window.BOOKS = window.BOOKS || {};
window.BOOKS['1'] = {"id": "1", "title": "Meretes Erindringer", "subtitle": "1949 – 1973", "years": "1949 – 1973", "frontispiece": {"name": "Merete Møller Christensen", "lines": ["Født den 12.11.1949 i Gl. Skagen", "Døbt Merete Møller Jensen i Sct. Catharinæ Kirke i Hjørring den 2.4.1950", "Min mor, Doris Møller Jensen, født Christensen den 9.3.1934 – død den 18.8.1993", "Min far, Erik Møller Jensen, født den 8.9.1924 – død den 21.8.1986", "Min mormor, Elna Christensen, født den 26.12.1901 – død den 21.11.1992", "Min morfar, Jens Christensen, født den 15.1.1892 – død den 31.3.1970", "Min farmor, Elisabeth (Lisbeth) Møller Jensen, født den 8.5.1897 – død den 9.7.1973", "Min farfar, Johannes Jensen, født den 6.11.1894 – død den 9.11.1962"]}, "dedication": "Disse erindringer er specielt tilegnet vores elskede søn Lars.", "forord": {"title": "Forord", "blocks": [{"type": "para", "text": "Disse erindringer er specielt tilegnet vores elskede søn Lars."}, {"type": "para", "text": "Kære Lars"}, {"type": "para", "text": "Jeg har af flere grunde længe haft lyst til at skrive mine erindringer."}, {"type": "para", "text": "For det første synes jeg selv, det er spændende at læse erindringer, og jeg ville gerne have læst mine forældres og bedsteforældres livshistorier. Derfor synes jeg, at du skal have chancen for at læse om min barndom og ungdom, og måske vil dine børn og børnebørn engang også finde det interessant."}, {"type": "para", "text": "Dernæst vil jeg gerne gennemgå den proces, det er at skrive. I skrivende stund har jeg produceret ca. 50 sider, og jeg har under processen tænkt meget på mine dejlige forældre, som desværre døde alt for tidligt, og på mine kære bedsteforældre. Jeg har gerne villet opleve min barndom og ungdom igen, for det var en dejlig tid."}, {"type": "para", "text": "På mit arbejde har jeg en kollega, Jørgen Haffgaard, som er noget af en skribent. Han har skrevet om sin barndom, og jeg har læst det med stor interesse. ”Du skal gøre det”, sagde han til mig en dag, ”du skal skrive om din barndom”, hvilket gav mig et ekstra skub."}, {"type": "para", "text": "Det, der så for alvor blev startskuddet, var, at far i foråret fik kræft. Heldigvis gik operationen godt og far blev erklæret rask, men det satte nogle tanker i gang hos mig. Tankerne sagde mig, at vi ikke lever evigt. Pludselig kan livet være slut, og man skal ikke udsætte til i morgen, hvad man kan gøre i dag."}, {"type": "para", "text": "Jeg håber, at du vil få fornøjelse af at læse denne bog, og at du også vil mindes dine bedsteforældre og oldemor, som alle holdt så usigelig meget af dig. Måske får du en dag lyst til selv at skrive dine erindringer."}, {"type": "para", "text": "Kærlig hilsen"}, {"type": "para", "text": "Mor"}, {"type": "figure", "file": "assets/images/p003_001.jpg", "caption": "Lars og Mor i en hyggestund, 1.10.2005 (Lars fylder 28 år)"}]}, "sections": [{"title": "Barndommen", "id": "barndommen", "chapters": [{"title": "Min fødsel", "blocks": [{"type": "para", "text": "Dagen før jeg blev student, sagde mor til mig: ”At du skulle komme til verden var ingen glæde, men du skal vide, at det blev det, for du har aldrig givet os andet end glæder”. Dette var et tegn på, at hun elskede mig højt, men det var også sandheden om, at min mor var meget ung, da hun fødte mig - kun 15 år. Jeg har aldrig fået hele sandheden om den periode, men jeg ved fra min moster og mine to onkler, at mor nok nærmest blev smidt ud hjemmefra. Det har jeg nu valgt ikke at tro på, for jeg forgudede mine morforældre og kunne ikke forestille mig, at de ville gøre noget sådant. Men min morfar kunne være streng. Han var anset og respekteret i Skæve, og på den tid bragte en sådan graviditet skam over familien. I hvert fald rejste min mor til Skagen, hvor min mosters kæreste boede, og hos hans mor, Bertha Støckler, blev jeg født. Min mor har ikke haft det let under graviditeten, idet hun og min moster arbejdede på hotel, hvor min mor blev hånet og drillet på grund af sin tilstand. I den periode var min moster hende en god støtte. Det positive var, at min far ikke rendte fra sine forpligtelser. De to holdt sammen indtil deres dages ende, og det er jeg lykkelig for."}, {"type": "figure", "caption": "", "page": 4, "file": "assets/images/p004_002.jpg", "dim": [860, 845]}, {"type": "para", "text": "Da jeg blev født, kom jeg straks på børnehjem i Hjørring, hvor jeg var i ca. 5 måneder, indtil jeg kunne blive bortadopteret, hvilket efter sigende var min morfars plan. De havde også fundet en god familie til mig i Frederikshavn, men den dag papirerne skulle underskrives, nægtede min mor at skrive under, og det på trods af, at mormor skulle have sagt: ”Se nu at få skrevet de papirer under, så vi kan få det overstået!” Det var hårde ord, og jeg kan egentlig godt forstå, at mor aldrig helt tilgav mormor. Det må have været en skrækkelig tid for min mor, først at være gravid under de forhold, så at gennemgå en svær fødsel, der varede i 3 dage, og dernæst at få sit barn taget fra sig. Hvor var det stærkt gjort af mor, at hun nægtede at give den underskrift, og hvor var det godt. Hvad der dernæst skete, har jeg aldrig fået fortalt, men min mor blev taget til nåde igen, og mine morforældre kom til at holde utroligt meget af deres svigersøn. Jeg blev hele husets kæledægge, og al sorg og ulykke blev vendt til glæde og lykke. Sådan husker jeg det i al fald, og min barndom var meget lykkelig."}]}, {"title": "Mine første år hos Mormor og Morfar", "blocks": [{"type": "figure", "caption": "", "page": 5, "file": "assets/images/p005_003.jpg", "dim": [860, 700]}, {"type": "para", "text": "Indtil min mor og fars bryllup den 24.10.1953 boede jeg hos min mormor og morfar, som ejede Skæve Konditori pr. Brønden i Vendsyssel. Dette var en slags kro, hvor der blev holdt et væld af fester. Min mormor havde også et bageri og en slikbutik samtidig med, at hun havde pensionærer. Min morfar var maler af profession, og gik ud og malede og tapetserede for folk. Jo, de var flittige og travle mennesker, men de havde også folk i arbejde. Min mor og far hjalp altid til, når der var bal om lørdagen. I 1962 kunne de på en sådan aften tilsammen tjene 100 kr., hvilket var mange penge dengang. Mor serverede og far ”stod i døren”, hvilket vil sige, at han tog imod billetter, når folk gik ind, samtidig med, at han var en slags udsmider, selvom jeg ikke rigtig kan se min far i den rolle. Han kunne nemlig ikke gøre en flue fortræd. Det kunne somme tider gå hedt til, når slagsmålene kom i gang. Våbnene var de bare næver eller en træsko, og det skete, at en mand røg gennem vinduet, hvis han havde danset for tæt med en anden mands kæreste. Så kunne han ligge udenfor og sunde sig, indtil han var tjenlig til at komme ind igen. Min største fornøjelse var at sidde på en stol ved siden af kakkelovnen i den store sal, når der blev spillet op til dans, og morfar gik rundt og strøede dansepulver på gulvet. Jeg kan se ham endnu, iført vest med urkæde og svingende pakken med pulveret, som skulle få ekstra gang i bentøjet. Hvor jeg dog elskede min morfar og han mig. I den tid jeg var hos mormor og morfar, arbejdede min mor ofte på hotel i Skagen sammen med moster Edith, som var 4 år ældre end mor. Moster blev gift med Eberhardt Støckler, også kaldet Onkel Ib, den 20. maj 1950, og de boede i Skagen til deres død. Far arbejdede som landbrugsmedhjælper på forskellige gårde, men han kom også selv fra en gård lidt uden for Skæve, nemlig Sillebak, hvorfor han altid blev kaldt Erik Sillebak. Min mor havde også to mindre brødre: Erik og Helge, født i henholdsvis 1937 og 1938, og mens jeg var på Konditoriet, boede de stadig hjemme. Helge fortæller, hvordan jeg lå ude i barnevognen uden tøj, helt nøddebrun, og hvordan de skiftedes til at løbe ud og se til mig. Og mormor var pludselig pavestolt over at have fået et barnebarn. Jeg var mine onklers trofaste følgesvend, da jeg fik lært at gå, men det tror jeg ikke, de havde noget imod. Da jeg var 2 år, lærte de mig at sige: ”Merete, 2 år, tisser i bukserne og bruger sut”. Og det gik jeg så rundt og sagde, selvom jeg ikke brugte sut. Ifølge mine onkler og andre i familien var jeg et meget nemt barn at passe."}, {"type": "figure", "caption": "Morfar med sine serveringspiger. Mor sidder til venstre.", "page": 5, "file": "assets/images/p005_004.jpg", "dim": [860, 592]}, {"type": "figure", "caption": "Moster og Ib den 20.5.1950", "page": 6, "file": "assets/images/p006_005.jpg", "dim": [542, 860]}, {"type": "figure", "caption": "Onkel Erik som soldat", "page": 6, "file": "assets/images/p006_006.jpg", "dim": [506, 507]}, {"type": "para", "text": "Moster og Ib den 20.5.1950 Onkel Erik som soldat For lille mig var Konditoriet et Eldorado, både mens jeg boede der og også senere, når jeg blev passet der i de lange sommerferier eller i weekenderne, når mor og far skulle hjælpe til ved ballerne. Paradoksalt nok kom jeg dog tit galt af sted, selvom jeg var meget stille og genert. Som 1½-årig fik jeg tredje grads forbrænding på halsen, da jeg væltede en primus ned over mig, og som 2-årig faldt jeg ud af et vindue. Sidstnævnte ulykke skete en dag, mormor stod og talte i telefon i en lille stue, der lå lavere end køkkenet. Jeg var kravlet op på køkkenbordet og sad ved et halvåbent vindue og legede med en underkop. Pludselig tabte jeg underkoppen ud af vinduet, og da jeg ville læne mig ud for at kigge efter den, faldt jeg ned i en kælderhals, forbi det vindue i den lille stue, hvor mormor stod og talte i telefon. Jeg kan forestille mig det chok, hun fik, da jeg fløj forbi. Da lægen kom (for anden gang den dag – han havde tidligere været der og fjernet en vorte på mig), blev han helt hvid i hovedet, for der stak noget op af kraniet. Var det mon hjernen, der var på vej ud? Heldigvis var det kun et stykke af underkoppen. Jeg fik forbinding om hele hovedet, men det var ikke sjovt for mormor, da hun skulle besøge mor på sygehuset, hvor hun var indlagt for basedow, og fortælle hende, hvad der var sket med mig. En anden dag, da jeg skulle rende efter mine to onkler, løb jeg lige ind i hjørnet af glasdisken i butikken og fik en stor bule i panden, og en dag, hvor jeg havde sovet til middag ovenpå med tyggegummi, som så havde klæbet mig fast til hovedpuden, faldt jeg ned af trappen, heldigvis med hovedpuden forrest, og sådan kunne jeg blive ved."}, {"type": "figure", "caption": "Her er jeg sammen med farmor og mormor i Konditoriets have", "page": 6, "file": "assets/images/p006_007.jpg", "dim": [418, 649]}, {"type": "para", "text": "Min mor og fars bryllup blev naturligvis holdt på Skæve Konditori efter vielsen i Skæve Kirke. Jeg var også med i kirken, hvor jeg sad sammen med min moster og onkel. Moster havde forsøgt at få mig på toilettet, inden vi skulle af sted, men uden held, sikkert fordi jeg var så spændt, for ”i da blywer mor, far og mæ jywt”, en sætning jeg på min dengang så ravjyske dialekt gik rundt og sagde hele dagen. Men hvad skete der, så snart vi kom ind i kirken: ”Moster, a ska’ tiss’!” Festen var vemodig for min morfar, for jeg gik rundt og sang ”Hele ugen alene, hu, hu, hu, hu”, som var en af slagerne dengang. Med den mente jeg, at nu rejste jeg, og så skulle morfar til at være alene."}]}, {"title": "Den første tid i Thorshøj", "blocks": [{"type": "para", "text": "Det var en spændende tid. Min far havde fået arbejde som lagerforvalter i Brugsen i Thorshøj, som ligger 10 km. fra Skæve, men der gik en rutebil, så vi kunne nemt komme derud, hvilket vi også gjorde næsten hver weekend. Vi havde lejet en lejlighed i Thorshøj i Villa Gydeje, som lå på hovedgaden i den lille landsby. Lejligheden var med skråvægge, der var lavt til loftet og meget hyggeligt, men mor havde nu også sans for indretning, så noget af hyggen var hendes fortjeneste. Vi boede til leje hos et ældre ægtepar, Jens og Kristine Jensen, som var barnløse, så de blev en slags ekstra bedsteforældre for mig. Jeg elskede at besøge dem, især husker jeg mine besøg sidst på eftermiddagen om vinteren, hvor vi holdt skumringstime. Måske var det for at spare på strømmen, at de sad i mørke, men for mig var det hyggeligt at sidde i halvmørket og sludre med de to for mig gamle mennesker. På et tidspunkt havde jeg fundet en af min fars drengebøger, som jeg gik i gang med at ”læse”. Det foregik på den måde, at jeg lod en finger glide hen langs linierne og lod så som om jeg læste. Den bog havde jeg med ned til Jens og Kristine, så når Jens læste avisen, sad jeg med min bog. Kristine havde næsten altid et hækletøj i hænderne, for hun hæklede for en forretning, de fineste babytrøjer, sokker og kyser i hvide, Mor og Far den 24.10.1953 gule, lyserøde og lyseblå farver. Det var mit arbejde at holde garnet, når hun skulle vinde det, men så var Jens jo også fri. Jens og Kristine havde telefon, som vi måtte benytte os af, og de havde badeværelse med badekar, hvorimod vi kun havde toilet og vaskekumme og måtte etagevaske os eller tage bad i en zinkbalje på køkkengulvet. Til højtiderne lånte vi badekarret, og jeg kan endnu dufte sæben, vi brugte. På et tidspunkt blev Jens syg, noget med prostata, og muligvis var det også det, han døde af. Jeg var ikke så gammel, og når nogen spurgte til Jens, sagde jeg gammelklogt, som jeg nu havde hørt andre sige: ”Det er galt med vandværket”, uden at have den ringeste anelse om, hvad dette betød. Da Kristine blev enke, fortsatte jeg naturligvis med at besøge hende, men det var nu ikke det samme, som da Jens levede. Hun fik TV før os, hvilket betød, at vi næsten hver aften kom på besøg for at kigge ind i dette møbel. Jeg husker, at vi bl.a. så Prinsesse Anne Maries bryllup med Kong Konstantin den 18. september 1964. Kristine havde efter sigende forventet, at Jens døde før hende, for hun skulle engang have sagt: ”Når dej ja’en af os dør, vil a te Skawi å bo”. Tømrermester Elbo Knudsen var en mester i at efterligne Kristine i denne fremtidsdrøm, som virkelig gik i opfyldelse: Kristine flyttede til Skagen midt i 60erne, hvor hun senere døde."}, {"type": "figure", "caption": "Mor og Far den 24.10.1953", "page": 7, "file": "assets/images/p007_008.jpg", "dim": [543, 860]}, {"type": "figure", "caption": "Vores lille trekløver i lejligheden, vinteren 1955", "page": 8, "file": "assets/images/p008_009.jpg", "dim": [423, 425]}, {"type": "para", "text": "Vores lejlighed var stor i mine øjne. Vi brugte altid bagtrappen, som var pæn og skinnende blank af fernis. Fortrappen brugte vi næsten kun, når vi skulle besøge Jens og Kristine, eller hvis mine veninder og jeg skulle lege med påklædningsdukker, som så kunne bo på de forskellige trappetrin. Når man kom op ad bagtrappen, var der en lille gang med en skunk, hvor der hang frakker med mølkugler og stod saltkar med flæsk. Det skete også, at vi fangede en mus i skunken, men så vovede jeg mig ikke derind i lang tid bagefter. Ved siden af gangen havde vi et lille toilet med vaskekumme, af nyere dato, så det var pænt. Fra gangen gik man ind i køkkenet, som havde blåmalede skabe og en lille klap, som vi trak ud, når vi tre skulle sidde i køkkenet og spise. Fra køkkenet gik vi ind i stuen, som havde kamin. Vi fyrede med koks, som vi hentede i kælderen i en metalspand. I stuen var der ét stort vindue ud mod hovedgaden og to små, og så var der kokostæppe på gulvet. Møblerne var af lakeret træ, der skulle poleres med jævne mellemrum, og på væggen hang den klassiske Sikker Hansen tegning af Davrepigen. Inden for stuen var soveværelset, hvor min lille mørkebrune tremmeseng stod under vinduet. Her var endnu en skunk, hvor jeg opbevarede meget af mit legetøj. Jeg fik først mit eget værelse ude ved fortrappen, da Per blev født, og jeg var 10 år. Det betød så, at huslejen steg lidt. Over for mit værelse var et andet lille værelse, som var Kristines, men som aldrig blev brugt. Jeg syntes, det var lidt uhyggeligt at komme derind, for der lå et grævlingeskind på gulvet. Jeg har altid været både fascineret af og bange for udstoppede dyr og skind. Min mormor havde en rævepels med hoved og hale i overskabet i sit soveværelse. Når hun tog den frem, gemte jeg mig under dynen."}, {"type": "para", "text": "Det værste, jeg vidste, var, når mor skulle vaske storvask, ca. en gang om måneden. Så lejede vi en halvautomatisk vaske- og vridemaskine hos købmanden, som leverede den i gården ved nedgangen til vaskekælderen. Hele dagen var sat af til denne aktivitet, hvor mor opholdt sig i kælderen, iført kittel og tørklæde bundet i nakken, og jeg hjalp til, så godt jeg kunne. Noget tøj skulle koges, og det foregik i gruekedlen. Noget andet tøj kom i vaskemaskinen, som så stod og kørte tøjet rundt i lang tid. Vi havde en stor tyk pind, som vi trykkede tøjet ned med fra tid til anden. Vaskebrættet var ikke helt gået af mode dengang, så det skete også at tøjet fik en tur på dette rillede bræt. Det krævede armkræfter. Det gjorde det også, når tøjet skulle igennem vridemaskinen. Senere blev vridemaskinen automatisk, så den bare skulle ”fodres”, men en dag, da Kristine vaskede storvask, fik hun armen i vridemaskinen. Jeg så det ikke men syntes, det lød drabeligt, da jeg bagefter hørte om det, og jeg kunne da også godt se, at armen var lidt flad. Den blev aldrig helt god igen."}, {"type": "para", "text": "Når tøjet så var tørt, skulle det lægges sammen. Sengetøj og duge skulle rykkes og stænkes, og det hjalp enten far eller jeg med. Det foregik oppe i stuen, og det må have støvet meget. Vi hev fat med begge hænder i hver sin ende og samlede tøjet til en lang pølse, som vi så rykkede frem og tilbage, i takt med hinanden – det var virkelig teamwork. Forinden havde mor rystet stænkeflasken over tøjet, så det kunne blive fugtigt og derved lettere kunne blive gjort glat. Når det var blevet tilstrækkeligt strukket, lagde vi det sirligt sammen, så det var klar til at blive rullet. I et andet kælderrum stod Kristines håndrulle, som vi gerne måtte bruge. Før jeg fik kræfter nok, var det far og mor, der rullede tøjet. Det skulle køres igennem rullen mange gange, inden det var glat og tørt. Rullen var et stort, tungt monstrum af jern. Der var to træklapper, man kunne slå ned til tøjet at hvile på, så det ikke umiddelbart ramte gulvet, og så var der naturligvis håndsvinget, som fik valserne til at køre rundt. Rullen var langt fra lydløs og frembragte nogle høje klagelyde, især hvis den trængte til at blive smurt. Jo, det var en lang proces fra det snavsede tøj til den kridhvide bunke af nyrullede duge og lagner, som kunne lægges i skuffen. Ikke så sært, at nogle brugte tøjet temmelig længe, inden det røg til vask. Mor var dog meget proper og forlangte det samme af os. Og hun var meget sirlig med tøjet og vaskeprocessen. Det tøj, der ikke blev rullet, blev strøget – med et enormt tungt strygejern, som ikke var termostatstyret. Man skulle derfor huske at slukke det efter endt brug. Hvis man glemte det, kunne det gå grueligt galt. Jeg mindes brune svedne mærker af strygejern i flere hjem, og der blev fortalt mange forfærdelige historier om strygejern, der kunne brænde igennem både bord og gulv og derved ende hos underboen og endda sætte ild til et helt hus. I starten af mine forældres ægteskab, hvor mor var hjemmegående det meste af tiden, strøg hun alt, om det så var undertøjet og stropperne i viskestykkerne og pudevårene. Senere droppede hun dette men blev alligevel ved med at stryge skjorter, selv om de var strygefrie. Denne strygemani har smittet af på mig, og jeg kan ligefrem til tider nyde det."}]}, {"title": "Mine første legekammerater", "blocks": [{"type": "para", "text": "Jeg var næsten 4 år, da vi flyttede ind, og jeg husker den første gang, jeg skulle ud og finde mig nogle legekammerater. Jeg holdt mig på min side af vejen, men på den anden side, lidt længere henne, fik jeg øje på nogle piger, som også havde fået øje på mig, men som troede, jeg var en anden, end den jeg var. ”Ellen, ka’ do lej’?” råbte de. På den måde kom vi i snak og indledte et varmt venskab, som varede hele barndommen. Den ene af pigerne, som hed Ulla, genoptog jeg forbindelsen med i 1993 efter en pause på 26 år. Pigerne kom fra to familier. Der var 6-årige Britta, som havde en storesøster Gunhild, Merete og Ulla leger med dukker på 8, der hed Inge-Lise og en lillebror på 2, der hed Jens Erik. Deres far var murermester N. Chr. Frost, og ham havde vi stor respekt for, selvom han var en lille mand. Han havde dog en vis portion humor, for i mine forældres gæstebog har han til min efterkonfirmation skrevet: ”Husk mit glas næste gang, Erik”, så far er sikkert kommet til at springe ham over. Det var også Frost, der en nytårsaften stod for at gemme mor og fars snapseflaske nede i Kristines have. Hans kone Rigmor var som regel flink og smurte tit rugbrødsmadder med puddersukker til os børn. Det var også Rigmor, der krøllede mit hår, når jeg skulle være fin. Det foregik med et gammeldags krøllejern, som blev varmet på komfuret og prøvet af på et stykke brunt papir, inden det kom i håret. Det skete, at jernet kom for tæt på huden, så der blev et rødt mærke. Man måtte også dengang lide for skønheden. I midten af 50erne byggede Frost et nyt hus til dem ved siden af det gamle. Denne i mine øjne enorme rødstensvilla med kælder var for mig meget imponerende. Og så var der 6-årige Ulla, hvis storesøster Gunhild var jævnaldrende med Inge-Lise. Gunhild var rødhåret og meget køn. Deres far var vognmand og hed Asger Skovmand-Jørgensen, en rar og fåmælt mand, som jeg husker siddende bag sit skrivebord inde i dagligstuen, ofte med en cigar i munden. Hans første kone var død, med hvem han havde nogle ældre døtre, Birte og Kirsten, som ikke boede hjemme mere. Dem så vi meget op til, og Ulla og Gundhild var stolte af deres halvsøstre og disses mænd og senere børn. Jørgensen havde så senere giftet sig med den 18 år yngre Magda, med hvem han først havde fået en søn, Gudmund, der desværre var død 7 uger gammel. Heldigvis fik de hurtigt Gunhild og 2 år senere Ulla. Jørgensen døde pludselig af et hjertetilfælde i 1966, 68 år gammel, men Magda lever endnu i Østervrå og fylder 90 år i sommer. Også Rigmor lever endnu og er ligeledes flyttet til Østervrå. Selvom Ulla og Britta var ældre end mig, blev de mine bedste legekammerater. Gunhild blev som ganske ung forelsket i en tysker, Dieter, med hvem hun blev gift kort tid efter sin fars død. De fik 3 børn, men Gunhild døde desværre af kræft i en alder af 38 år. Jeg husker, at jeg hos Frosts somme tider legede med to af Britta og Inge-Lises kusiner fra Thy, Lisbet og Sonja. I dag går vi til dans med Lisbet og hendes mand Svend, og de er blevet nogle af vores gode venner. Det var pudsigt den dag, vi fandt ud af, at vi havde leget sammen som børn. I sommer har jeg kontaktet Britta på mail, hvorefter vi talte 45 minutter sammen i telefonen. Det kunne være sjovt at mødes igen efter så mange år."}, {"type": "figure", "caption": "Gunhild, Merete og Ulla leger med dukker", "page": 9, "file": "assets/images/p009_010.jpg", "dim": [700, 451]}, {"type": "figure", "caption": "Merete 6 mdr.", "page": 10, "file": "assets/images/p010_011.jpg", "dim": [563, 550]}]}, {"title": "Mig selv", "blocks": [{"type": "para", "text": "Bagpå det første billede, der er taget af mig på et lammeskind hos fotograf Skræm Pedersen i Tårs, har min mor skrevet: ”Kære lille skat. Du blev født Lørdag den 12. Nov. Kl. 8 om Morgenen. En sød og kærlig lille Pige er du. Kærlig hilsen Mor og Far.” Da jeg var 1½ år, skrev mor: ”Du fik navnet Merete, det var Mor der bestemte det, vi håber du er tilfreds med valget.” Navnet Marianne havde også været på tale, men min farmor mente, at jeg så ville blive kaldt Majanne, et navn man sikkert vill have brugt i hendes unge dage. Da jeg var 4 år, skrev mor: ”En kær og rolig lille Pige, som giver os mange dejlige Timer.” Jeg lagde mit tøj Merete 6 mdr."}, {"type": "figure", "caption": "Jeg holder tale ved mormor og morfars", "page": 10, "file": "assets/images/p010_012.jpg", "dim": [860, 611]}, {"type": "para", "text": "pænt sammen om aftenen, når jeg tog det af, og hvis jeg rodede, ryddede jeg altid op efter mig. Men jeg var meget stille og genert, hvis der var voksne til stede, som jeg ikke kendte. Jeg var tit med mine forældre i byen, for de kunne bare placere mig i en stol, så sad jeg der hele aftenen eller lagde mig et sted for at sove."}, {"type": "para", "text": "Jeg havde også mine idéer. Jeg kunne ikke have tøj på, der kradsede, såsom uldne undertrøjer, og det har fulgt mig lige siden. Det var ikke altid, min mor og mormor forstod, hvor hårdt det var for mig med disse væmmelige beklædningsgenstande, så de gav mig det på alligevel. Noget, der står klart i min erindring, er en råhvid strikket kjole med røde rosenborter for neden. Den havde de fået strikket til mig til en familiefest, da jeg var et år gammel."}, {"type": "figure", "caption": "Mor så stolt ud", "page": 11, "file": "assets/images/p011_013.jpg", "dim": [860, 615]}, {"type": "para", "text": "Der flød mange tårer, inden det lykkedes dem at få den ned over hovedet på mig. Nej, må jeg så bede om den lyserøde taftkjole, jeg havde på til mine forældres bryllup, eller den lyseblå ditto jeg fik senere. De var både søde og behagelige at have på. Dette mareridt med uldtøj besluttede jeg, at mit barn aldrig skulle udsættes for. Anderledes blød og lækker var den hvide kaninpels, man kan se mig i på billeder fra 1952. På et tidspunkt blev jeg godt og grundigt træt af at gå i røde sko. Når jeg fik nye sko, skulle de altid være røde - det bestemte mor. Jeg husker det år, jeg fik nyt ”pinsesnit”, som mor kaldte det: rød lægget nederdel, hvid bluse, blå blazer, rød baret og naturligvis røde sko. Hvor var jeg chik. Mor ville have, at alting passede sammen. Senere, da engelsk vandt indpas i det danske sprog, kaldte hun det at ”matche”. Men de røde sko har nok betydet, at jeg næsten aldrig som voksen har haft den farve i sko."}, {"type": "figure", "caption": "Merete 3 år i hvid kaninpels", "page": 11, "file": "assets/images/p011_014.jpg", "dim": [499, 572]}, {"type": "figure", "caption": "Merete i ” pinsesnit”", "page": 11, "file": "assets/images/p011_015.jpg", "dim": [661, 451]}, {"type": "para", "text": "Merete 3 år i hvid kaninpels Merete i ” pinsesnit” Et år kom de røde sko dog til ære og værdighed. Det var i 1956, da mor til den årlige fastelavnsfest på Thorshøj Hotel havde bestemt, at jeg skulle klædes ud som Rødhætte. Hun havde syet flot kostume med kyse og halvmaske, og på armen havde jeg en kurv med vin og småkager. Behøver jeg at nævne, at jeg vandt førstepræmien. Jeg havde også fået den idé, at jeg ikke ville spise brun sovs – jeg syntes, det var ulækkert at få denne brune klæbrige masse på tallerkenen, blandet med kartofler og kød, som helst skulle ligge ordentligt og adskilt. Desuden havde en af min mormors pensionærer bildt mig ind, at man fik brune pletter i nakken af at spise brun sovs. Mælk kunne jeg heller ikke lide, men lægen beroligede mor med, at når jeg spiste ost og drak kærnemælk, var der ingen fare på færde. I dag kan jeg spise brun sovs, men jeg drikker ikke mælk, og jeg har aldrig kunnet lide mandler og nødder. Kaffe lærte jeg aldrig at drikke, men mor gjorde nu heller ikke noget for at lære mig det. I stedet drak jeg te, som ikke var så almindeligt dengang og ofte blev fulgt til dørs af følgende kommentar: ”Er du syg?” Jeg lærte at sige, at det var bedre at forebygge end at helbrede."}, {"type": "figure", "caption": "Her er jeg som Rødhætte i 1956", "page": 12, "file": "assets/images/p012_016.jpg", "dim": [624, 860]}, {"type": "para", "text": "Længe inden jeg fik lært at læse, lærte jeg en historie udenad. Det var en julefortælling, som hed ”Nisse Næsvis”, og som startede med: ”Der var engang en rigtig nissefamilie, nissefar, nissemor og tre små nissedrenge.” Når der så kom gæster, skulle jeg optræde med dette nummer. Jeg satte mig i lænestolen med teksten foran mig, og så ”læste” jeg helt fejlfrit, til alles store beundring. Historien har jeg gemt som et kært minde fra dengang. Noget, jeg dog ikke kunne prale med, var min evne til at cykle. I 1956 fik jeg min første tohjulede cykel. Jeg var gået fra den trehjulede til en stor, flot rød pigecykel, hvor jeg knap nok kunne nå pedalerne, og der var ikke noget, der hed støttehjul. Jeg har aldrig været særlig modig, og jeg var hunderæd for, at mor skulle give slip på cyklen og mig, når hun var ude og prøve at lære mig at cykle. På billedet nedenunder har jeg godt fat omkring en telefonpæl af frygt for, at cyklen skal vælte med mig. Der gik lang tid, inden jeg fik lært at cykle. Jeg turde simpelthen ikke, så når jeg skulle alene ud med cyklen, trak jeg den. En dag mødte jeg en bekendt, som spurgte:”Nå, har du ikke fået lært at cykle endnu?” ”Jo, da”, svarede jeg, og det var heller ikke helt løgn – jeg turde bare ikke. ”Må jeg se?” spurgte vedkommende, og så var der ingen vej udenom. Jeg skulle jo nødig tages i at lyve. Jeg bed tænderne sammen og satte mig op på dyret, og pludselig kunne jeg cykle. Jeg kunne næsten ikke vente med at komme hjem og fortælle mor og far den glædelige nyhed."}, {"type": "figure", "caption": "", "page": 12, "file": "assets/images/p012_017.jpg", "dim": [449, 651]}]}, {"title": "Brugsen m.m", "blocks": [{"type": "para", "text": "Da vi flyttede til Thorshøj, havde selvbetjeningsbutikkerne ikke gjort deres indtog endnu. Personalet stod trofaste og servicemindede bag disken, ofte med en blyant bag øret, og spurgte: ”Hvad sku’ der være?” Mange af varerne blev vejet og kommet i poser, fx mel, sukker og gryn. Kaffebønnerne blev malet, og krydderierne blev opbevaret i små skuffer bag disken, hvorfra de blev hældt i små poser. Den krydrede duft, der kunne finde vej til ens næsebor, er for længst forsvundet i nutidens kæmpemæssige lugtfri supermarkeder, hvor rækker af nedkølede og indpakkede produkter er resultatet af en revolution inden for fødevareindustrien. Alle havde dengang en brugsbog, som varerne blev skrevet ind i, og hver måned til den første betalte man så det, man skyldte. I 1955 kunne man for en tikroneseddel gå fra Brugsen med tungt indkøbsnet. For pengene fik man ¼ kg kaffe, 2 kg stødt melis, 1 kg mel, en stor hvidtøl og to pilsnere – og det syntes man var dyrt. 5 kg kartofler kostede 2 kr. og 1 kg smør 7,46 kr. Sammenlignet med det var en lønmodtagers timeløn 4,85 kr. i 1954."}, {"type": "figure", "caption": "", "page": 13, "file": "assets/images/p013_018.jpg", "dim": [860, 851]}, {"type": "para", "text": "Mit store nummer var at komme på besøg hos min fars chef, brugsuddeler Harald Møller. Især hvis alle de ansatte var inviteret. Da far startede i Brugsen, var der, foruden ham og uddeleren, en førstemand og to kommiser samt en lærling, og de holdt altid sjov, så over for dem var jeg lidt mere fri. De navne, jeg husker i hele perioden, er 2 gange Vagn, 2 gange Frede, Sørensen og Borup, og lærlingen Per. Førstekommiserne var højt på strå og blev kaldt ved efternavn. Senere, da Møller gik på pension, blev Borup uddeler."}, {"type": "para", "text": "Emilie og Harald Møller havde to døtre, Elinor og Aase, men de havde også haft en søn, Henning, som var blevet kørt ihjel som 12-årig. Det gjorde indtryk på mig at høre om, hvordan han under en cykeltur, hvor han havde siddet bagpå tjenestepigens cykel, var faldet af og blevet kørt over af en bil lige uden for Brugsen. Elinor var single, mens Aase var gift med proprietær Frede Nielsen, som efter sin far havde overtaget gården Galtrup uden for Thorshøj. De havde to søde drenge, som var yngre end mig, Flemming og Finn, og fik den 24.7.1959 en pige, som fik navnet Birgitte. Desværre døde Aase af kræft i en alder af 37 år. Frede nåede at være gift i alt tre gange. Hans anden kone Bodil døde på tragisk vis en aften, hvor hun gik alene fra fodermesterhuset til stuehuset i Galtrup. På den korte strækning faldt hun ned i en tom ajlebeholder og var dræbt på stedet. Frede kom, trods sin anden store sorg, videre og blev gift med den noget yngre Aase, som drev en stor vognmandsforretning i Dybvad efter sin afdøde mand. Jeg husker Frede som en charmerende, veltalende og meget behagelig mand, så det var ikke så sært, at han var eftertragtet. Han drev det vidt i politik og var i flere år borgmester i Sæby. Frede døde for få år siden."}, {"type": "figure", "caption": "Min yndlingsplads hos Borups", "page": 13, "file": "assets/images/p013_019.jpg", "dim": [602, 860]}, {"type": "para", "text": "Vi kom altid hos uddelerens, som boede ovenpå butikken, hvert år den 24. december til frokost. Da var hele personalet med familier indbudt samt uddelerens egne børn med Min yndlingsplads hos Borups familie. Min mor og jeg kom om formiddagen, mor for at 4 år gammel hjælpe fru Møller i køkkenet og jeg for at pynte deres juletræ. Nogle år nåede jeg at pynte 4 juletræer, for foruden Møllers og vores eget pyntede jeg også Kristines og mormors. Når så butikken lukkede til middag, kom uddeleren og personalet op for at indtage frokosten sammen med os ved det lange bord i spisestuen med det flotte parketgulv. Det var meget højtideligt, især når vi bad bordbøn og sang ”Julen har bragt” og ”Dejlig er jorden”, som Møller var forsanger for. Han var en mand, man havde respekt for, men han fik ofte det glatte lag, når kommiserne var samlet hos mor og far. Efter frokosten samledes vi alle i dagligstuen, hvor vi fik vores julegaver. Og hvis så sneen dalede ned, når vi gik hjemad, var julestemningen i hus, allerede inden det var juleaften."}, {"type": "para", "text": "En anden tradition, vi havde med Brugsen, var sidste søndag før jul. Da var alle ansatte med familier inviteret til Ålborg, hvor butikkerne holdt åbent fra kl. 16. På landet var alt lukket om søndagen dengang, også søndagen før jul. Vi havde naturligvis ikke bil, så mor, far og jeg kørte som regel med hr. og fru Møller i deres store Humber Hawk, en engelsk model, som for mig var på højde med et dollargrin. Efter far fik kørekort, skete det også, at vi lejede en bil uden fører, en Folkevogn, hvor der var et rum bagved bagsædet til mig at ligge i. Det gav jo også lidt plads på bagsædet til en ekstra passager. Vognmand Jørgensen fik i 1961 en ny lyseblå udlejnings Folkevogn, som vi til tider lejede. Vi ankom til Ålborg kl. 15 og gik så på Konditori Kirstine og drak chokolade og spiste kager. Vi var derfor klar, To gange Frede bag disken til butikkerne åbnede. Mor havde som regel købt de fleste julegaver på det tidspunkt, så vi manglede kun nogle få stykker og skulle derfor ikke stresse men kunne gå og hygge os, for vi havde kun ca. 2 timer at handle i. For øvrigt eksisterede ordet ”stress” ikke dengang. Et år var jeg med til at købe min egen julegave uden at vide det. Mor var god til at bluffe, så hun bildte mig bare ind, at hun skulle købe en gave for en bekendt, og spurgte mig, hvad jeg syntes. Jeg husker ikke mere, hvad det var, men jeg gjorde store øjne, da jeg lukkede gaven op juleaften. Kl. 18 skulle alle mødes og spise middag på det fine Hotel Phønix i Ålborg, alt sammen for Møllers regning. Første gang, vi var med, havde jeg fået strenge formaninger af mor om at opføre mig pænt, og hun havde fortalt mig alt om tjenerne og deres arbejde, hvilket jo ikke var svært, fordi hun selv var servitrice. At min far så et år kom hjem med en af restaurantens servietter i lommen i den tro, at det var hans lommetørklæde, han havde puttet i lommen, var en helt anden sag. Min mor blev meget flov, vaskede, stivede og strøg servietten og sendte den retur med en stor undskyldning. Kl. 20 havde Møller så bestilt enten teater- eller biografbilletter til alle, og det var som regel et julestykke, vi så, fx ”Jul i den gamle Købmandsgård”. For mig var denne dag årets højdepunkt, som bidrog til den perfekte julestemning."}, {"type": "figure", "caption": "To gange Frede bag disken", "page": 14, "file": "assets/images/p014_020.jpg", "dim": [424, 399]}, {"type": "figure", "caption": "Ålegilde hos mor og far. I midten er det førstekommis Tage Sørensen og mig.", "page": 14, "file": "assets/images/p014_021.jpg", "dim": [723, 475]}, {"type": "para", "text": "Mine forældre lagde tit lejlighed til, når der skulle festes sammen med kommiserne, for med undtagelse af førstemanden, som var gift, boede de alle på værelse. Det værste var, hvis jeg blev lagt i seng, inden de kom. Så kunne jeg ligge der og høre, hvordan de morede sig uden mig. Det skete så, at en af kommiserne, en stor og ikke særlig køn, men utrolig rar fyr ved navn Vagn (Sørensen) kom ind og læste godnathistorie for mig. (Vagn havde en karakteristisk dyb stemme og et grin, som han ofte benyttede – noget i retning af ”høhø-hø”). Ofte var brugsuddelerens chefen. De holdt tit ålegilder og spillede ved siden af far. Mor sidder yderst til højre. ”mousel”."}, {"type": "figure", "caption": "En munter aften hos mor og far sammen med kom- ved siden af far. Mor sidder yderst til højre.", "page": 15, "file": "assets/images/p015_022.jpg", "dim": [860, 615]}, {"type": "para", "text": "En aften – jeg har vel været 5 år - havde jeg fået lov at være oppe, og jeg hyggede mig ved bare at sidde og høre de voksne snakke. Lidt gammelklog blev man vel som enebarn med en hjemmegående mor. Førstekommisen Borup og hans gravide kone Grethe var der også, og da de sagde godnat til mig, spurgte Borup mig spøgende, om jeg da ikke ville med ham hjem og sove. ”Nej tak”, kom det prompte fra mig, ”a ska’ in ha’ min figur ø’lå (ødelagt)”. Den morede de sig meget over, men jeg forstod naturligvis ikke hvorfor."}, {"type": "figure", "caption": "Far fejrer sin 30-års fødselsdag den 8.9.1954. Forrest skimtes far ved siden af Borups gravide kone Grethe.", "page": 15, "file": "assets/images/p015_023.jpg", "dim": [424, 426]}, {"type": "para", "text": "Som sagt var uddeler Møller en bestemt herre og meget humørsyg, hvilket hans personale tit måtte lide under. Men samtidig respekterede de ham, og han kunne da også være noget af det mest elskelige. Hans kone Emilie, som han kaldte Mille, men som vi jo kaldte fru Møller og i starten sagde De til, var altid det samme rare menneske, og hun har bestemt heller ikke haft det let med ham. Som uddeler tilhørte de det bedre borgerskab i byen sammen med mejeribestyreren, bankbestyreren, skolelæreren og præsten. Dem var man på efternavn med og sagde De til. Næst i hierarkiet kom de forretningsdrivende, håndværksmestrene og de store gårdejere. Dette var naturligvis først noget, jeg lærte, da jeg kom i skole og i klasse med børn fra alle samfundslag. Der var klasseforskel dengang. Selvom min far nok rangerede på niveau med arbejderne, som dog boede i arbejderboliger, yndede jeg at sige, at han var lagerforvalter – ikke lagerarbejder, som han jo egentlig var til at begynde med. Lidt snobbet var man jo."}, {"type": "figure", "caption": "Merete og Lisbet på vej i skole,", "page": 16, "file": "assets/images/p016_024.jpg", "dim": [675, 401]}, {"type": "para", "text": "Min bedste veninde i skolen var Lisbet (Elisabet) Ejlersen, datter af autoriseret elinstallatør Lau Ejlersen og fru Aase, som jeg naturligvis af mor havde fået besked på at kalde fru Ejlersen og sige De til. Her bagefter kan jeg jo godt se, at de var ganske almindelige mennesker, men det, at de havde folk i arbejde, også rengøringshjælp, at de havde to biler og telefon, og at de af naturlige årsager var de første i byen til at anskaffe sig et 17 tommer TV, gjorde, at jeg mente, de måtte være rige. Derfor kunne jeg da også have bidt tungen af mig selv en dag, hvor vi legede hos Lisbet. Vi stod på hovedet op ad en dør i stuen, og pludselig er der en der kilder mig. I den tro, at det er Lisbet, råber jeg: ”Hold op! Du er ikke rigtig klog!” (Hos Lisbet talte de ikke vendelbomål, så jeg forsøgte at tale som dem). Til min skræk så jeg, at det var Lisbets mor, der stod der. Hun blev naturligvis ikke stødt over mit udbrud, men jeg var meget skamfuld og skulle i hvert fald ikke have sagt noget om det derhjemme. Vi legede mest hos mig, og mor var altid glad, når jeg havde Lisbet på besøg. De to gik godt i spænd sammen. Lisbet havde en 3 år yngre søster, Bente, som senere blev gift med borgmesterens søn Flemming. Lillebror Ejler kom til verden, da vi gik i 2. klasse, så da blev det ekstra spændende at gå med Lisbet hjem. Lisbet var også noget særligt, fordi hun var født i Buenos Aires, Argentina. Hendes forældre var emigreret men besluttede sig for at rejse tilbage til Danmark, da Lisbet var ganske lille. Under hjemrejsen gik skibet ned, men heldigvis reddede de livet ved at svømme i land. Når Lisbet fortalte, hvordan hendes far havde svømmet med hende på ryggen, sad vi måbende og lyttede. Det var godt nok spændende."}]}, {"title": "Tysklandstur", "blocks": [{"type": "para", "text": "Da jeg var 5 år, kom jeg på min første udlandsrejse – til Husum i Tyskland. Min moster og onkel havde købt en Folkevogn, og den skulle luftes. De inviterede os tre med til Tyskland for at besøge nogle af deres venner, som boede i Husum. Far sad på forsædet ved siden af onkel Ib, som var den eneste, der på det tidspunkt havde kørekort, og vi tre piger sad på bagsædet med mig i midten. Jeg havde lige lært at strikke og havde til turen fået en aflang grøn laktaske til strikketøj, så jeg kedede mig ikke, hvilket jeg for øvrigt aldrig gjorde. Den familie, vi besøgte i Husum, havde nogle drenge og en pige, der hed Renate. Hun var lidt ældre end mig, så jeg så beundrende op til hende. Hvordan vi kommunikerede, husker jeg ikke, men det gik vist meget godt. Faderen, Max, talte dansk, så han har nok hjulpet, når det brændte på. Min moster og onkel kunne lidt tysk, og jeg tror også, min far kunne forstå noget – han havde jo taget Almindelig Forberedelseseksamen på Østervraa Realskole i 1940."}, {"type": "para", "text": "En dag til frokost bad jeg min mor om at række mig osten, som på vendelbomål hedder ”wost”. Vores tyske venner troede, jeg sagde ”wurst” og rakte mig spegepølsen. Det morede vi os meget over. Det lykkedes mig, foruden ordet ”wurst”, også at lære andre tyske ord, så da vi kom hjem, pralede jeg med, at nu kunne jeg snakke tysk. Tysk har dog ikke senere haft min helt store interesse. På vej hjem fra Tyskland skulle vi en aften finde et sted at sove, men alt var optaget. Det endte med, at vi tilbragte natten i Folkevognen, en vist noget ubekvem oplevelse for de voksne. Min mor ytrede i hvert fald senere, når hun fortalte om Tysklandsturen til gud og hver mand, at hun ”hellere ville have haft et føl på tværs” end at have tilbragt natten i automobilen."}]}, {"title": "På hospitalet", "blocks": [{"type": "para", "text": "Jeg er født skeløjet, har bygningsfejl og stærkt nedsat syn på højre øje, så meget af min barndom har jeg tilbragt i øjenlægens venteværelse, for dengang kunne man sidde en hel dag og vente på, at det blev ens tur. Det var dog først som 17-årig, at jeg fik briller og alt blev klart og tydeligt for mig. Som 5-årig blev jeg indlagt på Hjørring Sygehus for at få mine øjne rettet. Det hed sig, at mit ene øje skulle vendes, og jeg forestillede mig, at de ligefrem tog øjet ud og vendte det. Hvad de bare ikke havde fortalt mig var, at jeg, når jeg vågnede op efter operationen, ville have bandage for begge øjne. Sikkert for at give øjnene ro. Jeg blev derfor ude af mig selv og gik i panik, da jeg vågnede op og var ”blind”. Ja, jeg græd så meget, at de skønnede, at de hellere måtte fjerne forbindingen, fordi for mange tårer kunne skade øjnene så kort tid efter operationen. I stedet fik jeg klap for det ene øje og lignede en sørøver, men det syntes jeg var sejt. Jeg var på sygehuset i 14 dage, og mor kom hver eftermiddag i besøgstiden. I weekenden var far også med. De tog rutebilen fra Thorshøj til Hjørring, en tur på 25 km. Jeg var ikke ked af at være der, men det skyldtes de daglige besøg, som jeg lå og glædede mig helt vildt til. Jeg husker, at mor havde små gaver med fra venner og bekendte, såsom malebøger og farver, glansbilleder og påklædningsdukker. Det værste var, når sygeplejersken kom og sagde: ”Besøgstid forbi”. Så vidste jeg, hvad klokken var slået, og mor skulle gå. Den dag, jeg blev udskrevet, var en festdag, takket være mors kreativitet. Da jeg kom hjem i lejligheden, havde mor inviteret mine legekammerater (Frosts piger og Jens Erik, Jørgensens piger og en større pige, der hed Solvejg). Legen den dag skulle hedde ”Sygehus”. Vi skiftedes til at være patienter og læger/sygeplejersker, og hele stuen var omdannet til en hospitalsstue. Mor havde fundet forskellige remedier, og de, der ikke lignede, forestillede vi os bare hvad var – fantasien fejlede ikke noget. Mors blå tykmælksskåle tjente som bækkener, og med kødhammeren kunne vi tjekke reflekserne. Vi legede hele dagen og havde det herligt, men til aften havde mor været mindre heldig: Hun ville lave noget rigtig lækkert og havde derfor købt lammekoteletter. Det er både første og sidste gang, jeg har smagt den ret, og siden den tid har jeg ikke brudt mig om lammekød. Jeg kan endnu smage sovsen, som smagte af uld. Det var, før man begyndte at bruge hvidløg i madlavningen. Året efter måtte jeg på sygehuset igen til endnu en øjenoperation, som var mindre end den første, og efter den tid har jeg ikke været skeløjet – næsten ikke."}, {"type": "figure", "caption": "Min 5-års fødselsdag. Yderst fra venstre er det Lissie, det Solvejg, Gunhild, Ulla og Britta.", "page": 17, "file": "assets/images/p017_025.jpg", "dim": [414, 400]}]}, {"title": "Fødselsdage", "blocks": [{"type": "para", "text": "Mor gjorde altid meget ud af min fødselsdag, og jeg fik fine gaver. Inden jeg begyndte i skolen, var der en fast skare bænket omkring spisebordet til denne årlige begivenhed: Ulla, Britta, Gunhild, Inge-Lise, Jens Erik og Solvejg. Det år, jeg blev 5 år, var Lissie Frederiksen, barberens yngste datter, uvist af hvilke årsager, også inviteret med. Andre tilløbere var tømrermester Jørgensens datter, Lisbeth, som var et år ældre end mig, og Lone Beck, som var 6 år ældre end mig og datter af Ellen og Calle, som var mine forældres venner. Vi fik altid kakao og boller samt bager Christiansens lækre brunsviger kagemand med slik. Jeg blev fotograferet, lige når jeg skulle skære halsen over på kagemanden, og vi skreg. Bagefter legede vi forskellige lege, som mor havde været med til at arrangere. Jeg husker det år, vi opførte ”Prinsessen på ærten”. Jeg skulle naturligvis være prinsessen, fordi jeg havde fødselsdag, og jeg lå på Her er vi blevet lidt ældre sofaen ovenpå alle de vattæpper og dyner, mor kunne fremtrylle. Og nederst lå selvfølgelig en ært, for det skulle gå rigtigt til. Nogle af de gaver, jeg fik af veninderne, har jeg stadig: lommetørklæder med fine motiver, tallerkner med ditto og sorte mokkakopper, som jeg jo samlede på. I 1962 gav vi 2 kr., når vi skulle til en venindefødselsdag."}, {"type": "figure", "caption": "Her er vi blevet lidt ældre", "page": 18, "file": "assets/images/p018_026.jpg", "dim": [860, 627]}, {"type": "figure", "caption": "Beck.", "page": 18, "file": "assets/images/p018_027.jpg", "dim": [860, 628]}]}, {"title": "Mine forældre", "blocks": [{"type": "para", "text": "Min mor og far var meget forskellige, men de supplerede hinanden rimelig godt. Mor var den udadvendte og snakkesalige, som hurtigt kunne tage beslutninger og gerne ville bestemme over min far og mig og alle mulige andre. Jeg tror, at hendes tidlige graviditet havde gjort hende meget moden, og det, at hun gerne ville bestemme, var måske et udslag af, at hun var blevet kanøflet i den svære tid, hvor hun ventede mig. Nu skulle hun tage revanche, og hun havde fundet en mand, som helst var fri for at tage beslutninger."}, {"type": "figure", "caption": "Her er trekløveret fotograferet hos Stella Nova i", "page": 19, "file": "assets/images/p019_028.jpg", "dim": [837, 860]}, {"type": "para", "text": "Mor var oftest sød og rar, men hun kunne også vende vrangen ud, og så var hun ikke rar at være i stue med. Så havde jeg ondt af far. Men når hun skældte ud, gik han bare. Han var næsten umulig at komme op at skændes med, men til gengæld kunne han gå i flere dage uden at sige noget, og det må også have været strengt for mor. Det var dog ikke så tit, der var krise, men når det skete, blev jeg frygtelig ked af det. Jeg ville have harmoni i familien, og ingen skulle være uvenner. Sådan har jeg det stadigvæk. Men der var ingen tvivl om, at de to elskede hinanden højt. Jeg hadede, når mor sov til middag, som hun gjorde hver dag i en stol i stuen. Så skulle jeg være musestille, og hvis jeg havde legekammerater på besøg, kunne hun finde på at sende dem hjem. Det syntes jeg var flovt, så jeg undgik oftest at have besøg lige over middag. Noget andet, jeg også hadede, var at gå ærinder. Dengang hentede vi mælk på mejeriet i flasker, som vi selv havde med. Mejeriet åbnede tidligt og lukkede kl. 9.30, så når mor om morgenen stod ved min seng (det var, før jeg begyndte i skolen), vidste jeg, hvad hun ville: ”Du skal op efter mælk!” Hvor jeg hadede det. Det var oppe i den anden ende af byen, og der var langt for mine korte ben. Men jeg protesterede naturligvis ikke – det gjorde man ikke dengang. Jeg blev bare sur og mut. Mine forældre røg meget, og det var altid mig, der blev sendt efter cigaretter oppe hos tobaks- og træhandler Wrensted, knap så langt som op til mejeriet. De ærinder havde jeg ikke så meget imod, for hr. og fru Wrensted var et par hyggelige ældre mennesker, og der faldt tit en pinocchiokugle eller to af. Min mor røg Prince, så der er røget mange 10-styks pakker Prince hen over disken i Wrensteds butik. Somme tider prøvede hun at holde op med at ryge, men så var hun ikke til at holde ud, og det endte med, at jeg tryglede hende om lov til at hente en pakke cigaretter hos Wrensted. Mor undskyldte altid sit cigaretforbrug med, at det var tante Karen, der havde lært hende at ryge i en alder af 13 år. Dengang var det acceptabelt, måske endda velset, at ryge. Der fandtes ingen røgfri områder, og når der blev holdt fest, opfordrede man ligefrem gæsterne til denne aktivitet ved at ”lade røg gå rundt” efter retterne. Så kunne gæsterne frit forsyne sig med cigaretter, cerutter og cigarer. Når man kom ind i et festlokale, var det nødvendigt at skære sig igennem røgen. Kun ved særlige lejligheder er der blevet budt røg rundt hos mine forældre, for mor mente godt, gæsterne kunne ryge deres egne cigaretter. For øvrigt ville det have været en ekstraudgift, der skulle have været taget af husholdningspengene, som var små. Min far, derimod, købte sine cigaretter selv. Han kunne ikke drømme om at ulejlige mig - det lod han mor om. Han var det stille vand med den dybe grund. Jeg har ofte spurgt mig selv, hvorfor han var så svær at nå ind til. Jeg har fået fortalt, at da han blev født med en defekt højre hånd, hvor der manglede det yderste af 4 fingre, skulle nogen have sagt til min farmor, at han nok aldrig blev til noget med sådan en hånd. Det troede hun så på i mange år, og det har måske smittet af på ham selv, for han havde ikke megen selvtillid. Han var meget beskeden og pralede aldrig, og han gjorde aldrig nar af folk. Mor, derimod, kunne godt kritisere og stikke lidt til folks særheder, men hun var ret underholdende, når hun gjorde det. Hun var også meget klog, og jeg har tit tænkt, at hun sagtens kunne have taget en studentereksamen, hvis hun havde haft muligheden. Far var boglig dygtig og fik da også lov at få en eksamen. På grund af hans hånd, kunne han have fået økonomisk hjælp til at læse til lærer, men han ville hellere på det tidspunkt være landmand. Måske havde han heller ikke haft psyke til det andet. Men han var god i alle former for gættekonkurrencer og krydsord. På trods af sit fysiske handicap lavede han mange ryatæpper, da disse i 60erne blev moderne, og senere lavede han papirklip, især til jul. Det er ikke jul hos os uden fars røde juleklip i vinduerne. Far var sportslig aktiv, idet han en gang om ugen spillede badminton sammen med kommiserne i gymnastiksalen i Thorshøj Skole. Senere spillede han sammen med Elbo Knudsen, Jørgen Jensen og tandlæge Bornæs i Østervrå. Derudover spillede han fodbold og var ude at spille kampe mange weekends. Da han blev for gammel til almindelig fodbold, kom han på oldboys holdet. Jeg ved, at far var meget vellidt i Brugsen og værdsat af uddeler Møller. Han var rigtig dygtig til at udføre de hverv, han blev sat til, men han var ikke selv nogen god leder, fordi han ikke kunne få sig selv til at bede andre om hjælp - så ville han hellere gøre tingene selv. Han blev dog i en periode valgt som formand for Brugsen. Jeg ved, at han elskede mig højt, men han gav aldrig åbenlyst udtryk for det. Det kom frem på anden måde, som når vi fx en sjælden gang tog rutebilen til Ålborg for at købe tøj. Så gik vi med hinanden i hånden, og en gang, hvor jeg måske har set lidt trist ud, spurgte han mig: ”Er der noget, du gerne vil have, lille skat?” Jeg var målløs, for sådan havde han aldrig talt til mig før, men jeg var samtidig glad. En gang var jeg stand-in for min mor. Hendes fætter Brian skulle giftes med sin Birthe, og mor og far var inviteret med. Det var om sommeren, så mor var i Skagen og arbejde på Brøndums Hotel og kunne derfor ikke være med. Jeg var vel 7 år på det tidspunkt og stor nok til at kunne opføre mig pænt, så jeg fik syet fin lyseblå nylonkjole og glædede mig enormt. Det var en stor dag, da jeg gik ud af kirken med far i hånden. Jeg ved ikke, hvem der var mest stolt, men jeg syntes min far så mægtig flot ud i sin bryllupssmoking. Heldigvis var der andre børn med, så det blev en rigtig dejlig dag. Far kunne ikke drømme om at skælde mig ud. Det hårdeste, han nogensinde har sagt til mig, var en aften, hvor vi var kommet i seng, og jeg lå og kørte fingrene irriterende mange gange hen over tremmerne i min seng, fordi jeg ikke kunne falde i søvn. Pludselig lød det fra far: ”Hold lige op med det!” Så kan det nok være, der blev stille. Da det jo var før TV vandt indpas, tilbragte far og jeg mange aftner med at spille Matador og Ludo."}, {"type": "figure", "caption": "", "page": 20, "file": "assets/images/p020_029.jpg", "dim": [860, 602]}, {"type": "para", "text": "Jeg glædede mig altid til min far kom hjem fra arbejde. Ofte sad jeg i vinduet og spejdede efter ham, så jeg kunne løbe ham i møde. Så var jeg ligesom børnene i sangen ”Venter på far”, som jeg havde lært udenad fra ”De Små Synger”."}, {"type": "figure", "caption": "Far og datter, oktober 1961", "page": 21, "file": "assets/images/p021_030.jpg", "dim": [516, 626]}, {"type": "para", "text": "Var far derimod sammen med venner eller familie, og de kom ind på emner, der interesserede ham, såsom fodbold, landbrug eller politik, så kan det nok være, han kunne få munden på gled. Jeg var meget glad for min far og tog altid hans parti, når mor skældte ud. Men det var mor, der var den kreative og havde idéerne, og hun havde virkelig god smag, hvilket også smittede af på far. Hun var ferm i et køkken, og der var ikke den ret, hun ikke kunne klare. Det var dog sjældent, at far roste hende. Han tog det bare som en selvfølge, at maden var god. Et eksempel på mors kreativitet, kombineret med en vis portion frækhed, var, dengang hun tog alle de dybe tallerkner og nogle fade i stellet Frisenborg med til isenkræmmer Søren Holm i Hjørring for at få dem byttet, ni år efter de havde fået dem i bryllupsgave. Mor havde fundet ud af, at de dybe tallerkner var altfor store, så hun ville hellere have nogle mindre. Hun har sikkert snakket godt for sig i butikken, for hun kom hjem belæsset med nye tallerkner og kopper, som hun manglede, i stedet for de tallerkner og fade, hun aldrig brugte. Et andet eksempel var, dengang hun købte en kjole, gik hjem, kopierede modellen, og leverede kjolen tilbage til butikken. Jo, frækhed belønnes."}]}, {"title": "Fobier", "blocks": [{"type": "para", "text": "Var der noget, min mor var bange for, var det hunde, edderkopper og mus, sidstnævnte både levende og døde. Derfra stammer nok også min angst for disse væsner. Så vi en edderkop, skreg vi straks på far, og hvis vi besøgte nogen på en gård, hvor der var hund, blev mor demonstrativt siddende i bilen, indtil kræet var blevet fjernet og forsvarligt lukket inde. Som 4-årig kom Per stolt hjem med nogle døde museunger, som Hans og Herdis på gården overfor havde givet ham. Da mor så de lyserøde skabninger, skreg hun så højt, at Per tabte dem på trappen, og først da jeg kom hjem, blev de fjernet – af mig. Jeg var ikke meget for det, men mor ville under ingen omstændigheder gøre det. Det var også vores begge to’s skræk, når vi havde mus – oftest under køkkenbordet. Mor lod altid noget fedt være tilbage på panden, når hun satte den på plads under køkkenbordet, så det var nemt at se, når musene havde været på spil. Vi hamrede altid på skabslågen, inden vi lukkede op, så musen kunne nå at komme væk. Far satte naturligvis en fælde, en af dem, der fanger dem levende, og det var en festforestilling, når mor tog fælden og sænkede den ned i en spand vand for at drukne musen. Mærkeligt, at hun ikke ventede, til far kom hjem, så hun selv var fri for det."}]}, {"title": "Thorshøj", "blocks": [{"type": "figure", "caption": "", "page": 22, "file": "assets/images/p022_031.jpg", "dim": [860, 549]}, {"type": "para", "text": "Thorshøj i Torslev Sogn er en lille landsby mellem Hjørring og Sæby, nærmere betegnet mellem Østervrå og Hørby. Byen er en såkaldt ”mejeriby”, idet den opstod omkring Thorshøj Andelsmejeri, som blev oprettet i 1887. Mejeriet tiltrak handlende og håndværkere, og efterhånden opstod der et mindre bysamfund på stedet. I 1892 startede Købmandsgården, og i 1899 kom Brugsen. Da jeg var barn, var der mange butikker i byen – i dag er der ingen, og hr. Møller ville sikkert have roteret flere gange i sin grav, hvis han havde set, hvordan hans kære Brugs ser ud i dag. Dengang kunne der eksistere to købmænd og en brugs, foruden to slagtere, tre bagere, to manufakturhandlere, en skotøjshandel, en boghandel, en urmager, en cigarhandel, en gartner, en frisør, en barber, en bank, en sparekasse, to mekanikere, en elektriker, to cykelhandlere, to tømrere, en murer, en blikkenslager, to malere, to vognmandsforretninger, en skole og et hotel. Nogle manufakturhandlere kaldtes trikotageforretninger, hvor man kunne få alt det nødvendige fra strikkegarn til hårnet og undertøj med lådden vrang. Det er vanskeligt at forestille sig, at et samfund på omkring 350 sjæle kunne holde liv i mere end tyve små forretninger. En af mekanikerne havde en søn, Thorkild, som var ca. 6 år ældre end mig og naturligt nok blev kaldt Thorkild Mekaniker. Han var en rigtig flot fyr, sorthåret med James Dean frisure, en rigtig drømmehelt. Og drømme, det gjorde jeg. Omkring 10-års alderen kunne jeg ligge i min seng om aftenen og fantasere om, at vi var kærester. Mine veninder var også vilde med ham, så det gjaldt om, hvem af os der kunne få hans opmærksomhed. En dag mødte vi ham tilfældigt og fik fremstammet et ”Daw”, som han gengældte med et stort smil. Det var før man sagde ”Hej” til hinanden. Bagefter brød vi fnisende sammen, og han må have tænkt: ”De fjollede tøser”, men dagen var reddet. Han gik i klasse med Lone Beck, og en dag, jeg var ude at gå med Lone, mødte vi Thorkild. Vi stoppede op for at snakke med ham, og jeg stod der målløs og ønskede, at jeg var Lone, for så ville han også vise mig opmærksomhed. Byen vrimlede med unge mennesker og børn, og der var altid nogen at lege med. Vi mødtes tit i byens anlæg, hvor der var en fin legeplads og et parklignende område, hvor nogle af byens mænd mødtes til et spil kroket, bl.a. barber Frederiksen, som var en af de festlige originaler i byen og samtidig min ”klipper”. Nogle kaldte ham ”Hundeklipperen”og jeg var tit sur på ham, fordi han klippede mig for kort, så jeg lignede en dreng. I 1963 kostede klip og føn 6 kr. Af andre originaler kan nævnes skomager Knudsen, som var lidt beslægtet med far, og som mine forældre kom sammen med. Det var mit store nummer, når vi blev inviteret derop, for de havde så mange børnebøger, jeg kunne fordrive tiden med, bl.a. en bog med vrøvlerim som ”Okker, gokker, gummiklokker”. Det var også skomageren, der lærte mig at drikke kirsebærvin, da jeg kun var 4 år. Desuden var der slagter Bock, som tronede stor og mægtig i sin blodplettede ”hvide” kittel og næsten så skræk- indjagende ud. Jeg skulle som regel kun have for 75 øre leverpostej eller ½ pund fars til frikadeller, men alligevel vankede der en rød pølse oven i handelen, så han var flink nok. Jeg skal endelig ikke glemme manufakturhandler Skovlund, som min mor var en trofast kunde hos, idet hun syede næsten alt vores tøj. Skovlund kunne altid garantere for kvaliteten, idet enten hans kone havde det samme ovenpå, eller hans søn Jørgen eller døtrene Tove og Birte, eller Birtes mand Jørgen. Min mor var en mester i at parodiere byens forretningsfolk. Anna Madsen var hans konkurrent, og hende støttede jeg, når jeg skulle købe stramaj til at brodere på. Jeg må heller ikke glemme Centralen, som i nogle tilfælde var bedre end nutidens telefonsvarere. De damer, der passede central, havde ord for at være sladderkællinger og meget nysgerrige, og det hed sig, at de lyttede med på samtalerne. Denne karakteristik er efter min mening meget uretfærdig, for de var ofte til stor hjælp. Man behøvede for eksempel ikke huske telefonnumre. Det var nok at sige, at man skulle have slagteren eller skomageren. Nu var numrene heller ikke så komplicerede dengang. For eksempel havde Skæve Konditori nr. 19. En gang i starten, Vagn og jeg kom sammen og jeg stadig boede hjemme, ringede han til mig og fik så først centraldamen. Hun kunne meddele ham, at vi ikke var hjemme, og fortsatte således: ”A tror, de er hos Knudsens, for a hår sit dem go forbi i dej retning for lidt si’en”. Så i stedet for at ringe forgæves til Tryvej 10, stillede hun om til Knudsens, og Vagn kom til at tale med sin elskede. Det har han aldrig glemt."}, {"type": "para", "text": "Selvom der var meget lidt trafik i Thorshøj, skete det alligevel to gange, mens jeg var barn, at der blev nogen kørt ihjel, og det gjorde indtryk. Der boede i byen en ældre mand, der blev kaldt Bette Thorvald. Han kom altid futtende på sin knallert, men en dag gik det galt. Det skete lige neden for vores lejlighed, og jeg kan endnu høre den dumpe lyd, da han efter at være blevet slynget op i luften faldt tungt ned på asfalten. Han lå helt stille, og folk strømmede til, de fleste af nysgerrighed. Også lyden af ambulancen med udrykning gjorde indtryk i sådan en lille by, hvor alle kendte alle. Han var død ved ankomsten til sygehuset. Omtrent på samme tid blev en af mine klassekammerater Bjarnes lillesøster på 4 år kørt ihjel uden for deres hus lidt længere nede ad vores gade. Det gjorde nok ekstra indtryk, fordi jeg selv havde en lillebror og prøvede at sætte mig i Bjarnes sted. Jeg fattede ikke, at han kunne gå i skole næste dag uden tilsyneladende at være påvirket af det, der var sket."}, {"type": "para", "text": "Som sagt var folk sensationslystne i de dage, for de oplevede ikke så meget. Da byens ældste gård, Hedebjerg, brændte, var jeg med far til ildebrand. Alle udhusene brændte ned og mange af dyrene indebrændte. Far hjalp til med at redde nogle grise ud, og jeg kan stadig fornemme lugten af brændt kød i mine næsebor, høre lyden af den knitrende ild og mærke den svidende røg i øjnene."}, {"type": "para", "text": "I 1913 blev Thorshøj stationsby på privatbanen mellem Hjørring og Hørby, men i 1953 blev skinnerne taget op, fordi rutebilen havde overtaget passagererne."}]}, {"title": "Mormor og Morfars Konditori", "blocks": [{"type": "para", "text": "Når jeg i dag kører forbi Konditoriet, ser det ikke ud af meget, men da jeg var barn, synede det stort. Jeg husker endnu indretningen: Slikbutikken var hovedindgangen og lå naturligt nok ud til vejen. Da jeg blev gammel nok, kunne jeg godt passe butikken. Foruden slik solgte vi brød og kager, øl, vand og is. I de år, jeg passede butikken, tiggede jeg ikke én eneste gang om et stykke slik, og jeg tog aldrig noget. Det skete, jeg fik lidt smuler i bunden af en kasse eller en is til 25 øre, og det var jeg tilfreds med. Det var stamkunder, der kom i butikken, så vi kendte hinanden, og jeg syntes, det var ret hyggeligt at være med i byens liv."}, {"type": "para", "text": "Inden for butikken var der tre rum: en dagligstue, et stort køkken og en restauration. Stuen var meget spartansk møbleret. Mine morforældre brugte ikke mange penge på møbler, heller ikke senere i livet, da de flyttede i hus. Køkkenet havde gammeldags komfur tilsluttet centralvarmeanlæg, men også gasblus samt et spisekammer. Inden for køkkenet var der en kælderhals ned til et gammelt bageri, samt et nybygget toilet. Restaurationen førte ned til en baggang, som blev kaldt hjørnestuen, hvor der var en trappe op til de øvre gemakker. Under trappen var der viktualierum. Ovenpå var der et soveværelse og fire værelser, så alle kunne overnatte, når de var hjemme. Neden for køkkenet var der en lille stue, der bare fungerede som mellemgang, men som havde været stue, inden min morfar byggede til huset. Dernæst kom man ind i det, der hed ”den lille sal”, og dernæst ”den store sal”, hvor alle festerne, dilettanten, begravelseskaffen, den omrejsende biograf og ballerne blev holdt. I enden af salen var der en stor scene, hvor vi kunne udfolde vores talenter. Her neden for igen var der en stor indgang med toiletter, billetluge og garderober."}, {"type": "figure", "caption": "", "page": 24, "file": "assets/images/p024_032.jpg", "dim": [860, 545]}, {"type": "para", "text": "Bagved Konditoriet, nede i noget, de kaldte ”Sandgraven”, var der udhuse, garage og værksted, hvor der henholdsvis blev holdt høns, grise og repareret knallerter og motorcykler, da mine onkler senere fik anskaffet sig disse maskiner. Der var også til tider rotter dernede. Da den store sal blev bygget ca. 1943, faldt en af håndværkerne, som hed Otto, ned og slog sig ihjel, kun 25 år gammel. Den beretning har sat sig fast i min erindring, fordi jeg følte, hvor forfærdeligt det må have været for min morfar at skulle hen til Ottos unge kone og give hende den frygtelige besked."}, {"type": "figure", "caption": "Den Bette Skrædder og Erik i sandgraven", "page": 24, "file": "assets/images/p024_033.jpg", "dim": [526, 738]}, {"type": "para", "text": "Over for mormor og morfar boede smedens. De hed Stinne og Georg, men hun blev altid kaldt ”Stinne til Smedens” (eller ”Stinne te Smejs” på vendelbomål). Dem kom mormor og morfar sammen med, og det betød også, at jeg kom til at lege meget med deres 4 børnebørn, som boede i Tårs. Deres mor, Bodil, (Bodil te Smejs) var smedens eneste barn, og deres far var fotograf Skræm Pedersen, som fotograferede mig som barn og også kom og fotograferede til festlige lejligheder i familien. De fire børn hed alle noget med T: Tommy, Tove, Teddy og Tim. Tim døde som 3-årig af kighoste, noget der gjorde et dybt indtryk på mig, især fordi han var en kær lille unge, som Tove og jeg tit havde passet. Senere kom Tove og Vagn til at gå i klasse sammen, og Tommy og Vagn kom til at spille fodbold sammen. Jo, verden er lille. Tommy var født med kun ét øre. Han gennemgik nogle plastoperationer, men dengang var man ikke så dygtig på det område, så det kunstige øre var meget mindre end det ægte og mere sammenkrøllet. Det forsøgte han at skjule ved at lade håret vokse lidt længere. Om sommeren, når jeg kom på ferie på Konditoriet, var det store nummer at spille dilettant. Jeg fik hurtigt fat i alle mine faste legekammerater, og så øvede vi os på alle mulige genrer. Engang havde vi besluttet, at der skulle tjenes penge, og det gjorde vi ved at tage entré: 50 øre per tilskuer. Vi øvede os i flere dage. Jeg skulle bl.a. synge ”Fiskerpigens Sang”, som var det store hit dengang, og hvis tekst jeg stadig husker. Vi var rundt i byen og gøre reklame, så da premieredagen kom, var der kø ved indgangen. Vi solgte billetter fra den rigtige billetluge, og tog imod folks overtøj. Der har nok været en snes tilskuere, da forestillingen gik i gang, men vi var ikke kommet ret langt hen i repertoiret, før døren gik op, og morfar tårnede frem. Han var en lille tæt mand, men han kunne godt råbe højt. Han havde ikke noget imod, at vi spillede dilettant, men vi blev kommanderet til at betale de 50 øre tilbage, så der røg den fortjeneste. Det er den eneste gang jeg husker, at min morfar har skældt mig ud."}, {"type": "para", "text": "Min mormor var som regel sød og rar, men en gang blev også hun gal på mig. Jeg var blevet sat til at skure gulv i den lille sal, et noget håbløst projekt for lille mig, selvom jeg var en halvstor pige. Mormor var gået hen for at sove til middag, som hun altid gjorde på det tidspunkt af dagen. Jeg havde nogle veninder, der stod og ventede på, at jeg skulle blive færdig, så vi kunne komme ud at lege. For at blive hurtigt færdig, foreslog pigerne, at de gav en hånd med. Den idé syntes min mormor absolut ikke om, for pludselig stod hun i døren, og så kan det nok være, at pigerne blev sendt hjem. Senere på dagen har hun måske angret sit temperament, for da jeg efter at have været ude og lege kom tilbage med de samme piger i hælene, gav hun is."}, {"type": "para", "text": "I mange år var der tradition for, at mine veninder fra Thorshøj blev inviteret til Skæve en dag i sommerferien. De kom med rutebilen om formiddagen, og så legede vi hele dagen, indtil de igen skulle med rutebilen hjem sidst på eftermiddagen. Var der fint vejr, legede vi i haven iført badetøj, for der var et fuglebad i græsplænen med ganske lidt vand. Nok vand til at vi alle kunne soppe og have det sjovt uden fare for at drukne. Det var der til gengæld fare for i det store bassin i haven, hvor der var åkander og fisk, men det havde vi stor respekt for. Hvis der var dårligt vejr, spillede vi dilettant i den store sal. Lige inden de skulle hjem, fik vi alle en is, som vi spiste på vej op til rutebilen."}, {"type": "figure", "caption": "Bedstefar fylder 80 år", "page": 25, "file": "assets/images/p025_034.jpg", "dim": [583, 860]}, {"type": "para", "text": "Når jeg besøgte mine morforældre og skulle overnatte, lå jeg altid i sprækken mellem dem. Det var det naturligste i verden. Jeg husker, at jeg i hvert fald lå der, til jeg var 11 år, for den 4. december 1960 blev der kastet sten på vinduet. Det var tante Karen, der kom for at fortælle mormor, at dennes far (Karens svigerfar), som vi alle kaldte Bedstefar, var død, 82 år gammel. Han boede i Skæve i en lejlighed ovenpå mormors bror Alfred og dennes kone Karen. Det var det år, min bror Per var blevet født og havde fået en bankbog af sin oldefar (Bedstefar) i gave. Jeg husker, at jeg følte sorg over Bedstefars død og gemte mig under dynen. Alfred lever endnu og er 97 år. Han boede i Bedstefars hus indtil for et år siden, hvor han kom på plejehjem. Vi besøger ham engang imellem, og han er stadig temmelig åndsfrisk men glemsom. * Men ellers var mit store nummer at ligge der i sprækken og høre min morfar fortælle historier. Inden han kravlede i seng, lå jeg og betragtede, hvordan han fjernede et langt bind, han hver morgen viklede om det ene ben, fra knæet og ned til foden, fordi han led af åreknuder. Når han så havde fjernet bindet, satte han sig på sengekanten og rullede det sammen, så det var klar til igen at blive viklet om benet næste morgen. Dette ritual gentog sig hver aften. Jeg kunne næsten ikke vente, til han blev færdig og kunne komme i gang med historierne. Nogle var sandfærdige og handlede om folk på egnen, bl.a. Vis-Niels, andre var opdigtede og handlede om de samme folk. Min mormor kunne også fortælle historier, men ikke så godt og levende som morfar. Hun var dog ret god til at fortælle om ”De tre Bukke Bruse”. Jeg husker også, hvordan mormor hver morgen stod foran spejlet i soveværelset og satte sit lange hår op i en knold. Først som ældre fik hun håret klippet kort."}, {"type": "para", "text": "Skrædder Stenvald Pedersen i Skæve havde en skrædderlærling, der var dværg. Han hed Leo, men blev altid kaldt ”Den Bette Skrædder”, og han kom fra Doense ved Hobro, hvor hans mor boede. Når jeg besøgte skrædderens, som var venner med mine morforældre, sad den store og den bette skrædder på bordet i skrædderstilling og syede. Dengang var der meget arbejde til skrædderne, for alle fik syet efter mål. Leo var ca. 5 år ældre end Onkel Erik, og der opstod mellem Leo og mine onkler et varmt kammeratskab, som resulterede i, at Konditoriet blev Leos andet hjem, selvom han jo boede og spiste hos skrædderens det meste af tiden. Meget af sin fritid brugte han sammen med Erik og Helge, hvis han da ikke skulle ud og spille til bal på sin harmonika og trompet, og jeg hyggede mig med ham. Leo så ikke ud som andre dværge, for alt på ham passede sammen, han var bare ikke så stor, nærmere som en 10-årig dreng med voksne træk, og vældig pæn. Før min lillebror forstod, hvad en dværg var, troede han, at Leo var en legekammerat, og det kan man også godt sige, at han var, for han gik ikke af vejen for at spille fodbold med Per."}]}, {"title": "Farmor og Farfars Gård", "blocks": [{"type": "figure", "caption": "", "page": 26, "file": "assets/images/p026_035.jpg", "dim": [860, 575]}, {"type": "para", "text": "Selvom jeg havde et ganske specielt forhold til min mormor og morfar, holdt jeg også meget af min farmor og farfar, men de var mere reserverede og knap så kærlige."}, {"type": "para", "text": "De boede på Sillebak, en gård lidt uden for Skæve. Sjovest var det at være på ferie deroppe om sommeren, hvis en af mine fætre eller kusiner også var der. Vi var 17 på fars side, så der var nok at vælge imellem. Jeg nød også at komme der, når fars yngste søster Aase var hjemme, både med og uden kæreste. Hun var en flot pige og ser stadig godt ud i dag som 73-årig. Vi børn kunne få megen tid til at gå ude i marken eller på høloftet, og så havde de på et tidspunkt en sød lille hund, der hed Bella. Bella og jeg var bedste venner, selvom det er svært at tro på i dag, hvor jeg ikke kunne drømme om at klappe en hund. Farmor havde en dejlig frugthave med de skønneste stikkelsbær, ribs, jordbær og solbær. Dem kunne vi bare spise løs af, men vi hjalp også somme tider med at plukke dem til syltning."}, {"type": "figure", "caption": "Mig og Bella", "page": 27, "file": "assets/images/p027_036.jpg", "dim": [449, 549]}, {"type": "para", "text": "I starten var der das i gården, men når der var gæster, og mændene skulle på deres runde i kostalden og se besætningen, ladede de vandet bag ved køerne. Jeg har vel været 8-9 år, da der blev lavet et toilet ved bryggerset."}, {"type": "para", "text": "Mig og Bella De var 6 søskende i min fars hjem, men de havde været 7. Min fars søster Ruth var død som 12-årig af tæring, det man i dag ville kalde kræft. Jeg tænkte ofte på hende, når vi efter farfars død stod ved gravstedet med stenen, hvorpå der stod Ruth. I dag er gravstedet slettet, men Ruths sten er stadig at finde på kirkegården. Min fars ældste bror og den tredjeældste i flokken hed Carl men blev kaldt Carl Møller. Han var gift med Karen, som var lidt enfoldig men meget sød. Mor plejede at sige, at hvis man fortalte Karen, at månen var lavet af en grøn ost, så ville hun tro på det. De havde en gård i Poulstrup og 4 sønner: Ole, Arne, Jørgen og Egon. Arne var på alder med mig, og Egon var født samme år som Per. Som barn glædede jeg mig altid, når jeg skulle være sammen med mine fætre fra Poulstrup. Peter var fars yngste bror og den næstyngste i flokken. Han blev gift med min mors kusine Inga, datter af Hans og Sørine. Hun havde datteren Jytte fra et tidligere forhold og fik to sønner, Kim og Søren, sammen med Peter. Inga og Peter overtog Sillebak, da farmor flyttede i lejlighed i Dybvad. Den ældste søster hed Anne Margrethe men blev kaldt Grethe. Hun var gift med Peter og boede i Vester Mellergård i Hugdrup ved Dybvad. De havde Bodil, Elin og Mogens. Pigerne var ældre end mig, og især Elin kunne få, hvem hun pegede på, for hun var en frisk pige og så godt ud, så hun havde altid kærester med hjem. Jeg så meget op til disse to kusiner, som i mine øjne kunne alting. Denne fascination har imidlertid fortaget sig. Grethe var den af fars søskende, vi havde mest med at gøre. Hun bor stadig på gården og går ikke af vejen for at passe have og kalke udhuse, selvom hun er 87 år. Den næstældste, Edel, var gift med Carl og boede i Try, men selvom de kun boede 3 km. fra os, så vi dem næsten aldrig. De kom aldrig, når de blev inviteret, kun når vi var i Sillebak. De havde 4 børn: Dorthe, Yrsa, Bruno og Jette. Faster Aase, som var den yngste, blev gift med fynboen Viggo og flyttede til Glamsbjerg, hvor de stadig bor i et fantastisk flot hus, som de byggede i 60erne. Viggo er maler og meget perfektionistisk, og så har de en meget ungdommelig smag, så man kan ikke se, at huset er så gammelt, som det er. De fik efter 9 års ægteskab datteren Lenette. Aase er i dag mit bindeled til min fars familie, og det er jeg meget taknemmelig for."}, {"type": "figure", "caption": "Forrest fra venstre: Edel, Anne Margrethe og Bagest fra venstre: Aase, Far og Peter", "page": 27, "file": "assets/images/p027_037.jpg", "dim": [860, 667]}, {"type": "para", "text": "Aase og Viggo blev viet lørdag den 5. december 1959 i Skæve Kirke med efterfølgende fest på Skæve Konditori. Mor fik syet ny kjole, for hun kunne ikke passe sit tøj, selvom hun kun var i anden måned. På selve bryllupsdagen startede en voldsom snestorm, som bevirkede, at mange af gæsterne sneede inde og først kunne komme hjem om onsdagen. Under vielsen var der hundekoldt, fordi fyret i kirken var gået i stykker, og strømmen var gået. Festen forløb dog fint, og brudeparret kom også til Flauenskjold Kro, hvor de tilbragte bryllupsnatten. Men næste dag måtte farfar hente dem i hestevogn ved Brøndens Kro, hvorfra der gik en grusvej op til Sillebak. De indesneede gæster var indlogeret dels på Konditoriet og dels i Sillebak."}, {"type": "para", "text": "Nogle gange om året var alle børn og børnebørn hjemme i Sillebak, og så var der liv og glade dage. Vi fik altid tarteletter med høns, hvilket er forblevet min livret, og til isen var der de skønneste isvafler i papir, lagt sammen med chokoladecreme. Efter maden legede vi børn ”sparke til bøtten” og andre udendørs lege, mens mændene spillede kort og damerne strikkede. ."}, {"type": "figure", "caption": "Her fejrer vi farmors 70-års Aase, der sidder over for far, ses", "page": 28, "file": "assets/images/p028_038.jpg", "dim": [798, 570]}, {"type": "para", "text": "Min farfar var, som min far, heller ikke en mand af mange ord, men han elskede at drille. En gang på Konditoriet havde vi fået ham med til at spille Matador, men det gik slet ikke, for han ville ikke sælge nogen af sine skøder, så vi kunne ikke få bygget huse. Han skråede, og jeg undrede mig tit over, hvad han brugte al den aske til, som mormor samlede i cigarkasser til ham, når der havde været fest på Konditoriet. Min farmor snakkede meget, og jeg tror, der var et godt forhold mellem hende og mor. Hun var meget sirlig og ordentlig, og hendes hvide forklæde var altid stivet og kridhvidt. Når vi besøgte dem om søndagen, fik vi nogle af mine livretter, og inden jeg fik lært at tale rent, sagde jeg, at vi skulle have ”finetoteletter og cikronfromage”."}, {"type": "para", "text": "Forfatteren Erik Aalbæk Jensens mor og min farfar var kusine og fætter, hvilket vil sige, at Erik Aalbæk Jensen og far var nærsøskendebørn."}, {"type": "para", "text": "Min farfar døde af kræft, mens jeg var i USA i 1962. Jeg græd meget, da jeg fik brevet med den sørgelige nyhed, og jeg følte, at jeg var meget langt hjemmefra."}]}, {"title": "Skolen", "blocks": [{"type": "para", "text": "I 1901 oprettedes en skole i Thorshøj. Skolen blev i 1917 udvidet fra to til fire klasser, og siden blev klassetallet øget flere gange, indtil der i 1959 var syv klasser. Jeg begyndte i 1. klasse i Thorshøj Skole den 1. april 1957 (billedet), og jeg husker endnu hr. og fru Mejlkjær (Johannes og Gudrun), han med violinen og hun i lang sort kjole med forklæde, rødmosset og med håret i en pølse for neden. Jeg selv havde lægget nederdel og strikket grønlændertrøje på. Vi skulle læse Ole Bole og synge en sang. Selvom det var forår, sang vi ”Dejlig er den Himmel Blå”, som i dag bliver betragtet som en jule- salme. Af den grund har jeg aldrig brudt mig om at synge den salme om julen. Hver dag, lige inden vi gik hjem, sang vi følgende vers: ”Nu er timen til ende og fra skolen vi gå, hvad vi lærte at kende, skal vi nok huske på”. Fru Mejlkjær var sød og blid, men hr. Mejlkjær kunne blive rasende og helt rød i hovedet. Det var oftest drengene, det gik ud over, og dengang måtte læreren slå. Dog var spanskrøret vist lige blevet afskaffet. Men også pigerne kunne få ryk i ørerne. Jeg husker engang i et frikvarter, hvor vi havde drillet Birgit fra klassen med, at hun var for tyk. I det samme kom Mejlkjær gående omkring hjørnet, og jeg stod forrest. Og selvom jeg var en af hans yndlingselever, tog han fat i mit øre og drejede det ganske let. Nej, hvor blev jeg flov. Siden den dag drillede jeg aldrig mere nogen."}, {"type": "figure", "caption": "", "page": 29, "file": "assets/images/p029_039.jpg", "dim": [688, 488]}, {"type": "para", "text": "Da jeg startede i skolen, skrev vi stadig med griffel på små tavler, hvilket dog hurtigt gled ud og blev erstattet af papir og blyant. Vi skrev også med penneskaft og pen, som vi dyppede i blæk, der stod i et blækhus på pulten. Det var svært at undgå at lave blækklatter eller at tvære blækket ud med hånden, inden det var tørt. For at undgå dette, brugte vi trækpapir."}, {"type": "para", "text": "Jeg kom til at sidde ved siden af Lisbet Ejlersen, som jeg før har omtalt. Vi blev bedste veninder og sad sammen resten af skoletiden, til jeg gik ud af 2. real og kom på gymnasiet. Hun var en dygtig pige, og jeg var vildt imponeret over hendes præstationer i Danmarkshistorietimerne. Nu har historie aldrig interesseret mig ret meget, og jeg havde min force inden for læsning, stavning, skrivning og regning. Vi lærte skråskrift ved hjælp af tretræksmetoden, som vi kunne i søvne. Fx: ”i, en, to, tre, bue væk, prik”. Vi havde skiftende vikarer til Danmarkshistorie, og på et tidspunkt havde vi selveste Elinor, brugsuddelerens datter, som læste til lærer på Ranum Seminarium. Hun fortalte om en masse historiske begivenheder i Danmarkshistorien, som vi så skulle kunne genfortælle næste gang. Og her var det, at Lisbet brillerede. Hun var næsten den eneste, der sagde noget i de timer. Det irriterede mig noget, at jeg ikke var så god til det, for Elinor kom jo sammen med mine forældre, så jeg ville gerne have brilleret. I klassen var der en spastisk lammet pige, der hed Inge. Hun gik med læderskinne på benet, talte meget dårligt, savlede og var svær at forstå. Hver gang, hun tog et skridt, så det ud, som om hun var ved at falde. Hende var der ingen, der drillede, og hun var altid med til pigernes fødselsdage, hvor der blev taget ekstra hensyn til hende. Et år gav hun mig en vase i fødselsdagsgave. Dengang tænkte jeg: ”Hvad skal jeg med den?” I dag er den min yndlingsvase. Hvert år var vi ved skolelægen, som bl.a. tjekkede synet og hørelsen. Jeg husker første gang, jeg skulle af sted og have en urinprøve med. Vi havde sovet over os og havde derfor travlt, så mor sendte mig i hast ud på toilettet for at tisse i et lille medicinglas. Jeg anede ikke, hvad jeg skulle stille op og placerede derfor glasset på gulvet, satte mig ned og forsøgte at ramme hullet. Med det resultat, at der kun kom meget lidt i glasset og mere på gulvet. Mor kom dog og reddede mig, for jeg var meget ked af min fadæse. Det værste var vaccinationerne, selvom de reddede liv. Da en amerikansk forsker i 1955 fandt vaccinen mod polio, blev poliofrygten taget fra danske forældre. Det, jeg bedst husker ved koppevaccinationerne, var de store sår, der dannedes på skulderen og som Forreste række fra venstre: Inge, som var spastiker, Lis Olsen, Kisse (Kirsten Jensen), Yrsa, Tove, Birte Carlsen, Tove, Kirsten, Irene og Lisbet Ejlersen. Yderst fra venstre: Lærer Casper, en vikar, Jette Kragelund, Tove Vestmark, Aase Simonsen*, Birgit Risager og mig. Bagest fra venstre: John Post**, Eigil Olsen, Bjarne, Erling Olsen, Charles, Erik Orry, Erik Maler, Bent og lærer Mejlkjær. * Aase kom fra St. Ødegård, fra et kristent hjem. Da vi blev ældre, syntes jeg nok, det var synd for Aase, at hun aldrig måtte være med til fest, for hun var en sød og festlig pige, og det er hun stadigvæk. Hun blev stewardesse ved Lufthansa, blev gift med en berømt grafiker, Karl Pichler og bosatte sig på et slot i Østrig. Hun fik en søn, Jens Karl, som i dag er 20 år. Jeg genoptog senere forbindelsen med Aase og skriver flittigt sammen med hende. Vi har mødtes nogle gange, bl.a. kom hun til mors bisættelse i 1993, hvilket rørte mig dybt. ** John Post hed egentlig John Larsen, men hans far var post, en nydelig høj, tynd mand. Hans mor hed Marna, men blev altid kaldt fru Post. Hun holdt sig mest inden døre, for hun kunne næsten ikke gå på grund af fedme. Jeg så hende aldrig sammen med manden, og de er da også siden blevet skilt. Når vi endelig så hende, kom hun vraltende hen ad fortovet, bleg og altid iført en lys cottencoat. Mor mente nu, at det havde været bedre med et villatelt, og far supplerede med at sige, at det var nemmere at springe over hende end at gå udenom, og han påstod, at man gik i skygge længe after, at man havde passeret hende. Vi kunne sagtens grine og gøre nar, men det må have været en skrækkelig tilværelse for den stakkels kone."}, {"type": "figure", "caption": "", "page": 30, "file": "assets/images/p030_040.jpg", "dim": [860, 630]}, {"type": "para", "text": "man ikke måtte røre ved, fordi de skulle falde af af sig selv. Hos skolelægen blev vi også vejet og målt. Den 30.3.1962 vejede jeg 45 kg og målte 159 cm."}, {"type": "para", "text": "I 1960 blev der oprettet en centralskole i den større naboby, Østervrå, 5 km. fra Thorshøj: Torslev Centralskole. Skolen i Thorshøj blev reduceret til forskole for de tre første årgange. Det passede så lige, at jeg kunne begynde på den splinternye skole i 4. klasse. Vi blev herved blandet med elever fra Østervrå og det omkringliggende opland, og vi kørte med skolebus. Jeg kom i en god klasse sammen med Lisbet, og vi fik nye venner, også blandt drengene, som ikke var helt uinteressante. Men jeg skulle også vænne mig til, at de elever, der kom fra ”byen”, talte bysprog ligesom læreren og præsten, en slags rigsdansk, mens folk fra landet talte bred dialekt og sagde ”a” og ikke ”jeg”. Jeg skammede mig over mit sprog, så jeg talte ”fint”, når jeg var i skole. Man skulle jo nødig blive til grin p.g.a. sin dialekt."}, {"type": "figure", "caption": "Merete 10 år har geografi", "page": 31, "file": "assets/images/p031_041.jpg", "dim": [592, 860]}, {"type": "para", "text": "Når jeg havde veninder med hjem, sagde jeg næsten aldrig noget, når mine forældre var til stede, for jeg kunne ikke få mig selv til at tale bysprog over for mor og far. Men på den anden side ville jeg heller ikke være bekendt at tale dialekt over for mine ”fine” veninder fra byen. Jeg har den dag i dag et ambivalent forhold til dialekter og til vendelbomål. På den Merete 10 år har geografi ene side synes jeg, de skal bevares, men jeg vil ikke være den, der bringer det videre i min familie. Det var virkelig en klods om benet på mig, da jeg gik i skole, indtil mit 13. år, hvor jeg efter at være kommet hjem fra USA benyttede lejligheden til at lægge det på hylden. Jeg glemmer dog aldrig min barndoms dialekt, og jeg nyder at høre andre tale den, blot ikke mig selv."}, {"type": "para", "text": "I marts måned 1962 var vi i min 5. klasse til flere 3-timers skriftlige optagelsesprøver til den boglige linie. Jeg bestod prøven og blev boglig. De boglige gik efter 7. klasse videre til realklassen, mens de almene gik til 8. klasse. Det var en lidt barsk opdeling, for der blev i mange tilfælde set ned på de almene, selvom mange af dem slet ikke ønskede at gå i den boglige klasse. Nogle få kom fra fattige hjem, var snavsede og havde lus. Dette gav til gengæld anledning til drillerier (men jeg skulle ikke have noget klinket). Jeg husker en pige, Karen Margrethe, som kom fra en fattig husmandsfamilie mellem Try og Thorshøj. Hun blev kaldt Putti, ligesom sin far, og ejendommen var den værste rotterede, og ligger der for øvrigt endnu. En anden pige fra Try var også altid snavset og havde lus, så drengene kaldte hende Lusforskrækkeren. Det må have været forfærdeligt at blive drillet på den måde. En tredje pige kom fra et lille hus på samme strækning, hvor moderen efter sigende var meget nysgerrig og altid skulle hen og glo ud af vinduet. Hende kaldte de Gardinsmutteren. Jo, man kunne nemt få et tilnavn. Men var det et pænt tilnavn, og kom det fra den ”rigtige” dreng, så havde vi piger ikke noget imod det. Der var visse drenge i klassen, vi gerne ville have opmærksomhed fra, og de gjorde det jo for at komme i snak med os. Sådan var det også om vinteren, når vi vaskede hinanden i sne i skolegården. Det bedste var at blive vasket af en af de drenge, man godt kunne li’. À propos navne, så havde jeg også et slags kælenavn (eller var det et øgenavn?), når jeg var i Skæve. Det var en af drengene, der havde fundet på det. Han kaldte mig altid ”Miratos”, fordi jeg solgte Piratos i min mormors slikbutik. Jeg havde egentlig ikke noget imod det, sikkert fordi jeg godt kunne lide den pågældende dreng."}, {"type": "para", "text": "Vi startede altid dagen i skolen med morgensang, efterfulgt af Fadervor, og denne ceremoni holdt jeg af. Vi sang i det hele taget meget dengang, og det er kommet mig til gavn siden hen. Jeg synes, det er dejligt og værdifuldt at lære sine fædrelands sange og salmer. Nogle af de smukkeste, vi sang, var B.S. Ingemanns: ”Nu titte til hinanden” og ”Nu vågne alle Guds engle små”. Somme tider tillagde jeg ord betydninger, som de slet ikke havde, hvilket jeg først har fundet ud af som voksen, når jeg har sunget salmerne i kirken."}, {"type": "para", "text": "Vores klasselærer hed Egon Juel Jensen, en yngre lærer, som havde sine favoritter i klassen, deriblandt mig. De, som han ikke kunne lide, havde det svært. Han ville gerne være populær hos pigerne, og det lykkedes ganske godt. Hvor dygtig han var, kan der måske sættes spørgsmålstegn ved, men jeg synes nok, jeg fik lært noget dansk. Jeg var så glad for Juel Jensen, at jeg havde svært ved at holde tårerne tilbage, da jeg tog afsked med ham i 1962 og tog til USA. Jeg bilder mig ind, at også han havde vand i øjnene. Af andre lærere kan nævnes fru Thykær, som i dag er 89 år. Hun var en lille kraftig dame, som vi havde til håndarbejde, når drengene havde sløjd. Hun var meget sød, men lære os at sy kunne hun ikke. Vi syede bl.a. ballonbukser efter hendes eget mønster, så vi kunne være i dem flere gange. Karen Bayer Jensen havde vi til tysk. Hun var også en yngre lærer, der kunne sit fag og var god til at lære fra sig. Hendes mand Jørgen kom senere til at spille badminton med far. Kurt Kirkedal havde vi til regning og matematik. Han var ung, mørk og flot, og vi piger var lidt forelskede i ham. At han så var hammerdygtig og behagelig tillige med var jo kun et ekstra plus. Vi havde flere vikarer, som jeg ikke husker navnene på, men de kvindelige vikarer havde det ofte svært, fordi drengene kunne være modbydelige over for dem. Hvis det blev alt for slemt, gik vikarerne til skoleinspektør Bramsen, og så blev pågældende dreng kaldt hen på kontoret til en kammeratlig samtale, hvorefter han vendte tilbage med røde ører og måske blev straffet med en eftersidningstime."}, {"type": "para", "text": "I frikvartererne gik vi piger arm i arm frem og tilbage i skolegården, ofte 3-5 sammen, som man nu var veninder til. Vi skrev i hinandens poesibøger, de sødeste vers, som f.eks.: ”Roser er røde, violer er blå, jordbær er søde, og du er ligeså”. Også drengene skrev deri og lavede tegninger, og nogle af lærerne indvilgede i at give deres besyv med i bogen. Min poesibog var en lyserød Puk-poesibog. På første side har Charles Andersen i 5.b skrevet: ”Kære Merethe. Når ulen (uglen) tuder i træets top, så ser man Merethe i grisegalop” Min veninde Kisse (Kirsten Jensen) skrev: ”Kære Merete. Jeg vil ønske dig et hus og en mand der bruger snus, og sytten raske gutter der bestandig råber Mutter”. Lærerne skrev altid digteriske citater, og min mor skrev: ”Kære lille Merethe (sjovt at hun næsten altid skrev mit navn med h, når jeg var døbt uden). Lyset slukkes, alt er stille, hør i naade, gud, den lille. Tak for Dagen, tak for livet, tak for alt havd du har givet. Din Mor.” Moster skrev: ”Merethe du er en dejlig pige, i verden der findes ej din lige, men selv om du vokser dig smuk og stor, saa glem dog ikke hvor din ensomme Moster bor. Kærlig hilsen Moster Edith.” (Det glemte jeg heller aldrig.) Og sådan kunne jeg blive ved. Når det ringede ind, skulle vi stille op i skolegården i tre lige rækker bag en linie, som markerede, at her skulle vores klasse stå. Vi skulle være musestille og først gå ind på et tegn fra gårdvagten. En dag var der en dreng fra vores klasse, der kastede et kanonslag, mens vi stod på række. Han blev naturligvis straks sendt hen på Bramsens kontor og fik en eftersidning, som der blev delt mange ud af dengang. Når vi så kom ind på gangen, skulle vi marchere hen og stå uden for vores klasseværelse, indtil den pågældende lærer kom og gav os lov til at gå ind. Vi skulle stå ret ved siden af vores bord, indtil vi fik besked på at sætte os ned. Når vi blev overhørt, foregik det ved tavlen eller stående ved siden af pulten. Og kom der en lærer på besøg i klassen, rejste alle sig straks op, når denne trådte ind. I dag ville man synes, det var streng disciplin, men dengang var det en naturlig sag. Jeg nød min skolegang i Østervrå utrolig meget, sikkert også fordi jeg lå blandt de dygtigste i klassen. Det skulle ændre sig, da jeg kom på gymnasiet. I 1962 fik jeg 2 kr. i karakterpenge af mormor for de fine karakterer, jeg havde fået."}, {"type": "para", "text": "Når vi kom hjem fra skole, lyttede vi til ”Efter Skoletid” i radioen med Jørgen de Mylius."}, {"type": "para", "text": "Skolefridage var nogenlunde som i dag, bortset fra, at vi holdt fri både på Kongens og Dronningens fødselsdage. Også Fastelavnsmandag var fridag, for da skulle vi ud og rasle. Vi blev klædt ud og gik fra dør til dør og sang: ”Fastelavn er mit navn…..” Det var i de hjemmegående husmødres tid, så der faldt en 10-øre af hvert sted."}, {"type": "para", "text": "Årets højdepunkt var skolefesten, dels fordi der blev opført en såkaldt skolekomedie, og dels fordi man så måske kunne være så heldig at komme ud at danse med en dreng, man kunne lide. På et tidspunkt var ”twist” den helt store dansedille. Forældrene var naturligvis med til skolefesten, og det hændte, at man mødte en lærer, som de lige vekslede et par ord med, og som fortalte dem, hvor godt det gik med deres afkom. Dette var til glæde for alle parter. Men skolekomedien var noget ganske særligt, fordi der i næsten alle årene var kræfter på skolen, der formåede at opsætte et stort stykke, enten et teaterstykke eller en musical. Jeg husker ”My Fair Lady”, ”Annie Get Your Gun” og ”Oklahoma”, hvor jeg i sidstnævnte sang i koret. Først i de sidste klasser kunne man komme på rollelisten, hvilket skete for mig i ”Gøngehøvdingen”, hvor jeg havde en mindre rolle."}, {"type": "para", "text": "Sidst i 50erne blev det moderne at gå i strutskørter, også i skolen. Taljen blev strammet ind med brede bælter, og ud fra det smalle liv bølgede de vide nederdele, båret ud af flere skørter med spiraler og stivelse som i en gammeldags krinoline. Det var hårdt for mødrene at skulle vaske og stive alle de lag skørter – helst i sukkervand. Det var også i de dage, at stoffer som perlon og terylene kom frem, dejlige strygefri materialer, som kunne kompensere for strutskørterne, når det gjaldt vask og strygning. Vores bedstemødre gik med korset, mens mødrene nøjedes med hofteholdere. Senere kom jeg også til at bruge hofteholder. Det var, før buksestrømperne gjorde deres indtog. Hvis en af de runde dippedutter i hofteholderen gik af, brugte vi bare en 1-øre i stedet for. Om natten lå vi i korte lyserøde Ole Lukøje natkjoler af tyndt nylon."}, {"type": "para", "text": "Skoleudflugter var også en begivenhed, hvorfra mange hjembragte de mest gyselige porcelænsfigurer med hilsen fra Himmelbjerget eller andre udflugtsmål. Jeg vidste, at mor afskyede denne form for souvenir, så jeg købte næsten aldrig noget med hjem. I de yngste klasser gik turene til Sæby, Himmelbjerget og Mariager. I 1963 gik skoleudflugten til Ålborg Zoo, Rebild og Tivoli (Karolinelund), en dejlig dag, som kostede mig 10 kr. I 1965 var vi på Bornholm, nærmere betegnet vandrerhjemmet ”Sjöljan” i Allinge. På denne tur købte jeg en smuk blå keramikvase fra Søholm Keramik med hjem til mor, og den blev hun glad for. I 1966 gik turen til Rüdesheim i Tyskland, hvor vi havde Egon Juel Jensen med. Vi lå i telt, og på denne tur prøvede jeg at ryge for første gang. Det blev ikke til ret meget mere, idet det smagte hæsligt, men vi skulle jo prøve det, og cigaretterne var billige i Tyskland, var der nogen, der havde fundet ud af. Vi brugte mit plastik spejdersæt, tallerken og kop, til askebæger, og det satte sine spor. Mor blev gal, da hun så mærkerne og spurgte mig, om jeg nu skulle til at ryge. Hun ville naturligvis gerne forhindre, at jeg gik i den samme fælde, som hun selv var gået i. Men heldigvis gik rygning aldrig i arv til mig og min familie. På turen mødte vi nogle andre klasser fra Lillerød og Grenå, og der var nogle af pigerne, der fik sig en feriekæreste. Det var her, jeg mødte Jens Kruse fra Grenå, og vi holdt forbindelsen et stykke tid. Vi bestemte, at han skulle komme og besøge mig, og jeg besøgte også ham og var endda med til hans brors bryllup. Men sandheden var, at jeg var mere forelsket i hans familie end i ham. Han havde nogle herlige søskende, og vi havde det sjovt, når jeg var på besøg. Da jeg imidlertid kunne mærke, at mor ikke brød sig om ham, og jeg indså, at jeg ikke var forelsket i ham, tog jeg mod til mig og slog op i et brev. Jeg følte mig fej, også over for hans familie, som havde taget så pænt imod mig. Den 24. juni 1973, lige før mit bryllup, så jeg hans forældre på Møllerens Hus sidde ved nabobordet, og de må også have set mig. Jeg burde være gået over til dem, men igen var jeg fej. Jeg håber, Jens har fået det godt, for han var en sød fyr."}]}, {"title": "Gaver", "blocks": [{"type": "para", "text": "Jeg var nok meget beskeden af natur og plagede aldrig om noget. Det gjorde børn nu heller ikke så meget dengang. Når det så kom på tale, hvor nem jeg var, sagde folk altid: ”Det er da bare, fordi hun er så forkælet, at hun får tingene, inden hun når at pege på dem”. Lidt sandt var der nok i den påstand, men der var da tider, da jeg blev lidt ældre, hvor jeg godt kunne have tænkt mig noget, som mine forældre ikke havde råd til, og hvor jeg så ikke ville plage om det for ikke at såre dem. Fx da jeg skulle konfirmeres. Selvom min kjole var den flotteste af dem alle, ville jeg gerne have haft en ny som de andres. Min var brugt. Mor havde købt den for 50 kr. af sin kusine, og den var med broderi over det hele, stor vidde i nederdelen og med store roser af tyl for neden hele vejen rundt. De andres kjoler var af noget tyndt stof uden megen vidde og med et lyseblåt eller lyserødt skærf i taljen. Men de var nye. Mit andendagstøj var også anderledes: Min kjole var svag orangefarvet og syet af byens syerske, Tulle. Det undrer mig lidt, at mor ikke selv syede den, men hun har nok ikke syntes, at hun kunne gøre det godt nok. Jeg var ikke specielt glad for kjolen, for de andre havde købt deres hos Marinus Madsen i Hjørring, og de var enten lyserøde eller lyseblå. De havde også frakker, hvorimod jeg havde en mørkebrun ruskindsjakke. Mor mente, at den kunne jeg have glæde af længere. Hun havde så evigt ret, for jeg har den endnu, og jeg har faktisk tænkt mig at begynde og bruge den igen, da den har fået en renæssance. Den passer mig, for jeg er ikke vokset meget siden min konfirmation, og det betyder også, at jeg var en af de højeste – drengene var nogle undermålere."}, {"type": "figure", "caption": "Mig og dukke Jette, 4½ år", "page": 34, "file": "assets/images/p034_042.jpg", "dim": [650, 860]}, {"type": "para", "text": "Hvis vi så går længere tilbage, må jeg sige, at legetøj manglede jeg ikke. Jeg havde tre favoritdukker: en meget fin og stor dukke (55 cm lang) med lange sorte fletninger og ditto øjenvipper, med hvid kjole af tyl og hat med hattenål. Og så kunne hun lukke øjnene, når hun blev lagt ned. Hende havde mor og far haft med hjem fra Østrig, da jeg var 6 år. De havde taget en tur med Moster og Ib i folkevognen, mens jeg var blevet passet i Skæve. Dukken døbte vi Gisla efter en tysk pige, som jeg havde mødt året forinden. Gisla var jeg meget øm over, så hende skiftede jeg næsten aldrig tøj på, fordi hun var lidt skrøbelig. Hun var mest til pynt. Jette, derimod, var min yndlingsdukke. Hun var opkaldt efter mejeribestyrerens datter, som var ældre end mig og meget køn. Dukke Jette var næsten ligeså stor som Gisla men var af celluloid og havde ikke rigtigt hår. Hun var alligevel pæn, og mor syede meget tøj til hende."}, {"type": "para", "text": "Endelig var der ”Bamse”, min gule teddybjørn, som havde to sæt tøj, jeg kunne skifte med. Han kunne brøle, når man vendte ham om på maven."}, {"type": "para", "text": "Den bedste gave fik jeg dog det år til jul, hvor morfar og ”drengene” havde lavet dukkehus til mig. Det var vel den første jul, efter vi var flyttet til Thorshøj. Stor var min overraskelse, da de juleaften kom bærende med huset. Det var i to etager og med elektrisk lys og veranda. Der var en stor stue og et køkken samt soveværelse og badeværelse. De havde også lavet møbler til det, og med tiden fik jeg flere. Jeg husker endnu det lyserøde badekar og bornholmeruret samt radioen, som var en miniudgave af den, min mor og far havde. Dukkehuset fik sin plads på mit lille bord i soveværelset, men jeg flyttede det tit ind i stuen, hvor jeg tilbragte megen tid med at lege med det."}, {"type": "figure", "caption": "Her er jeg iført grønlændertrøje og ”bukket” hår, 7 år", "page": 35, "file": "assets/images/p035_043.jpg", "dim": [523, 550]}, {"type": "para", "text": "Jeg fik altid mange gaver til jul og fødselsdag. Min mor syede meget, så jeg fik næsten altid dukketøj og tøj til mig selv, somme tider ens. Hun brugte en bestemt æske til mig hvert år til jul. Den fulgte mig, lige til hun døde. Når jeg så den under juletræet, vidste jeg, at det var en gave, som mor selv havde lavet. Et år var det en stoftrykt anorak, et andet år en hjemmestrikket grønlændertrøje. Mor var som sagt kreativ, og hun lavede både stoftryk og senere batik, som også blev et erhverv for hende, indtil en eller anden nævenyttig person meldte hende og Ellen Beck, som hendes medfabrikant hed, til skattevæsenet, og så var der lukket for det varme vand. De gad i hvert fald ikke lave batik, hvis de skulle betale skat. Det havde nu også grebet om sig, for de købte rullevis af hvidt stof på en fabrik, farvede det i de smukkeste farver og mønstre og syede kjoler, bluser, tasker m.m., som de så solgte til kunstforretninger og private. Farvningen, som var en lang proces, hvori der indgik kaustisk soda, foregik i vores vaskemaskine i vaskehuset, og somme tider var stuen fyldt med kjoler, der hang på bøjler overalt, klar til at blive solgt i kunstforretningerne. En almindelig kjole kostede 100 kr. i 1969. Jeg husker, at jeg det år, udover min hvide studenterkjole, også havde en rød batikkjole af mors kreationer. Den var meget smuk, og jeg nød at have den på. I deres kreationer satte de mærket ”Dorell” (Doris og Ellen). Måske var det, da der i Vendsyssel Tidende blev bragt en artikel med billede af mor og Ellen, at nogen fik ondt af deres forehavende. I avisen er de afbildet siddende i sofaen, mor iført en model ”Merete” og Ellen en model ”Lone”."}, {"type": "para", "text": "Efter sin batik-karriere fik mor arbejde i Østervrå Børnehave, som senere skiftede navn til Bødkergården, og her var mor en afholdt og elsket medarbejder indtil sin død i 1993."}, {"type": "para", "text": "Når mor forærede nogen noget, forlangte hun, at man var taknemmelig, viste glæde og sagde tak. På det punkt lignede jeg nok min far, som ikke hoppede i vejret af begejstring eller strøede om sig med taksigelser. Efterhånden som min generthed fortog sig, blev jeg bedre til at vise følelser og udtrykke taknemmelighed, men jeg var også i en hård skole hos mor."}]}, {"title": "Lege", "blocks": [{"type": "para", "text": "Jeg er jo ikke vokset op med TV og computer, så det var lidt af en sensation, når vi så en film på lærred. På Konditoriet kom der nogle gange en omrejsende biograf, og så sad jeg på forreste række og sugede til mig. Jeg husker film som ”Blåvand melder storm”, ”Barken Margrethe af Danmark”, ”Fy og Bi”, ”Panserbasse” med Ib Schønberg og lille Connie, og film med Poul Reichardt, som var min drømmehelt. Senere var det Lille Per og Dirch Passer filmene, der var favoritter. Men ellers husker jeg min barndom som fuld af leg. Vi legede med dukker, påklædningsdukker og købmandsbutik, sidstnævnte i Frosts gildesal i kælderen. Påklædningsdukkerne var ofte kendte filmstjerner med komplet garderobe fra badedragt til dekolleteret aftenkjole. Oxford kiksefabrik havde lanceret tre påklædningsdukker, som symboliserede tre slags kiks: Store Marie, Lille Marie og Sorte Marie. Sidstnævnte var en negerpige og symboliserede naturligvis chokoladekiks. Udover disse og mange andre påklædningsdukker havde jeg de canadiske femlinger, som var en sensation på det tidspunkt. Det var, før der var noget, der hed kunstig befrugtning. Det var fem piger, som alle hed noget med C. Jeg husker ikke alle navnene, men en af dem hed Cecilie."}, {"type": "para", "text": "På et tidspunkt havde Ulla og jeg også gang i et stort projekt på hendes værelse, hvor vi legede arkitekter. Vi byggede et hus op af skotøjsæsker, papir og stof med vægge, døre, vinduer, møbler etc. Vi blev aldrig færdige med projektet, for jo længere det skred frem, jo mere kompliceret blev det. Det sidste, vi lavede, var en rød sofa, derefter mistede vi interessen. Dengang legede kun pigerne med kaffestel og komfur – de skulle jo forberede sig til rollen som husmødre. Jeg havde et lille komfur med indlagt stearinlys, hvis flammer gik op og varmede bunden af gryderne. Vi hældte hvidtøl og saftevand i gryderne og legede, at det var sovs og saftsuppe, som så blev øst op i bittesmå skåle og spist med god appetit."}, {"type": "para", "text": "Om vinteren stod vi på skøjter og kørte på slæde, for der var altid sne dengang. Sådan husker jeg det i hvert fald. Det bedste, jeg vidste, var at iføre mig mine skistøvler, som vi havde købt brugte, slænge skøjterne over skulderen og begive mig over vejen og ned på Riis Tofts mark, hvor der var et stort tilfrosset meget lavt vandområde uden nogen fare for at drukne, hvis isen brast. Her mødtes vi børn ofte om vinteren og konkurrerede om, hvem der kunne løbe længst baglæns. Nogle havde ikke ordentlige støvler men havde spændt skøjterne på deres gummistøvler, hvilket var et handicap. Jeg blev helt god til at løbe baglæns, og som tiden gik, stod jeg ikke længere så meget på skruerne. Skøjteløb adskiller sig fra cykling og svømning på bl.a. ét punkt. Hvis man først har lært sig de to sidstnævnte, glemmer man dem aldrig. Jeg har senere i mit voksenliv prøvet at stå på skøjter. Det gik slet ikke. Men tilbage til barndommen. Efter en dag på isen kom man hjem med følelsesløse fingre og tæer. Til tider ”mylede” fingrene så meget, at jeg græd, men så hjalp det at få dem varmet ved kaminen. Tøjet dengang var ikke som det, børn har på i dag. På et tidspunkt havde jeg ikke en ordentlig vinterfrakke men stod på skøjter iført en tyk trøje, hvor blæsten rigtigt kunne trænge igennem. Oppe ved en anden gård, Hedebjerg, var der en sort ajle is, som også var ret populær at stå på, men det skete, at man gik igennem og kom hjem gennemblødt af denne stinkende masse. Det var ikke særlig populært hos forældrene."}, {"type": "para", "text": "En vinter gik det galt. Det må have været et af de første år, jeg gik i skole, for jeg var nede hos Jette fra klassen. Hun boede på en stor gård, som hed Gydeje, og de havde nogle gode bakker, hvor vi kunne køre på slæde. På en af mine ture ned ad en bakke, vælter jeg og støder hovedet ind i en stor sten, så der bli’r en flænge, der bløder meget, over venstre øje. Min mor var meget forarget over, at de sendte mig hjem bagpå tjenestepigens cykel. De havde bil og kunne have kørt mig hjem i den, men de gik for at være meget nærige, hvilket deres kulinariske specialiteter såsom brændenældesuppe også vidnede om. Mor ringede straks til doktor Tram fra Dybvad, som var familiens læge."}, {"type": "para", "text": "Han kom ret hurtigt og syede flængen med 4 sting. Jeg husker, at jeg sad ved spisebordet, mens han syede, og jeg husker også den krumme nål, som jeg fik lov at beholde. Det var også Tram, der tidligere havde taget sig af mig, når jeg var kommet galt af sted. Senere har jeg dog sat spørgsmålstegn ved, om han virkelig var så dygtig, som familien ville gøre ham til. Det viste sig nemlig mange år senere, da mormor som 80-årig kom til en anden læge, at det, som Tram havde diagnosticeret som dårligt hjerte og havde givet hende hjertemedicin for i over 30 år, viste sig at være en dårlig lunge!"}, {"type": "para", "text": "Når skøjtesæsonen var overstået, kom rulleskøjterne frem. De skulle også spændes på sko eller støvler, og var tunge som et ondt år. Mine var købt brugte men ikke ringere af den grund. Om foråret hinkede vi og ”hoppede i mand”. Det var ikke så populært hos de voksne, for vi tegnede simpelthen med kridt en mand på fortovet og opdelte ham i felter. Så skulle man smide en hinkesten og hoppe rundt i felterne uden at træde på stregerne. På et tidspunkt var den helt store dille at hoppe i elastik, hvor to personer havde et bukseelastik spændt ud i skiftende højder omkring benene. En tredje person skulle så foretage sig forskellige øvelser i elastikken uden fejl. Så snart en fejl blev begået, var det en andens tur. Og vi var strikse dommere over hinanden. Elastik og sjippetov var en yndlingsbeskæftigelse i frikvartererne, hvor vi SKULLE ud i skolegården. Kun sygdom og en seddel hjemmefra fritog os fra at gå ud. Og så naturligvis hvis vi var dukse. Vi skiftedes til at være duks og skulle så bruge frikvartererne til at rydde op i klassen, viske tavlen ren og dele materiale ud til næste time. Om vinteren kunne det godt være træls at skulle ud i frikvarteret, så en vinterdag i Thorshøj Skole løj jeg over for lærer Mejlkjær og sagde, at jeg ikke måtte komme ud for min mor, fordi jeg lige havde været forkølet. HURRA! Han hoppede på den, og jeg fik lov at blive inde, måske fordi han havde respekt for mor. Da det var en lørdag, kom far tidligt hjem fra arbejde, og jeg husker, at jeg gik med ham ud for at rydde sne. Pludselig så jeg lærer Mejlkjær komme gående imod os, og jeg fik meget røde ører. Værre blev det, da han stoppede op og vekslede et par ord med far. Hvad nu, hvis han spurgte til mit helbred, og far fandt ud af, at jeg havde løjet? Men Mejlkjær var en fin mand, og kun hans blik til mig røbede, hvad han tænkte. Denne episode var virkelig en lærestreg for mig, og jeg fandt ud af, at det ikke betaler sig at lyve."}, {"type": "para", "text": "En overgang var det moderne med hula-hop ringe, som vi også tog med i skole og brugte i frikvartererne. Det gjaldt om at kunne blive ved længst muligt, uden at ringen faldt til jorden. Nogle kunne svinge den omkring halsen og helt ned til anklerne og op igen, men jeg var ikke specielt dygtig på det område."}, {"type": "para", "text": "Boldspil var også populært, og det kunne blive ganske avanceret. Enten havde man et program med en stor bold, som man spillede ned i jorden eller op ad en mur. Man skulle så foretage sig nogle bevægelser, inden man igen greb bolden, og nåede man ikke det, var det den næstes tur. Vi blev også helt dygtige til at spille med små bolde op ad en mur. Jeg kom aldrig op over 3 bolde, men Gunhild og Inge-Lise kunne spille med 4 og nogle gange 5 bolde, hvilket var ret imponerende."}, {"type": "para", "text": "Vi samlede på alverdens ting dengang: påklædningsdukker, frimærker, servietter, glansbilleder og Rich’s billeder. ”Det er Rich’s, der drik’s” var et slogan for dette kaffeerstatningsprodukt, som kunne strække lidt på de dyre kaffebønner, og hvor man samlede billeder, som man satte ind i et album med undertekster. Jeg samlede et album med ”Peter Pan” og ”Dumbo”. Sloganet for Rich’s fortsatte: ”men Danmark’s, der du’r”, et konkurrerende produkt, hvor man også kunne samle billeder til albums. Hos os brugte vi Rich’s og ikke Danmark’s. Desuden samlede vi på hønseringe, marmorkugler, snapringe, (farvestrålende plastikfigurer eller –bogstaver, som vi satte sammen og spillede om i frikvartererne), og billeder af filmstjerner fra tyggegummipakker."}, {"type": "figure", "caption": "", "page": 38, "file": "assets/images/p038_044.jpg", "dim": [704, 437]}, {"type": "para", "text": "En overgang samlede vi også på bilnumre. Det var dengang, man kunne se, hvor bilerne kom fra, fx P fra Hjørring og U fra Ålborg. Det var også dengang, der ikke var så mange biler på vejene, så man nemt kunne nå at notere bilens nummer ned, inden den næste kom. Det gjaldt altså om at have flest numre, og de sjældneste. Det hændte, at jeg fik en taburet ned på fortovet for så der at sidde i flere timer og måske kun få 10 numre. Billedet her er fra 1957. Mest spændende var det, når man kom lidt længere væk fra Thorshøj, hvor der var en chance for at få numre fra andre distrikter. Vi talte også Folkevogne, og her appellerede vi i højere grad til hinandens ærlighed. Hver gang, vi så en Folkevogn, blev den talt med, og vi kunne altid huske, hvor langt vi var kommet. Det gjaldt om først at nå til 500, men hver gang vi så en sort Folkevogn, skulle vi trække 5 fra. Hjemmesygeplejersken i byen havde en sådan, så det skete jo, at der blev minus på kontoen. En dag, jeg kom kørende på min røde cykel, anede jeg, at den omtalte bil holdt længere nede ad vejen. For at undgå synet af denne for os børn så upopulære bil, kørte jeg et langt stykke med lukkede øjne, indtil det sagde ”BANG”, og jeg lå på vejen ved siden af uhyret med cyklen i et ottetal. Surt show at have slået sig, at skulle hjem og fortælle, at cyklen var gået i stykker og at trække 5 biler fra på listen, for vi snød jo ikke. Når jeg var alene hjemme og havde veninder på besøg, var det helt store nummer at gå mannequin i mors tøj og sko. Mor havde engang gået mannequin på Thorshøj Hotel, så det måtte vi også gøre. Vi gjorde det aldrig hos mine veninder, sikkert fordi min mor var yngre og havde smartere tøj end mine veninders mødre. Mor vidste godt, at vi gjorde det, men hun sagde ikke noget til det, hvis blot vi ryddede op efter os."}, {"type": "figure", "caption": "Mor går mannequin på Thorshøj Hotel", "page": 38, "file": "assets/images/p038_045.jpg", "dim": [559, 788]}, {"type": "para", "text": "Før jeg fik lært at læse, læste mine forældre for mig, oftest far. Det var dejligt at få læst op af Halfdan Rasmussens vrøvlerier of især husker jeg også ”Spørge Jørgen” bogen. Den havde jeg megen fornøjelse af, også når jeg udfoldede mine kunstneriske evner ved at lægge gennemsigtigt smørrebrødspapir over billederne, tegne dem af og farvelægge dem. Da jeg så senere fik lært at læse, åbnede der sig en helt ny verden for mig. Jeg blev lidt af en læsehest og læste mange pigebøger i starten. Jeg samlede på Puk og Pernille bøger men læste også H.C.Andersen, ”Det lille hus på prærien”, ”Onkel Toms Hytte” og Inge Åsted. Dengang var jeg også lidt af en romantiker og slugte kærlighedsromaner råt. Vi havde ikke råd til at holde ugeblade, men hos Frosts holdt de ”Hjemmet”, som jeg fik lov at kigge i, når jeg var ovre og lege. Rasmus Klump og senere Gyldenspjæt og Knold og Tot var faste tegneserier hver uge, men jeg lånte også somme tider en stak gamle blade med hjem, så jeg kunne læse en kærlighedsroman. Når jeg så legede med Ulla, kunne jeg kigge i ”Familie Journalen”, som de holdt. Heri var tegneserier som Bamse og Dukkelise samt Kaptajn Willy’s Eventyr favoritter. Somme tider fik jeg lov til at købe et Anders And blad, og jeg nød virkelig at leve mig ind i denne tegneserie- og eventyrverden."}]}, {"title": "Fritidsaktiviteter", "blocks": [{"type": "para", "text": "Jeg kom ret tidligt til at gå på danseskole, først på Skæve Konditori i 1956 og 1957, hvor der kom en danselærer en gang om ugen og holdt danseskole, og hvor der sad en spillemand og spillede på sin harmonika. Jeg husker også afdansningsballerne, hvor jeg dansede med nogle store piger, Inge Koustrup og Hanne, og Inges bror Arne. Senere kom jeg til at gå til dans på Thorshøj Hotel, hvor det var den samme danselærer, Regnar Christensen, der underviste. Dengang var der heller ikke så mange drenge, der gik til dans, så det var ofte piger, jeg dansede med, men det var ikke altid, man havde en fast partner. Da min bror blev 4 år og skulle gå til dans, blev det mig, der kom til at danse med ham de første år, hvilket jeg ikke havde noget imod. Han ville sikkert hellere have haft en partner på sin egen alder. Højdepunktet var afdansningsballerne, hvor forældrene sad i en kødrand i salen og beundrende så til, mens deres små poder gjorde sig på de bonede gulve. De dygtigste dansere fik lov til at give en speciel opvisning, hvilket var en stor ære, som flere gange tilfaldt mig. Blot var jeg lidt træt af, at jeg altid skulle danse dreng og derfor kun have sorte bukser og hvid skjorte på, mens pigerne, fx Lisbet Ejlersen og Til afdansningsbal sammen med Arne Koustrup Lisbeth Jørgensen, havde fine folkedanserkjoler på Skæve Konditori. Jeg var sløj, hvilket ses på på. Måske hænger det sammen med, at jeg var mine skelende øjne. temmelig høj af min alder på det tidspunkt og var blevet drengeklippet hos barber Frederiksen. Det kan have været på Thorshøj Hotel, at kimen blev lagt til min senere danseinteresse og til, at jeg også syntes, at min egen søn Lars skulle gå til dans. Senere kom jeg til at gå til håndbold, hvilket var en dejlig sport, som stadig interesserer mig som tilskuer. Jeg stod på mål og var meget nervøs, når vi skulle spille kamp. Når vi tabte, følte jeg ofte, at det var min skyld. Det var altid uretfærdigt, når vi tabte, for ”de andre var garanteret ældre, end de måtte være, og også meget større end os”. Men når vi vandt, var vi stolte. Jeg husker min største triumf på hjemmebane, hvor far var blandt tilskuerne. Vi vandt stort, og jeg havde nogle pragtredninger; om det så var held eller dygtighed skal jeg lade være usagt. Bl.a. reddede jeg en bold ved at stikke foden ud det rigtige sted, så bolden røg langt pokker i vold. Far var stolt, da vi gik derfra, kunne jeg mærke, men han udtrykte det ikke med ord. Den måde, han smilede på, var nok for mig. Jeg var også en slags spejder – UA hed det, hvilket stod for ”Unges Arbejde”, en lidt missionsk organisation, hvor bl.a. Ditte Knudsen var leder. Det var her, jeg først lærte købmanden Ejvind og hans kone Ditte at kende. Vi mødtes en gang om ugen hos lederne på skift, og der hyggede vi os med sang, bøn og andre aktiviteter, såsom håndarbejde. Og så fik vi saftevand og kage. Nogle gange blev der arrangeret udflugter, og hvert år lavede vi i Missionshuset en adventsfest for de gamle i byen, hvor de så kunne vinde de ting, vi havde kreeret i årets løb. Vi var på hyggelige lejre, men det, jeg husker allerbedst, var en weekend i Ditte og Ejvinds sommerhus i Sæby i 1963. Vi hyggede os med sang og leg, spillede bold, gik i kirke og fik dejlig mad. Det var et utroligt stort stykke arbejde, Ditte og de andre ledere leverede."}, {"type": "figure", "caption": "Til afdansningsbal sammen med Arne Koustrup mine skelende øjne.", "page": 39, "file": "assets/images/p039_046.jpg", "dim": [604, 860]}, {"type": "figure", "caption": "Merete på blokfløjte og med fønbølget", "page": 40, "file": "assets/images/p040_047.jpg", "dim": [523, 515]}, {"type": "para", "text": "I min familie var vi ikke specielt musikalske, men jeg fik ligesom mange andre på min alder ret tidligt en blokfløjte. To huse fra os boede Frederik Larsen, som var spillelærer. For 1,25 kr. i timen kunne man få undervisning i blokfløjtespil, hvis man var en gruppe sammen. Jeg gik sammen med Frosts og Jørgensens piger, og jeg kan endnu høre lyden af blyanten, der blev slået ned i bordet for at angive takten. Vi fik da også lært at spille mange melodier, som jeg optrådte med, når der var gæster. Vi gik en gang om ugen, men jeg husker det som lidt af en plage at skulle af sted, så efter nogle vintre sluttede festen. Hos Frosts havde de klaver, og pigerne blev holdt i ilden og skulle øve sig."}, {"type": "figure", "caption": "Gunhild, mig, Britta, Ulla og Inge-Lise", "page": 40, "file": "assets/images/p040_048.jpg", "dim": [669, 451]}, {"type": "para", "text": "Om vinteren gik jeg på aftenskole på Torslev Centralskole, bl.a til formning og husgerning. I mange år havde jeg en syklub sammen med Ulla, Gunhild, Britta og Inge-Lise. Vi mødtes en aften om ugen hos hinanden, og vi levede virkelig op til navnet, for der blev broderet mange klokkestrenge, mellemlægsservietter og bordløbere de vintre, samtidig med at der blev snakket og fjantet. Vores mødre servicerede os med saftevand og kage. Dette måltid blev drukket og spist af vores mokkakopper, som vi alle samlede på. Vi samlede på det samme rillede stel med guldkanter, som kunne fås i mange farver, men til forskel fra de andre, som havde kopperne i mange farver, havde jeg dem kun i sort. Det var naturligvis mor, der havde bestemt det, fordi hun mente, at jeg ville få mere glæde af dem senere, hvis de var sorte. Hun var nu så praktisk anlagt, men hun havde ofte ret. Også en gang om ugen gik jeg på sykursus i Husflidsforeningen, hvor jeg bl.a. syede duge og pudevår i hardangersyning. Jeg brugte meget af min fritid derhjemme på at brodere. Et år op til påske havde jeg så travlt med at få en påskeløber færdig til Moster, at jeg måtte sidde oppe den halve nat for at nå det. Som stor pige gik jeg til porcelænsmaling sammen med mor på Thorshøj Skole. Der var mange med fra byen, også andre mødre med døtre, så det var hyggeligt. Mor viste sig at være meget dygtig til at male, meget dygtigere end mig. Hun malede et helt stel til mig, som jeg er meget glad for i dag. I 60erne var det moderne at sy lampeskærme, men der skulle fingerfærdighed til, og stoffet skulle strammes godt ud, så det ikke bulede bagefter. Mange gamle lampeskærme blev fornyet på denne måde, og ekstra flot så det ud, hvis der var en stor tylsrose i hvert felt. Jeg gik en vinter til lampeskærmssyning og fik kunsten lært. Et håndarbejde, min mor lærte mig, var kludeklip, som jeg kunne blive helt bidt af. Mor lavede mange forklæder, hvor hun af tøjrester klippede figurer og syede på, bl.a. husker jeg et blåt forklæde med en rødternet kaffekande og kop, hvor sidstnævnte dannede lomme. Jeg selv var med til at lave juleduge og juletræstæpper, hvorpå vi limede filtnisser og –hjerter. I mange år var radioen det fremtrædende medie, og selv børn lyttede til hørespil og naturligvis godnathistorier fortalt af Inge Åsted. En vinter fulgte jeg med i et hørespil om udvandrerne til Amerika. Det tryllebandt mig, og lydeffekterne var meget autentiske. Men folk var nu stort set heller ikke kræsne dengang. Blandt de mest populære udsendelser var den månedlige ”20 spørgsmål til professoren”, den gamle gætteleg om genstande fra enten dyre-, plante- eller mineralriget. Ind imellem udsendelserne kunne man lytte til Frøken Klokken, som gav det nøjagtige klokkeslæt inkl. nul, nul, dut. I midten af 50erne begyndte folk at interessere sig for TV, og hos de lokale elforretninger kunne man om aftenen se folk stå med næserne klemt flade mod ruden for at se de første udsendelser. Man slugte alt råt, bare det var noget, der bevægede sig. Da TV så senere kom ind i folks stuer, gik man på besøg for at se TV, selv hos folk man ikke kom sammen med. Folk sad i mørke og stirrede ind i kassen, og de bemærkede knapt nok, at der kom flere og flere seere til. Hvis nogen sagde noget, fik de straks besked på at tie stille. Ofte fik man så kaffe, når udsendelsen var slut, for før kunne værtinden jo ikke løsrive sig. ”Kvit eller dobbelt” var fjernsynsprogrammet, der bragte eventyret og gyset ind i danske dagligstuer. Svend Petersen var den populære studievært, og historien om vognstyrer Erik Thorn fra linie 10, der quizzede sig til den store gevinst på 64.000 kr. og en stilling på Risø for sin viden om atomfysik var bedre end nogen roman. Volmer Sørensen var i topform som show-master i de store udsendelser til fordel for Ungarn i radio og fjernsyn. Alt fra kunst til reklamepenge kunne omsættes i penge til et nødlidende folk. I 60erne blev Otto Leisner populær med ”Pladeparade” på TV. En gang hvert andet år kom der et omrejsende tivoli, Pallis Tivoli, til byen. I 1963 har jeg i min dagbog skrevet, at jeg hver aften i den uge, det lå der, var deroppe sammen med veninder. Mange af forlystelserne var for små børn, men for os var luftgyngerne det bedste. Vi tog mange ture og kom uhyggeligt højt op. Heldigvis skete der aldrig noget. Det gjorde det heller ikke mindre spændende, at det var flotte unge fyre, der passede luftgyngerne."}]}, {"title": "Ferier i Skagen", "blocks": [{"type": "para", "text": "Mit store nummer var at komme på ferie hos Moster og Ib i Skagen, især mens de stadig boede i lejlighed i Vesterport. Morfar byggede hus til dem på Skagavej 19 i 1961. Lejligheden, de havde, var utrolig hyggelig, og de fik ret tidligt fjernsyn. Ib var postbud i rød uniform, og han cyklede rundt i de hyggelige gader med post hver dag. Jeg tror også, han fik tid til at drikke en kop kaffe indimellem. Moster arbejdede på Brøndums Hotel som servitrice, men ikke hele året rundt. De to forstod rigtigt at hygge om mig, og Moster lavede mine livretter – hun var en knag i et køkken. Jeg legede også med Ibs søsters datter Lene, som desværre i efteråret 2004 pludselig døde. En sommer havde jeg fået lov at tage Ulla med på ferie i Skagen. Mens vi var der, døde en af Ullas klassekammerater pludselig. Det gjorde stort indtryk på os piger, og mor sendte dødsannoncen til os. Han hed Willy og var 12 år. Jeg gik i klasse med hans lillesøster Kirsten. Det var også hos Moster og Ib, at Ulla og jeg en aften så en kæmpeedderkop komme pilende hen over gulvtæppet i stuen, mens vi sad og hyggede os foran fjernsynet. Vi fik hurtigt trukket fødderne op under os, men edderkoppen forsvandt under gardinet, og selvom Ib gennemsøgte stuen, kom den ikke frem. Den var så stor og lådden, at den kunne ligne en giftedderkop, som var kommet fra de varmere himmelstrøg skjult i en last med bananer. Det forestillede vi os i hvert fald."}, {"type": "para", "text": "Mor tog også til Skagen om sommeren og arbejdede på Brøndums Hotel. Det var, inden hun fik Per. Jeg besøgte hende somme tider sammen med far, og så skete det, at jeg blev præsenteret for nogle af de fine gæster, der boede der. Jeg havde en autografbog, som mor havde med derop. Deri skrev mange af de berømte gæster, ofte med en personlig hilsen til mig. Lidt sjovt er det, at min mosters søn Jens Christian i dag arbejder på det samme hotel. Af meget kendte personer, som har skrevet i min lille lyserøde Pukautografbog, er Ellen Winther, Jeanne Darville, Helga Ancher, Holger Fællessanger, Ib Mossin, ”Lille Per”, Rudi ”Mie” Hansen, Thorkild Bjørnvig, Soya, H.C.Hansen, Arveprins Knud og Arveprinsesse Caroline Mathilde, Henry From, Maria Garland, Osvald Helmuth, Lise Ringheim, Henning Moritzen og Herman D. Koppel."}, {"type": "figure", "caption": "Brøndums Hotel vinteren 1954. Mor sidder lidt til venstre for Dantoft, som var mor og mosters bedste kollega og veninde", "page": 42, "file": "assets/images/p042_049.jpg", "dim": [860, 626]}]}, {"title": "Københavnertur 1959", "blocks": [{"type": "para", "text": "Min onkel Helge var blevet forlovet med en feriepige fra København i 1958. Hun hed Tove Sønderholm og var eneste barn af Hertha og Helge Sønderholm, der boede i en lejlighed i Kronborggade 24. Med årene kom vi til at kende dem godt, idet vi besøgte hinanden, når lejligheden bød sig. De var vældig søde og gæstfrie, og vi havde det hyggeligt sammen. Herthas mor og moster boede i en stor herskabslejlighed på 5. sal på Jagtvej 11. Til lejligheden hørte en 6. sal, hvor Helge lejede sig ind, da han flyttede til København. Jeg beundrede Tove, som var 9 år ældre end mig og også havde fødselsdag den 12. november, fordi jeg syntes hun var sød, pæn, smart, havde langt sort hår og var københavner. Og så arbejdede hun ved telefonselskabet KTAS."}, {"type": "figure", "caption": "Tove 18 år – Merete 9 år", "page": 43, "file": "assets/images/p043_050.jpg", "dim": [525, 763]}, {"type": "para", "text": "I august 1959 fik vi lov til at låne ovennævnte flotte herskabslejlighed i en uge, fordi mormoren og mosteren var ude at rejse. For mig var det som et eventyr at få lov at bo under de forhold. Om morgenen gik far efter rundstykker, og vi tre sad badet i sol i den smukke karnap og indtog morgenmaden. Vi oplevede meget på den tur, som var min første til København. Den første del af oplevelsen var sejlturen fra Ålborg til København, for dengang gik der færge. Af seværdigheder husker jeg Zoologisk Have, Amalienborg, Nyhavn, Den lille Havfrue, Danmarks Akvarium med den elektriske ål, Tivoli, Bakken og Cirkusrevyen, hvor årets hit var replikken ”…og så ta’r vi den én gang til for Prins Knud”, og hvor det kostede 15 øre at komme på toilettet. Vi spiste frokost på Skovrider Kroen i Charlottenlund og betalte 29,40 kr. for 5 frokost med 2 øl og 3 vand. Vi kørte med sporvogn for 55 øre og handlede i Daells Varehus og Illum. En aften var vi til landskamp i Idrætsparken, hvor Danmark spillede mod Island. Ved den lejlighed så jeg Kong Frederik 9. Vi sad på Hovedtribunen til 11 kr. pr. billet og så bl.a.Tommy Troelsen, Tove 18 år – Merete 9 år Henning Enoksen og Erik Jensen kæmpe for Danmarks ære. Jeg syntes, det var sjovt, at en af spillerne hed det samme som min far. Kampen endte 1-1. En anden aften, som nok var lidt sjovere for mig, var vi i Palladium og se ”Kærlighedens Melodi” med Nina og Frederik og Louis Armstrong. Jeg syntes, at Nina og Frederik var det perfekte par, og jeg elskede musikken. Men et af højdepunkterne var helt sikkert turen til Landskrona i Sverige, en sejltur, der udgik fra Tuborg Havn om morgenen og retur om aftenen. En børnebillet kostede 2 kr. Alt var dengang billigt i Sverige, så vi har sikkert haft en god forsyning af billige cigaretter med hjem, selvom det, jeg bedst husker, var chokolade og lakridskonfekt i store mængder."}, {"type": "figure", "caption": "Far og Calle", "page": 43, "file": "assets/images/p043_051.jpg", "dim": [700, 451]}]}, {"title": "Andre udflugter", "blocks": [{"type": "para", "text": "Selvom vi ikke fik bil før i 1969, var mor og far gode til at arrangere udflugter. Det skete, at far lånte Møllers bil, men ellers lejede vi en bil uden fører eller var sammen med venner, som havde bil. Mor fik aldrig kørekort, heller ikke da vi selv fik bil. Hun hævdede, at det var fars skyld, fordi han ikke ville have, at hun kørte, men sandheden var en anden. Mor var altid bange for at køre i bil og så helst, at det var far, der sad bag rattet, selvom jeg kendte mange, der var bedre til at køre bil end ham. Sandheden var, at hun ikke turde få kørekort og selv sidde bag rattet. Når vi skulle til stranden, var det næsten altid Sæby, vi tog til, hvilket resulterede i, at jeg senere syntes, at Vesterhavet var for barskt. Jeg har fået fortalt, at jeg, første gang jeg var ved Sæby Strand i en alder af 2-3 år, spontant udbrød: ”Sikke i stur balli wåj” (sikken en stor balje vand), et tegn på at min begrebsverden ikke var nået ud over baljestadiet. Af andre foretrukne udflugtsmål kan også nævnes Sæbygård Skov, Hals, Hammer Bakker, Tversted, Voerså, Aså og Lyngså samt Løkken, Blokhus, Lyngby Mølle og Zoologisk Have i Ålborg. Det bedste, jeg vidste, var, når mor pakkede frokostkurven, og vi drog af sted, enten alene 3, eller senere 4, da Per kom til, eller sammen med Borups eller senere Elbo og Vibeke med børn. I juni 1961 tog vi på en tur til Rebild Bakker for at være sammen med Calle Beck, som var på sanatorium i Skørping. Calle havde tuberkulose og var somme tider indlagt, når sygdommen var værst. Vi havde lånt Ellens fars bil, og Ellen var naturligvis med. Vi hentede Calle på Sanatoriet og kørte til Rebild Bakker, hvor vi nød frokosten, som mor havde pakket. Jeg husker Calle som en høj tynd mand med en grim hoste. Ofte lå han i sengen men stod op, når vi kom på besøg. Så sad han i sin stol iført stribet pyjamas og hev efter vejret. Jeg havde ondt af ham, for han var vældig sød over for mig. Det var også hårdt for Ellen og deres to piger, Jonna og Lone. Den 16. juli 1963 døde Calle på Hjørring Sygehus."}, {"type": "figure", "caption": "Leo ved sommerhuset i Kulhuse", "page": 44, "file": "assets/images/p044_052.jpg", "dim": [675, 451]}, {"type": "para", "text": "I juli 1961 rejste jeg til København en uge sammen med Erik, Leo, Helge og Tove. Undervejs var vi på Hjerl Hede, som jeg syntes var meget spændende. Efter at have været rundt i København, hvor vi bl.a. oplevede Danmarks første drive-in-bio, Villabyernes drive-inbio, hvor en billet kostede 6 kr., tog vi til Kulhuse, hvor Helge og Tove havde købt sommerhus. Det var virkelig luksus dengang, men dejligt for dem, idet de jo boede trangt på 6. sal på Jagtvej. Jeg råhyggede mig virkelig i sommerhuset sammen med mine dejlige onkler og tante samt Leo, som var fuld af sjov. Vi fik spillet en del fodbold og spist mange ærter i de dage."}]}, {"title": "Min bror Per bliver født", "blocks": [{"type": "para", "text": "Jeg havde i mange år lagt sukker i vinduet til storken, fordi jeg bildte mig ind, at jeg gerne ville have en lillesøster eller lillebror. Der skete bare ikke noget, før jeg var 10 år. Jeg havde da godt lagt mærke til, at mor begyndte at gå i nogle store bluser eller kitler, men vi var jo ikke så oplyste dengang, så det hæftede jeg mig ikke yderligere ved. Ikke før mor en dag stod og strøg i stuen og så pludselig sagde: ”Du skal have en lillebror”. Da gik det pludselig op for mig, at det ønskede jeg mig i virkeligheden slet ikke. Jeg befandt mig fint med at være enebarn, bildte jeg mig ind. Jeg havde mine forældres fulde opmærksomhed, og det skulle der ikke ændres ved. Jeg husker ikke, hvad jeg svarede mor, men jeg gik straks ud på toilettet, foldede hænderne og bad til Gud om, at det ikke var sandt. Det var også lidt flovt dengang, når ens mor gik rundt med stor mave. Nogle af drengene drillede mig i skolen, og et par af mine ikke-veninder var med på samme galej."}, {"type": "para", "text": "Heldigvis hørte Gud ikke min bøn, for den 24. juli 1960 blev Per født. Jeg havde forinden fået mit eget værelse, og jeg husker far komme stolt ind og vække mig om morgenen med det glade budskab, at jeg havde fået en lillebror. Jeg sprang straks ud af sengen og løb ind i soveværelset, hvor mor lå med Per, og fra den dag af var han mit et og alt. Jordemoderen var der stadig, og nogen var i gang med at lave ”jordemoderkaffe”, som det hed dengang. Dagen blev rigtig hyggelig, for mine bedsteforældre og flere onkler og tanter kom på besøg. Jeg blev sendt op til skomager Heidelbach, som havde håndkøbsudsalg, for at købe en lyseblå sut. Den dag havde jeg ikke noget imod at blive sendt op i byen, og jeg fløj af sted så let som nogen fjer. Jeg håbede hele vejen på at møde nogle af mine kammerater, som jeg så kunne fortælle den gode nyhed."}, {"type": "figure", "caption": "", "page": 45, "file": "assets/images/p045_053.jpg", "dim": [860, 628]}, {"type": "para", "text": "Per kunne ellers nemt være blevet født på Frederikshavn Stadion, for der sad mor næsten hver søndag sammen med far og uddeler Møller. De var inkarnerede fans af Frederikshavns 1. divisions fodboldhold, som dengang havde Harald Nielsen som centreforward. Derfor lå det i luften, at Per skulle være fodboldspiller."}, {"type": "para", "text": "Da Danmarks landshold i fodbold senere på året var med ved OL og nåede til semifinalen, fik vi lov at se kampen hos Møllers. De havde TV men skulle selv i byen den aften. Derfor gav de far nøglen, og så kunne han og kommiserne med familier boltre sig i den pæne stue, bare de huskede at slukke for al lys og ild, inden de gik hjem. Sådan lød fru Møllers ordre. Per lå sød og stille i sin lift hele aftenen, hvilket mor var glad for, for det var næsten for spændende, da målmand Henry From klæbede sit tyggegummi på målstolpen inden det berømte straffespark. Kampen mod Ungarn endte 2-0 til Danmark, og så var sølvet i hus. Næsten al sport blev dengang kommenteret af hele Danmarks Gunnar ”Nu” Hansen, som i år kunne være blevet 100 år. Han leverede reportage i verdensklasse, og hans stemme og begejstring fik folk til at rejse sig fra stolene. Sådan tryllebandt den legendariske radio- og TVreporter nationen, når danske idrætsfolk var i kamp. Da Harald Nielsen så kom hjem fra Olympiaden med sølvmedaljen om halsen, var jeg med Lone Beck i Frederikshavn for at tage imod denne helt, som var alle pigers drømmefyr, også min, selvom jeg kun var 11 år. Meget hurtigt fik jeg lov at komme ud og køre med Per i barnevognen, en meget flot blå barnevogn i et dyrt mærke (PMK) og splinterny, sponsoreret af morfar. Jo, intet var for godt til denne knægt, hvis navn forblev en hemmelighed indtil dåben, så han i starten kun hed Lillebror. Elbo og Vibeke havde fået Lars i december, så en af mine veninder spurgte tit om lov til at køre med ham, så vi kunne følges ad."}, {"type": "figure", "caption": "", "page": 45, "file": "assets/images/p045_054.jpg", "dim": [523, 531]}, {"type": "para", "text": "Jeg lærte hurtigt at skifte ble og passe Per, når mor og far skulle i byen, og det skete ikke så sjældent. Det havde jeg aldrig noget imod, for jeg husker ham som et nemt barn. Jeg påtog mig i det hele taget lidt af en moderrolle over for ham. Jeg elskede at nusse omkring denne dejlige knægt, og det bedste var, når han lagde sine buttede arme om min hals. Hvis vi var alene hjemme, sov vi sammen i fars seng. En gang havde Per i løbet af natten suttet så meget på min hage, at jeg næste dag havde et kæmpe sugemærke, hvilket jeg ikke var særlig stolt af."}, {"type": "figure", "caption": "", "page": 46, "file": "assets/images/p046_055.jpg", "dim": [859, 610]}, {"type": "para", "text": "Når mor blev spurgt, hvor mange børn hun havde, og hun svarede, at hun havde to med 10 års mellemrum, var der folk, der spurgte: ”Hvor har du så alle dem derimellem?” Sandheden var, at mor ikke havde kunnet blive gravid før."}, {"type": "figure", "caption": "", "page": 46, "file": "assets/images/p046_056.jpg", "dim": [524, 726]}, {"type": "para", "text": "Per blev døbt den 18. september 1960 i Skæve Kirke med Moster og Ib som faddere. Dette var den kirke, vi følte os mest knyttede til. Jeg havde en lyseblå todelt kjole på, og mor havde den mørkeblå brokadekjole på, som hun havde fået syet til Aase og Viggos bryllup. Navnet var hemmeligt indtil det store øjeblik, hvor Per skreg så højt, at ingen kunne høre, hvad han kom til at hedde. Min mormor troede, at han kom til at hedde Erik, og syntes nok, at to Erik’er i familien var nok. Udover den nærmeste familie minus morfar, som var indlagt med dårligt ben, en slags åreknuder, som var noget, han til tider døjede med, var hr. og fru Møller med til barnedåben, som blev holdt i lejligheden, hvor soveværelset var blevet omdannet til spisestue."}, {"type": "para", "text": "Med et spædbarn i huset kunne man ikke nøjes med at vaske en gang om måneden. Der var hele tiden bleer, der skulle koges, og det foregik i en høj, sort gryde på et gas- blus i køkkenet. Jeg kan endnu fornemme dampen i køkkenet og lugten, der kom fra denne blesuppe."}]}, {"title": "Mad, drikke og slik", "blocks": [{"type": "para", "text": "Som barn var det meget traditionel mad, vi fik, såsom frikadeller med brun sovs, karbonader med stuvede grønærter og gulerødder, stegt flæsk med persillesovs, stegt lever, bøf med løg, brødæggekage og en gang om ugen fisk, som mor købte ved den omrejsende fiskemand. Om søndagen vankede der som regel grydestegt kylling, flæskesteg eller svinekoteletter. Det var, før salaten vandt indpas, så vi fik mest rødbeder, asier, græskar og syltetøj eller gelé til maden, og om sommeren agurkesalat. Vi fik altid to retter mad. Eftermaden kunne om sommeren være koldskål, frugtgrød eller ymer med revet rugbrød og puddersukker. Skulle det være ekstra godt, fik vi mejeristen til at hælde fløde i det øverste af ymeren. Om vinteren fik vi altid mælkemad, fx kogt mælk med tvebakker, kakaosuppe med ditto, rismelsgrød, sagosuppe, øllebrød, eller vandgrød, hvis vi skulle spare. Om søndagen fik vi ofte fromage eller budding, som vi spiste til tonerne fra ønskekoncerten, som var et ”must”. ”Den gamle gartner” og ”Hvide måge” hørte til repertoiret. Hos mormor var det også godt at spise, især om lørdagen, hvor hun altid bagte pandekager, og jeg husker endnu, når hun lavede klipfisk, hvilket mor aldrig lavede, af den simple årsag at hun ikke selv kunne fordrage det. Det var også hos mormor eller farmor, at der kom kiksekage på bordet, denne søde stive chokolademasse med lag af firkantede vanillekiks, som smagte noget så dejligt."}, {"type": "para", "text": "Mor lavede alt fra grunden, og hun kunne ikke drømme om at købe færdigretter, rødkål og rødbeder på glas eller købebrød. Hun var endda slem til at kritisere, hvis nogen gjorde det, for det var nu det sundeste at lave tingene selv. Hun glemte at tænke på, hvor usundt det var, at hun røg 20 cigaretter om dagen! Længe leve dobbeltmoralen."}, {"type": "para", "text": "Jo, vi levede godt, selvom far ikke tjente den store løn, men mor var god til at få meget ud af sine husholdningspenge. Mens farmor og farfar havde gård, faldt der da også en steg af i ny og næ. Før fryseren blev hver mands eje, var der noget, der hed kommunale frysehuse, hvor man kunne leje en plads i en fryser. Når min farmor og farfar slagtede, blev alt skåret ud og pakket i brune pakker med sejlgarnssnor og navn eller nummer på, og så gik turen i hestevogn ned til Skæve Frysehus, hvor alt blev lagt i en af de store frysere der. Der var en speciel lugt og meget koldt i dette hus."}, {"type": "para", "text": "Til daglig fik vi saftevand til maden, og om søndagen en sodavand eller hvidtøl, aldrig vin. Det var kun til store fester, at denne liflige drik kom på bordet. At drikke en hel sodavand var for mig komplet umuligt, så jeg delte med mor og senere med Per. Vand kom sjældent på bordet, og slet ikke til fester, for det var tegn på, at man var nærig eller fattig."}, {"type": "para", "text": "Jeg har vel været 9 år, da vi for første gang havde rejer i huset. Mor havde skaffet dem fra Skagen med skal på, så gæsterne skulle selv pille dem. Hvis der blev problemer, kunne mor vise dem, hvordan de skulle gøre, for hun arbejdede jo på hotel, hvor den slags var hverdagskost. Aftenen blev en stor succes, men rejerne blev også skyllet ned med øl og en enkelt snaps."}, {"type": "para", "text": "Det var meget sjældent, at jeg fik slik, til trods for, at min mormor havde en slikbutik. Det skete, at jeg fik lov at købe for 10 øre pinocchiokugler, når jeg hentede cigaretter til mor. Kuglerne kostede 1 øre pr. stk. Ellers kunne 10 øre også bruges til en salmiakstang, som det en overgang var mode at rulle sammen og putte ned i en plastik mælkekapsel. På den måde kunne den vare rigtig længe, i og med at vi ikke kunne bide af den men i stedet gik rundt og slikkede på den. Piratos og spejderhagl var også noget af det gode slik, der kradsede i smagsløgene. På et tidspunkt var det sejt at gå rundt med en ”cigaret” i munden, enten af lakrids eller tyggegummi, eller en lakridspibe. ”Cigaretter” kunne også fås i plastik med kulørt mundstykke, der smagte af mentol, når man ”inhalerede”. Jeg kendte navnene på al slik, fordi jeg af og til passede mormors slikbutik, hvorfra jeg også husker ”guldmønterne”, hvori der var gemt chokolade eller tyggegummi, samt karamelstænger og flødeboller, som var betydelig større dengang end i dag. En flødebolle kostede 25 øre."}]}, {"title": "Pligter", "blocks": [{"type": "para", "text": "Da vi jo hverken havde landbrug eller have, havde jeg ikke de helt hårde pligter som barn, selvom de dengang kunne være trælse nok, såsom at hente mælk på mejeriet. En daglig pligt var at rydde op og vaske op efter aftensmaden, og mor kunne godt rode temmelig meget, når hun lavede mad. Om foråret og sommeren var det lidt af en pestilens, idet jeg gerne hurtigt ville ud og lege med de andre børn, men der var ingen kære mor – jeg fik først lov at gå, når alt var i den skønneste orden. Senere blev dette fars opgave, for mor elskede at lave mad, men oprydning og opvask var hun ikke meget for. I min dagbog fra 1961-62 fremgår det, at jeg var temmelig involveret i de huslige pligter og hver dag hjalp mor med enten at gøre rent, vaske, hænge tøj op, rulle eller stryge. I samme periode blev jeg også inddraget i madlavning og bagning. I min konfirmationssang står der, at jeg havde fået 16 frikadeller ud af et halvt pund fars, hvilket var rekord: ”16 af et halvt pund fik, der sin mor hun overgik”. Episoden var fra dengang, Per blev født, hvor jeg fungerede som husmor den første uges tid. Jeg blev dog aldrig så dygtig til at lave mad som min mor, ej heller til at sy – sidstnævnte interesserede mig ikke, og mor forsøgte aldrig at lære mig det. Utroligt var det, at jeg, udover de huslige pligter, babysitningen og lektielæsningen, næsten hver dag havde tid til at være sammen med veninder."}, {"type": "para", "text": "Af sure pligter var vaskedagen, hvor jeg hjalp til, samt når der skulle syltes og henkoges. Der blev klippet runde stykker smørrebrødspapir, der passede ned i glassene med syltetøj og gelé. Dem dyppede vi i atamon og lagde oven i glassene, så indholdet kunne holde sig vinteren over. I stedet for låg bandt vi celofan om glassene med elastik, og så blev det hele båret ned i kælderen og stillet i et lille rum, hvor der var hylder til formålet. Jeg blev tit sendt i kælderen efter et glas syltetøj, men selvom vi havde taget vores forholdsregler, hændte det alligevel, at der var mugpletter øverst i glassene. Det var helt naturligt bare at fjerne pletterne og så spise resten med god appetit, men det år, der var ørentvister i de syltede kirsebær, satte vi grænsen – da røg hele indholdet ud."}, {"type": "para", "text": "Af dejlige pligter var at passe min lillebror, lægge vasketøj sammen og stryge. Hver dag efter skole passede jeg Per, men han var så nem, at jeg blot tog ham med hen til veninderne eller passede ham, når de var hos mig. Nogle af mine veninder havde også mindre søskende, som han legede med, mens vi læste lektier. At hjælpe til med at bage var også sjovt, især når man fik lov til at slikke skålen. Mor var flink og lod et godt lag sidde tilbage til mig. Det var, før frygten for salmonellaen meldte sig."}]}, {"title": "Julen", "blocks": [{"type": "para", "text": "Julen var noget ganske særligt, da jeg var barn, og den julestemning, som jeg tidligere har nævnt, og som mange børn sikkert oplever, lader sig vanskeligt genfinde i det voksne liv. Mor var vild med julen, og når vi nåede til den 24. december, vrimlede og vrikkede det med julepynt, ikke for meget og aldrig grimt og usmageligt, for mor havde en god smag, også hvad angik julepynt. Mens vi boede i lejligheden, blev soveværelset hvert år omdannet til ”julestue”. Sengene blev flyttet ind på mit værelse, og jeg sov i stuen. Så blev spisebordet flyttet ind i soveværelset, så der var plads til juletræet i stuen. Jeg kan endnu mærke duften af gran og nelliker i den nye stue, som nu pludselig var blevet varmet op."}, {"type": "para", "text": "Der var mange forberedelser til denne højtid. Mor lavede alt selv, dog ikke brune kager. Det prøvede hun kun én gang, hvor dejen ikke ville hænge sammen, og hun endte med at levere det hele op til bageren, som så bagte dem for hende. Siden den tid købte hun altid de brune kager, indtil hun startede traditionen med at bage honningkager, som så erstattede de brune, men det var først, da Lars blev født. Den tradition har Lars og jeg ført videre. Ellers bagte vi finsk brød, kanelkager, vanillekranse, jødekager og pebernødder. Far blev også sat i sving i bogstaveligste forstand, idet han skulle dreje svinget på den maskine, der spyede vanillekransene, kanelkagerne og de finske brød ud. Det var også far, der sammen med mig lavede pebernødderne, for alt det trælse arbejde undgik mor helst. Men vi hyggede os med det, og senere kom Per til, så vi var et godt team."}, {"type": "para", "text": "Så var der sirupslagkagerne, som var et ”must”. Mor bagte en ordentlig stak og lagde dem sammen, så vi havde noget, hvis der kom et fremmed menneske. Før fryserens tid kan jeg se mig selv hænge ud af soveværelsesvinduet i januar måned og fodre fuglene med de lagkager, der ikke var blevet spist, men ”fuglene skal også leve”, sagde mor til sit forsvar. Vi havde dog tit gæster i julen. Det bedste, jeg vidste, var, når mor og far fik den idé, at de fra Kristines telefon ville ringe enten til Poulstrup eller Mellergård for at høre, om de ikke kunne starte Forden (de havde begge en HGF) og komme til kaffe om aftenen, selvfølgelig sammen med børnene. Jeg glædede mig helt vildt, og det var altid hyggeligt at have dem på besøg. Jo, mor og far var meget gæstfrie."}, {"type": "para", "text": "Udover bagningen blev der også lavet medisterpølse, leverpostej og sylte, og der blev kogt flæsk og grønlangkål. Sidstnævnte blev hentet i Mellergård hos min faster Grethe og hendes mand Peter. Sjovt var det ikke for far det år, hvor han skulle rense dem for grannåle, fordi de havde stået under en granhæk. Det var ikke fri for, at man kunne få en grannål eller to i munden den jul."}, {"type": "para", "text": "En tradition, som jeg har ført videre, var konfekten, som vi selv lavede. Vi æltede en del flormelis i den ægte marcipanmasse og blandede frugtfarve i, så vi havde 4 forskellige farver dej. Dem rullede vi ud, penslede med vand og lagde oven på hinanden i 3 lag. Det hele blev skåret ud i små snitter og stillet til tørre."}, {"type": "para", "text": "Nogle år lavede mor en julekalender til mig af små tændstikæsker, 24 stk. limet sammen i 6 rækker. Hver morgen rykkede jeg spændt en ”skuffe” ud og fandt et stykke slik. Jeg troede, som alle andre børn, også på julemanden, og mor stillede grød op til ham på loftet, men jeg så aldrig skålen, når mor hentede den ned. Hun sagde, at den var tom, og så troede jeg på det."}, {"type": "para", "text": "Mor syede mange gaver til jul og var meget hemmelighedsfuld, for nogle af dem var til mig. Jeg selv broderede gaver og gav til mormor og farmor. Det skete også, at jeg fik held til at brodere noget til mor, som hun ikke havde haft fingrene i – så kan det nok være, jeg var stolt juleaften."}, {"type": "para", "text": "I mange år holdt vi juleaften i Skæve, oftest hos mormor og morfar, men også i Sillebak hos farmor og farfar. Kun et enkelt år holdt vi juleaften i lejligheden, nemlig i 1963, men grunden dertil husker jeg ikke. Jeg var ca. 20 år, da traditionen med at holde juleaften hos bedsteforældrene stoppede, sikkert fordi min morfar døde. Mens vi tog til Skæve og holdt jul og var 12 personer juleaften, kunne jeg ikke tænke mig andet, men i dag kunne jeg ikke tænke mig at være så mange på denne aften. Vi havde ikke tradition for at gå i kirke juleaften af to årsager. Den ene var, at dengang vi holdt juleaften på Konditoriet, havde alle så travlt op til højtiden, at der simpelthen ikke var tid til det. Et år blev der hængt køkkengardiner op lige inden middagen, og der var altid gaver, der skulle pakkes ind i sidste øjeblik. Den anden årsag var, at vi ikke havde bil, og kirken lå uden for byen, både i Thorshøj og i Skæve. Mens morfar levede, fik vi altid risengrød først, inden vi fik andesteg, efterfulgt af fromage til dessert. Det var et ordentligt måltid, og mine onkler drillede mig altid med, at nu skulle de hen og hvile sig ovenpå maden, inden de kunne danse om juletræ."}, {"type": "para", "text": "Vi havde nogle hyggelige juleaftner, men ikke mindre hyggelige var de efterfølgende juledage, hvor vi også var sammen. Juledag lavede vi ikke så meget, men om aftenen skulle onklerne lige op til tante Karen og gemme hendes kaffekande – sådan noget gjorde man både juledag, nytårsaften og Hellig Tre Kongers aften. Bagefter legede vi panteleg eller spillede bankospil. 2. juledag var en travl dag for kvinderne, der skulle stå i køkkenet, fordi mormor havde fødselsdag, og der kom mange gæster. Morfar havde 9 søskende, hvoraf de 6 med familier altid kom, i hvert fald i de første mange år af min barndom. Det drejede sig om bror Maltha, den yngste i flokken af 10. Han var gift med Emma og havde en slagterforretning i Nørresundby. De var dem i familien, vi så mest til. Det må have været godt at være slagtermester, for deres hjem var fyldt med ægte malerier og kongelige porcelænsfigurer. De havde to sønner, Erik og Brian. Erik var gift og havde to piger, Majbrit og Lone, som var lidt yngre end mig, men ikke mere end at vi legede godt sammen. Ofte havde Maltha hele familien med 2. juledag. Så var der bror Hans og dennes kone Sørine, en trivelig dame, som Hans havde fuld tillid til, for hans valgsprog var: ”Det ser Sørine sil” (det siger Sørine selv), når han skulle overbevise andre om sandheden af sine påstande. Hans havde et lille husmandssted uden for Skæve, som hed Guldbæk, hvor der voksede en stor børneflok op. Desværre døde mange af børnene, enten under fødslen, som små, som unge eller som voksne. Hans kunne huske langt tilbage, og når snakken gik lystigt til, kunne man høre ham sige: ”Det var det or, dej bråge fek kal” (det var det år, den brogede fik kalv). Og hvis folk ikke troede på det, kunne de bare spørge Sørine. Jeg skal heller ikke glemme at nævne søster Ingeborg og dennes mand Ejnar, som boede i Ålborg og havde to sønner, Poul Erik og Jørgen. I Ålborg boede også søster Bertha og hendes halvkriminelle mand Simon. Han boede ikke så tit hjemme, for hvis han ikke var på farten, sad han i spjældet. Men han var godheden selv, og holdt altid sjov med os børn. Han kunne som regel skaffe fribilletter til dit og dat, og der gik mange historier om ham i familien. De havde tre døtre, Edel, Lissie og Lisbeth og en søn Møller, som var gift med Sigrid. Møller var født uden for ægteskabet og var vokset op sammen med de yngste af morfars søskende. Han og Sigrid var altid med, når der foregik noget i familien. De var de sødeste mennesker, og et meget flot par, så det var ikke så sært, at de fik kønne børn. Deres datter Hanne blev Miss Danmark i 60erne. Søster Signe og hendes mand Laurits boede i Try, og endelig var der den yngste søster Mie og hendes mand Mynke, som boede i Silkeborg og havde to fine døtre. Mie ville gerne være smart og ungdommelig, og selv som 80-årig gik hun i lange hvide lakstøvler og korte skørter. Af en eller anden grund var man i familien meget imponeret over Mynke og behandlede ham, som om han var direktør, selvom han ”kun” var værkfører. Sikkert fordi vi selv boede på landet, så vi op til den del af familien, som boede i Ålborg og Silkeborg og betragtede dem som den ”fine” gren af familien. Mormor havde ikke så stor en familie som morfar. Mormors mor, Christine, var død i barselseng, da hun fik Alfred, og mormor kun var 7 år. Derpå havde Bedstefar, som var født den 28. marts 1878, giftet sig med Christines søster, Maren, som var kommet for at være hans husbestyrerinde, og de havde fået børn sammen. Maren, som var født den 17. november 1885, døde desværre også tidligt, nemlig den 11. maj 1920, hvorefter Bedstefar fik en ny husbestyrerinde, som også hed Maren, og som jeg tydeligt husker. Den af mormors søskende, der stod hende nærmest, var helbroderen Alfred, som havde automobilværkstedet med tilhørende cykelforretning i Skæve. Karen og Alfred havde ingen børn men en schæferhund ved navn Bella. Karen led af eksem og ville derfor næsten aldrig med i byen, så Alfred kom oftest alene. Men når det en enkelt gang ved særlige lejligheder skete, at Karen var med, kom der gang i kludene, for hun var ikke kedelig. Så var der halvsøster Krista, som næsten altid var syg, halvsøster Gerda, som boede i Bouet og rakte uklar med familien over arven efter Bedstefar, og endelig søster Ida, der var gift med Anton, som havde et savskæreri i Fredericia. Mormor havde også haft en lillebror, August, som var død fra sin kone Ella og 4 børn i en ung alder. Den ene af sønnerne har i dag Herskind Savskæreri. Lidt sjovt, at Bedstefars beskæftigelse gik i arv til to i familien. Det var på grund af afstandene ikke så tit, at mormor så sine søskende."}, {"type": "para", "text": "Efterhånden som familiens ældste begyndte at falde fra, blev selskabet mindre og mindre til mormors fødselsdag, men vi, de nærmeste, mødte trofast op. På et tidspunkt var der tradition for, at mor havde sin familie til julefrokost 1. juledag, hvilket også var hyggeligt. Men tredjedagen sammen, altså mormors fødselsdag, kunne godt være anstrengende, især hvis mor havde en af de dage, hvor hun var lidt halvsur, fordi hun hellere ville have været hjemme. Moster kunne også godt have ondt af sig selv, fordi hun skulle stå i køkkenet, og Ib kunne have en af de dage, hvor han var nem at drille. Fandt onklerne først ud af det, kunne de godt tirre ham, og så gik bølgerne højt. Ib havde for vane at beklage sig over, at han havde haft travlt med posten op til jul, hvilket gav udslag i, at Erik og Helge antydede, at hele Danmarks post så måtte have været over Skagen den jul. Dette var nok til, at Ib kunne forlade bordet i arrigskab. Det var sikkert ikke så slemt, som det lød i mine ører, men jeg fandt det ikke hyggeligt og drømte mig tilbage til de dage, hvor vi legede panteleg."}, {"type": "para", "text": "Julen var en dyr tid, men vi havde heldigvis ”Julens Glæde”. Dette var en slags opsparing, som foregik på den måde, at en dame kom rundt en gang om ugen og opkrævede penge, som blev sat ind på en bog. Man bestemte selv beløbets størrelse, fx 5 eller 10 kroner. Til jul fik man så hele beløbet udbetalt, hvilket gjorde det nemmere at få pengene til at slå til. Far forsøgte ellers hver uge at vinde penge i tips. Havde man 12 rigtige, kunne man blive meget rig. Det var spændende hver søndag at sidde med hovedet inde i radioen, når de 12 rigtige blev læst op. Jeg mindes kun, at det blev til småbeløb og aldrig den store gevinst."}]}, {"title": "Et år i USA", "blocks": [{"type": "figure", "caption": "", "page": 51, "file": "assets/images/p051_057.jpg", "dim": [860, 615]}, {"type": "para", "text": "Min morfar havde tre brødre, der var emigreret til USA omkring 1915, Martinus, Julius og Christian. De var alle blevet amerikansk gift, men kun Christian havde fået børn, to døtre. Martinus havde sidst besøgt Danmark i 1935, men på morfars fødselsdag, den 15. januar 1961, ringede telefonen, og i den anden ende af røret lød Martinus’ stemme. Det var så stor en sensation, at det næste dag var omtalt i avisen, at Jens Christensens bror fra Denver, Colorado havde ringet for at gratulere ham. Martinus havde fødselsdag samme dag og var nøjagtig 10 år yngre end morfar. Denne telefonopringning blev optakten til et eventyr for mig, for om sommeren kom Martinus på besøg sammen med sin kone, Margaret. Under besøget mødte de selvfølgelig også mig, og dette resulterede i en invitation fra dem, da de var tilbage i USA."}, {"type": "para", "text": "Der kom et brev til mine forældre, hvori der stod, at Margaret og Martinus gerne ville invitere mig til at komme og bo hos dem i et år. Jeg skulle gå i en lutheransk skole, og de ville betale alle udgifter, der var forbundet med opholdet. Det var noget af en mundfuld, og jeg ved ikke præcist, hvor lang tid der gik, inden mine forældre svarede. Som forælder ville jeg have haft svært ved at skulle træffe en sådan beslutning, og dengang var det noget af en sensation. Heldigvis for mig takkede de ja til invitationen, og det har jeg siden været dem dybt taknemmelig for, for det år kom til at betyde meget for mig og mit liv senere."}, {"type": "para", "text": "Afrejsen blev sat til den 27. juni 1962, og jeg glædede mig helt vildt. I januar var vi til møde med skoleinspektør Bramsen for at spørge, om jeg kunne få fri et år og simpelthen springe 6. klasse over. Det var tilsyneladende ikke det store problem, for jeg var rimelig godt med i skolen."}, {"type": "para", "text": "Forberedelserne var spændende. Mor bestilte en kæmpestor kuffert i Daells Varehus. Den lå fremme i meget lang tid inden afrejsen, og hver gang, vi købte noget nyt undertøj, strømper eller andet tøj, blev det lagt i kufferten, hvis indhold voksede, jo tættere vi kom på juni. Af naturlige årsager havde jeg aldrig før ejet en BH eller en hofteholder, men det mente mor nu var tidspunktet, så disse to mærkelige beklædningsgenstande fandt også vej til den nye kuffert. Gaver blev også købt og lagt deri."}, {"type": "para", "text": "En dag måtte vi rejse til København for at få et visum til mig på Den amerikanske Ambassade. Som dokumentation skulle de se det brev, som Margaret og Martinus havde sendt med invitationen. Og en dag kom der en journalist fra Vendsyssel Tidende for at interviewe mig. Jeg var det store samtaleemne i byen og på skolen. På et tidspunkt tænkte jeg: ”Hvor er det synd for mine kammerater – de har slet ikke noget at glæde sig til”. Det var naturligvis ikke sandt. De eneste, der ikke glædede sig på mine vegne, var nogle af min morfars søskende. Hans fine søster Mie skulle have sagt: ”Hvad skal den tøs derover efter – hun lukker jo aldrig munden op”. Det hørte jeg flere år senere, men da var jeg ligeglad. Hun var nok bange for, at jeg skulle bruge alle deres penge, så der ikke blev noget at arve."}, {"type": "para", "text": "I skolen havde vi endnu ikke haft engelsk, og da jeg ikke kunne tage til USA med så ringe en baggrund, måtte jeg forsøge at lære lidt. I starten læste far med mig, hvilket var hyggeligt, men senere aftalte vi med Lone Beck, som gik på gymnasiet, at jeg mod betaling skulle gå en aften om ugen til engelsk hos hende. Det gik også fint, men jeg var langt fra udlært, da jeg tog af sted."}, {"type": "figure", "caption": "Afsked med veninderne Birte Skov (forrest), Inga Billedet har jeg taget på mit værelse med mit nye", "page": 52, "file": "assets/images/p052_058.jpg", "dim": [598, 598]}, {"type": "para", "text": "Endelig oprandt den store dag, hvor mine forældre skulle følge mig til København. Jeg havde forinden holdt afskedskomsammen for veninderne, og aftenen før afrejsen havde hele familien været til kaffe for at sige farvel til mig."}, {"type": "para", "text": "Jeg havde fået mange gaver af venner og familie, og af Per havde jeg fået et sølvhjerte i afskedsgave. Mormor og morfar havde taget Per med hjem for at passe ham, idet han var for lille at have med til København. Det var hårdt at sige farvel til familien, men allerhårdest var det at tage afsked med Per. Den aften græd jeg mig i søvn. Jeg havde et billede af ham med til USA, og da jeg kom hjem igen, var det helt krøllet, så ofte havde jeg krammet det. Billedet ses på næste side."}, {"type": "para", "text": "Tidligt næste morgen tog vi rutebilen til Ålborg. Da vi kom op til stoppestedet, stod tre af mine veninder der for at sige farvel. Lisbet gav mig en venindebuket, Birte Carlsen en æske kattetunger, og min veninde Kisse to billeder. Forinden havde Lisbet og jeg forseglet vores venskab med en venindering. Rutebilen kørte igennem Skæve, og hvem stod der ved stoppestedet for at sige farvel en sidste gang? Det gjorde mormor – og så græd vi igen. Hun havde en æske chokolade med, hvilket var sødt af hende."}, {"type": "figure", "caption": "Var det så sært, at jeg havde svært ved at sige farvel", "page": 53, "file": "assets/images/p053_059.jpg", "dim": [520, 583]}, {"type": "para", "text": "Det var første gang, vi skulle prøve at flyve, men det gik fint. Vi skulle jo kun til København, hvor vi skulle bo hos onkel Helge og tante Tove. Om aftenen var vi, for at aflede tankerne, i Falkonercentret og se ”South Pacific”, men jeg husker ikke ret meget af filmen – mine tanker var andetsteds."}, {"type": "figure", "caption": "til Per? Kjolen var en gave fra Margaret og Martinus", "page": 53, "file": "assets/images/p053_060.jpg", "dim": [622, 860]}, {"type": "para", "text": "Den nat var også forfærdelig at komme igennem, og jeg havde mange sommerfugle i maven. Men jeg havde besluttet, at jeg ikke ville græde, mens mor og far så på det. Det løfte holdt jeg. Hvor må det have været svært for dem at sige farvel, vel vidende at der nu skulle gå et helt år, inden de havde mig hjemme igen. Jeg har tit beundret dem for denne beslutning. Dengang kostede en enkeltbillet til Denver 3000 kr. Der var ikke mange med flyet, som skulle mellemlande i New York. SAS havde lovet at passe godt på mig og få mig fra den ene lufthavn i New York til den anden. Det blev en svensk stewardesse, som hjalp mig, og jeg følte det hele som meget overvældende. I flyet fra New York var der mange passagerer, og jeg kom til at sidde ved siden af en neger, som det dengang hed. Det var den anden neger, jeg nogen sinde havde set. Den første havde jeg set på Skæve Konditori nogle år tidligere. Han var skoleinspektør i Ålborg og havde været i Skæve for at holde et foredrag."}, {"type": "para", "text": "Da flyet næste gang landede, stod jeg af. Jeg havde forventet, at der var en velkomstkomité for at tage imod mig, men jeg så ingen, jeg kendte. Jeg gik rundt inde i ankomsthallen i det, der føltes som meget lang tid, og jeg var på nippet til at begynde at græde. Men så tænkte jeg på mor, som altid sagde, at man skulle tælle til 10, før man gik i panik. Det hjalp."}, {"type": "para", "text": "Jeg havde af mormor og morfar fået et Kodak fotografiapparat til 58 kr., og inde i læderetuiet havde mor skrevet min amerikanske adresse. Jeg tog en hurtig beslutning, gik ud til en række taxaer, der holdt uden for bygningen, og henvendte mig til en taxachauffør. Jeg viste ham adressen, for pludselig kunne jeg ikke få et ord over mine læber. Jeg forstod ikke så meget af det, han sagde, men jeg forstod, at han sagde: ”You are in the wrong city, Miss”. Det viste sig, at vi var mellemlandet i Chicago men skulle videre med samme fly. Stewardessen havde ikke passet særlig godt på mig, men taxachaufføren fik nu fat på hende, og jeg kom med flyet, som landede i Denver til den fastsatte tid. Da jeg senere skrev hjem om denne udflugt, blev mor forfærdet, for det, hun forbandt med Chicago, var gangstere. Senere, da Per som 6-årig skulle flyve alene fra Ålborg til København, kunne mor ikke dy sig for at fortælle damen på SASkontoret om min oplevelse, hvortil denne bemærkede: ”Jeg lover Dem, frue, han står ikke af undervejs”."}, {"type": "figure", "caption": "New York – på vej ud i den store verden", "page": 54, "file": "assets/images/p054_061.jpg", "dim": [678, 860]}, {"type": "para", "text": "Mors onkel Martinus var ”General Contractor”, en slags entreprenør, som opkøbte huse, indrettede dem til lejligheder og lejede dem ud, fuldt møblerede. Da jeg var der, havde han 13 lejligheder og 3 værelser til udlejning. Margaret var pensioneret sygeplejerske. De boede i et stort hus i 3 etager på 2837 Federal Blvd., hvor jeg havde et stort værelse i kælderen med en bred seng."}, {"type": "figure", "caption": "", "page": 54, "file": "assets/images/p054_062.jpg", "dim": [588, 600]}, {"type": "para", "text": "Det første, jeg bemærkede, var, at væggene var plastikmalede og ingen billeder havde men store spejle. Desuden skulle jeg ligge med et lagen og undvære dyne, men da temperaturen var meget høj, 90 grader F i skyggen, klarede jeg mig. Den første uge græd jeg meget, og jeg forstod ikke så meget af det, der blev sagt. Martinus havde glemt det meste af sit danske, og jeg skulle jo også lære engelsk. Jeg var desuden dårlig p.g.a. ”the high altitude”, hvilket de gav som undskyldning for min manglende appetit og mit dårlige humør. Sandheden var, at jeg var ”homesick”, et af de første ord jeg lærte. De gjorde ellers alt for, at jeg skulle føle mig hjemme. Med i lufthavnen havde været Margarets niece Sharon, som var to dage yngre end mig, samt Cindy og Crissy på hhv. 8 og 7 år, et par reservebørnebørn. Disse tre piger kom jeg hurtigt på bølgelængde med, og de hjalp mig igennem den første svære uge."}, {"type": "para", "text": "Det var overvældende for en pige som mig at komme til dette store land, hvor alting var storslået og flot i mine øjne. Mange ting var nye for mig og også meget spændende. I 60erne var forskellen mellem Danmark og USA enorm, når det gjaldt forbrugsgoder og levestandard. I dag vil jeg sige, at Danmark er kommet godt med og endda er foran USA på nogle områder."}, {"type": "para", "text": "Margaret og Martinus havde tre biler: to personbiler, hvoraf den ene var en rød og sort Packard, samt en pick-up truck. De havde vaskemaskine, forskellige elektriske maskiner i køkkenet, TV, klaver, skrivemaskine og m.m. Pengene lå og flød alle steder, i skuffer og løse i Margarets taske. Skulle hun betale, dykkede hun bare ned i tasken, og så fulgte der masser af sedler med op – det var jeg sandelig ikke vant til hjemmefra. TV var min helt store hobby. Der var udsendelser hele dagen på 13 kanaler, og jeg elskede Lucy Show og Flintstone."}, {"type": "para", "text": "Maden var meget anderledes end den danske mad, men for det meste god, og jeg fik hurtigt mine favoritter, såsom kylling, vandmelon og ”lemon pie”. Det var første gang, jeg smagte majs på kolbe, så jeg troede, at jeg skulle spise hele kolben, indtil jeg så, hvad de andre gjorde. Det var også første gang, jeg smagte vandmelon, pizza, burgere og pie. Jeg hadede pizza, sauerkraut, spinat og ”peanut butter”, og ”cherry pie” var jeg heller ikke vild med. Jeg havde imidlertid hjemmefra fået besked på, at jeg skulle spise det, der kom på bordet, så det gjorde jeg. Og når jeg blev spurgt, om jeg kunne lide maden, svarede jeg høfligt bekræftende. Det blev så fortolket på den måde, at jeg elskede pizza og ”cherry pie”, hvilket jeg absolut ikke gjorde, så de retter fik vi desværre rigtig tit."}, {"type": "para", "text": "Jeg skulle også vænne mig til, at Margaret bad bordbøn hver aften, hvilket man i øvrigt gør i mange amerikanske hjem. Når børnene var der, skiftedes vi til det, og jeg fik også tit lov. Det var lidt af en ære. Den religiøse påvirkning, jeg var udsat for i det år, jeg var i USA, har medvirket til, at jeg i dag er blevet stærkere i min tro på Gud."}, {"type": "para", "text": "Jeg blev præsenteret for nye traditioner, såsom amerikansk ”picnic”, hvor alle kommer med en ret, der så bli’r stillet på et langt bord. Efter maden er der forskellige aktiviteter, såsom sækkevæddeløb, hesteskospil eller volleyball, men ligesom det går allerbedst, og man har det allersjovest, er festen slut. Jeg oplevede også andre indkøbsvaner end dem, jeg var vant til. Jeg stiftede bekendtskab med de store varehuse og supermarkeder, hvor vi handlede stort ind. Der blev heller ikke sparet på tøj til mig – og jeg erhvervede mig mine første bermudashorts, som senere blev højeste mode i Danmark. Tøj var meget billigt – jeg fik mange kjoler, der kun kostede 35 kr."}, {"type": "para", "text": "Jeg har altid haft et noget strid og glat hår, som blev krøllet med krøllejern, da jeg var barn eller fønbølget hos frisøren. I USA lærte jeg at bruge curlers, som man ikke generede sig for at gå rundt med i supermarkedet. Jeg sov med dem om natten og led på den måde for skønheden, for de prak og stak."}, {"type": "para", "text": "Af mindre muntre oplevelser kan nævnes to begravelser, som jeg deltog i. Det gjorde et stort indtryk på mig, at kisten var åben. Den døde var balsameret og lå i sine fineste klæder, og folk defilerede forbi for at vise den døde en sidste ære. Den ene begravelse var med en af mine klassekammeraters mor, der pludselig var død, så det foregik fra den kirke, jeg tilhørte, Emmaus Lutheran Church. Jeg glemmer aldrig synet af kvinden, der lå der i sin fineste blå kjole og med sminket ansigt. Også de sørgende børn og nærmeste familie gjorde indtryk. Sjovere var det naturligvis at være med til et såkaldt ”Wedding Shower”, som bli’r holdt for den vordende brud i dennes hjem. Kun kvinder er inviteret, og de forventes at have en gave med til bruden. Vi var 20 den pågældende aften, som gik med at lege ordlege og gættekonkurrencer med præmier samt spise konfekt, nødder, bryllupskage og is. Alt i alt en festlig aften, men nødderne kunne jeg godt have undværet. Margaret og Martinus kendte nogle danske familier i Denver, blandt dem en gartnerfamilie, Gudmund Jensen, med tre døtre, hvoraf den yngste var 16 år, havde kørekort og sportsvogn. Og så boede de i en kæmpevilla med svømmebassin. De havde boet derovre i 12 år. Det var dejligt at besøge dem, hvilket jeg nogle gange gjorde alene, for så talte vi dansk, og de lavede dansk mad, fx bøf og jordbærgrød til ære for mig. Jeg så beundrende op til den 16-årige, for hun tog mig med på ture i sin sportsvogn og introducerede mig for den musik, teenagere lyttede til dengang, bl.a husker jeg, at vi dansede rundt til og sang med på ”If I had a hammer” med Trinny Lopez."}, {"type": "para", "text": "Et andet dansk par, som jeg kom til at kende, var Marie og Svend Sønderup, der var omkring de 50. For mig var de ældre mennesker, men sådan betragter jeg naturligvis ikke mig selv i dag. Svend arbejdede ved vandværket og havde tjent godt efter at være udvandret som 35-årig. Parret havde ingen børn. Vi besøgte dem i 1976, og de besøgte os, når de var i Danmark. I 1985 købte de hus i Holme, hvor Svend stadig bor som enkemand. Det viste sig, at Marie og Svend var i familie med nogle af vore venners familie, så verden er endnu engang lille."}, {"type": "para", "text": "I kælderen stod et klaver og en skrivemaskine, som jeg straks viste interesse for. Klaveret nok mest, fordi det var af den slags, der kunne spille af sig selv. Man trykkede blot på en fodpedal, og så kom de dejligste melodier ud. Det var godt nok imponerende. Men man kunne også spille rigtigt på det – hvis man altså kunne spille. Det syntes Margaret og Martinus, at jeg skulle lære, så de aftalte med en dansk dame, Florence Larsen, at hun skulle give mig klaverundervisning og også lære mig maskinskrivning. Florence, som ganske vist var af dansk afstamning, kunne kun sige få ord på dansk. Hun boede til leje hos Frode og Frideborg Caspersen, som var fra henholdsvis Norge og Sverige. De var alle tre venner med Margaret og Martinus. En gang om ugen gik jeg til undervisning hos Florence og fik da også lært noget, som jeg i mellemtiden har glemt. Det blev ikke holdt ved lige, da jeg kom hjem, for mor og far havde ikke råd til klaver."}, {"type": "para", "text": "Martinus, som blev kaldt Chris, lignede min morfar af statur men ikke af sind. Han havde mindreværdskomplekser, sikkert fordi han ikke havde gået så meget i skole og derfor ikke kunne læse. Margaret læste hver dag avisen højt for ham og ordnede al regnskab og papirarbejde. For at kompensere for denne manglende evne, skulle han så hævde sig på andre måder. Han ville gerne prale af det, han havde drevet det til i USA, og han var meget dømmende og kritisk over for andre samfundsklasser, religioner og farvede. Han så ned på negre og mexicanere. Sidstnævnte, hævdede han, gik med kniv. Han gjorde også nar af den katolske kirke, som Margaret tilhørte. Martinus gik aldrig i kirke, og han kunne ikke forstå, at Margaret absolut skulle til messe hver søndag. Jeg var heldig med, at han kunne lide mig, for han lagde ikke skjul på, hvem han favoriserede. Fx kunne han ikke lide Margarets familie. Margarets brors datter Sharon sagde det en dag til mig, og jeg kunne da også godt fornemme det. Den eneste i den familie, han havde respekt for, var Margarets søster Agnes. Til gengæld øste han af al sin kærlighed til Crissy og Cindy og deres familie, som var ret stor. De var katolikker, så det forklarer den store børneflok. Forældrene Lila og Ted var hhv. 25 og 26 år, havde 5 børn og ventede nr. 6, og efter jeg rejste, fik de 3 mere. Martinus blev af børnene kaldt Pappa, og især pigerne var han glad for. Han var overbevist om, at jeg ikke ville kunne falde til i Danmark igen, når jeg kom hjem, for USA var jo nummer ét. Det sagde han til mig en dag. Når han skulle tale alvorligt og sige noget for ham betydningsfuldt, havde han det med at gå helt tæt hen til folk, lægge hånden på deres skulder og se op på dem, for han var en lille mand og skulle se op til de fleste. Selvom han var dansker, regnede han ikke Danmark for noget."}, {"type": "para", "text": "Margaret, derimod, elskede Danmark og sin danske familie. Uden hende kunne Martinus ikke have udrettet noget. Hun var godheden selv, og hun talte altid pænt til ham, selv når han snerrede ad hende. Jeg kan ikke tælle alle de gange, hun fortalte mig, at hun elskede mig, men i det år var jeg jo også som en datter for dem. Margaret var en stor dame og meget besværet af sin vægt, fordi hun havde dårlige hofter. Hun måtte ofte sidde oppe om natten i en stol og sove, og man kunne tit se, hvor ondt hun havde det, når hun gik. Men hun beklagede sig aldrig."}, {"type": "figure", "caption": "", "page": 57, "file": "assets/images/p057_063.jpg", "dim": [648, 650]}, {"type": "para", "text": "Martinus ejede de 2 nabohuse, hvor der var 4 lejligheder i hver. I den ene boede en pensioneret lærer ved navn Helen Beckler. Hun gav mig engelskundervisning i starten, så jeg kunne klare mig, når skolen startede. Men det gik nu rimelig hurtigt med at lære sproget, så da jeg havde været der en måned, kunne jeg fint klare mig. I det andet hus i kælderen boede Sally Hogan, som blev min bedste veninde, selvom hun var over 70 år. Hun var en lille væver dame, der var fuld af spilopper og sjov at være sammen med. Hendes barnebarn Kathy var jævnaldrende med mig, og hun kom tit på besøg. Der gik ikke en dag, uden Sally lige kiggede ind og vi fik en sludder. Vi drillede hende med, at hun var kæreste med Frank, som boede i baghuset, eller Pickles, som boede ovenpå. Det syntes hun var sjovt. På billedet ses Sally sammen med Pickles."}, {"type": "figure", "caption": "Her har vi besøg af Chris og Lilly fra Iowa", "page": 57, "file": "assets/images/p057_064.jpg", "dim": [644, 661]}, {"type": "para", "text": "En måned inde i mit ophold blev jeg taget med på en spændende 10-dages tur gennem 7 stater: Colorado, Kansas Nebraska, Iowa, Minnesota, South Dakota og Wyoming. Med på turen var Sharon, så jeg ikke skulle kede mig. Formålet med turen var at vise mig noget af USA samt besøge familie. Første stop var Council Bluffs i Iowa efter en køretur på 15 timer. Her besøgte vi Krista, som var kusine til morfar og Martinus. Kristas datter, svigersøn og børnebørn boede i nærheden, og børnene var på vores alder. Dem havde vi det sjovt med, enten i deres store hus, som havde bar i kælderen, eller i haven, hvor vi red på en pony. Efter 4 dage kørte vi videre til en gård i Iowa, hvor mors anden onkel, Christian, og hans kone Lilly boede. Det var tydeligt, at de ikke havde klaret Her har vi besøg af Chris og Lilly fra Iowa sig så godt økonomisk som de to andre. De havde heller aldrig haft råd til at komme til Danmark. Men de havde noget, som de to andre brødre aldrig fik, nemlig børn. Deres to døtre hed Agnes og Bernice. I Belgrade, Minnesota besøgte vi min mormors danske veninde Karen og dennes danske mand Møller, som havde en gård, og videre derfra gik turen til Park Rapids i samme stat, hvor den tredje onkel, Julius, havde et feriereservat ned til en sø. Han og konen Blanche, som var kræftsyg, havde en helårsbolig i Council Bluffs men flyttede til dette reservat om sommeren, hvor de lejede små hytter ud til turister. Mens vi var i Council Bluffs, boede vi i deres hus, som var ret imponerende. Det var første gang, jeg så et brunt køleskab og komfur, og de havde tre fjernsyn. I Park Rapids fik Sharon og jeg en hytte for os selv, hvor vi underholdt hinanden om aftenen med at fortælle spøgelseshistorier. Om dagen sejlede vi ud på søen og fiskede, og her fik jeg min debut som lystfisker. Jeg fik endda lært at sætte orm på krogen. Den dag, jeg fangede ti regnbueørreder, var jeg stolt, og aftensmaden var reddet. En dag var vi i Itasca State Park, hvor Mississippi-floden har sit udspring. Sharon og jeg blev fotograferet midt i floden, så jeg kunne sige, at jeg havde gået tværs over denne mægtige flod."}, {"type": "para", "text": "På vejen hjem til Denver kørte vi igennem the Black Hills i South Dakota med de fire præsidenthoveder hugget ind i klipperne, og vi så bisonokser, så det var meget spændende. Det var også på denne tur, at jeg første gang boede på motel. En overnatning for os alle 4 kostede $ 8 (56 kr.) Jeg blev hurtigt glad for at bo i Denver, og skulle jeg nogen sinde bo andre steder end i Danmark, skulle det være her. Jeg var fascineret af Rocky Mountains, hvor vi tit kørte op, hvis vi skulle på fisketur tidligt om morgenen eller på picnic om søndagen. Dette var jo også mit første møde med bjerge. Denver havde oprindeligt været en guldgraverby, og i bjergene findes mange mindre guldgraverbyer og nedlagte miner og museer. Buffalo Bill, den berømte bisonjæger, der deltog i kampen mod indianerne og døde i 1917, er begravet i disse bjerge, og hans gravsted er en turistattraktion, ligesom Red Rocks Theater."}, {"type": "figure", "caption": "", "page": 58, "file": "assets/images/p058_065.jpg", "dim": [648, 675]}, {"type": "para", "text": "Den 4. september begyndte jeg at gå i skole, efter at vi i forvejen havde været oppe og tale med skoleinspektøren, Mr. Wesch. Under samtalen bad han mig læse noget op, hvilket sikkert har lydt gebrækkeligt, idet jeg jo ganske vist havde lært at tale sproget men ikke var så øvet i at læse det. Skolen var en forholdsvis ny og moderne lutheransk privatskole og hed Emmaus Lutheran School. Den havde ca. 350 elever, 10 lærere og 2 præster, og det kostede $ 18 (126 kr.) om måneden at gå der plus bøger og andet materiale. Skolen var bygget sammen med Emmaus Church, som jeg allerede havde stiftet bekendtskab med, idet jeg den 12. august var begyndt i søndagsskole og kirke. Her var en helt ny verden dukket op for mig: jeg skulle gå i søndagsskole og kirke hver søndag. I Danmark havde jeg også en kort stund gået i søndagsskole, men kun for at få mit hæfte klistret til med røde æbler, hvilket kun skete, hvis vi mødte op hver søndag. Søndagsskolen på Emmaus varede en time, hvor vi læste i Bibelen, besvarede spørgsmål, så film og lagde penge i en sparebøsse, der gik rundt. Jeg forsømte kun søndagsskole og kirke to gange på det år, jeg var der. Derhjemme var det virkelig kedeligt at gå i kirke, ikke mindst på grund af Pastor Lentz, men også fordi der var nogle kedelige ritualer. I min familie gik vi sjældent i kirke, selvom mor troede på Gud og bad Fadervor med mig hver aften. Vi talte aldrig om det, men det var mest missionsfolk, der kom der. Desuden lå kirken uden for byen, og vi havde ikke bil. I USA var det anderledes. Der var en hyggelig atmosfære i kirken, og folk gik der ikke af pligt men for at være sammen, også efter kirketid hvor der tit blev arrangeret noget socialt. Kirken var stedet, man mødtes, og alting var ikke stift og formelt. En gudstjeneste varede 1½ time, og mange søndage sang jeg i kor. Til det formål var vi iført lange, hvide kåber. Der skulle nu ikke nogen speciel sangstemme til for at blive optaget i koret, for hele min klasse var med. Da nogle af drengene sang elendigt eller havde overgang i stemmen, blev de bedt om bare at mime til salmerne. Der var to præster tilknyttet kirken, og de underviste samtidig i religion: Pastor Pollack og Pastor Fiegel. De gav mig en flot modtagelse, og jeg følte virkelig, både i kirken og i skolen, at jeg var genstand for alles interesse, fordi jeg kom fra Danmark. Både elever, lærere og forældre gjorde alt for, at jeg skulle føle mig godt tilpas, og det lykkedes til fulde. Jeg kom i 8. klasse, fordi de i USA starter tidligere i skolen. Hver morgen holdt eleverne på skift andagt i klassen, og vi svor troskab til det amerikanske flag, hvorefter vi havde en times religion med præsten, som også spillede klaver til de salmer, vi sang. Der var et stort flag i hver klasse, og under den indledende seance rejste vi os op, lagde den ene hånd på brystet og rettede blikket mod flaget, samtidig med at vi lirede en remse af, som begyndte med ordene: ” I pledge allegiance to the flag of the United States of America”. Vi sad ved enmandsborde, hvor bordpladen kunne løftes op og afslørede et dybt rum, der var beregnet til vores skolebøger. Der var ikke noget, der hed skoletasker – man tog bare den bog eller de bøger under armen hjem, som man skulle læse i til næste dag. Vi var 18 piger og 19 drenge i klassen, indtil en af drengene blev bortvist p.g.a. dårlig opførsel. Jeg skulle pludselig til at lære om Amerikas historie, hvilket i starten var meget svært, ikke mindst de ”multiple choice” prøver vi havde hver uge. Vi havde vores klasselærer, Mr. Harms, til historie, og han hjalp mig meget. I starten havde jeg kun 60% af spørgsmålene rigtige, men jeg fik mig arbejdet op til 90%, inden året var omme. Noget nyt var også fysik, eller ”science”, som det hed. Her lærte vi om elektricitet, energi, astronomi og geologi. I starten havde vi en helt ny, ung lærer, Mr. Miskimen, men han kunne overhovedet ikke styre drengene, så han blev afløst af skoleinspektøren, hvorefter der blev ro i klassen. Også dette fag var svært for mig. Derimod var regning, matematik og aritmetik for mig den rene leg, fordi jeg i Danmark allerede havde haft noget af stoffet. Vi havde Mr. Rathe, som virkelig kunne pruste sig op over for ballademagerne i klassen, men over for mig var han meget venlig og imødekommende, og jeg fik tit kørelejlighed af ham til skolen, hvis han mødte mig på vejen. Jeg blev så god i hans fag, at jeg ofte blev bedt om at forklare noget for de andre. Mr. Rathe er i dag 91 år og aktiv i kirken. Jeg har flere gange mødt ham og hans kone siden – sidste gang i sommeren 2004, da jeg var i Denver og naturligvis var i kirke. Hver dag havde vi en time, som vi kunne bruge til at læse lektier, læse blade, skrive sedler til hinanden eller holde hemmelige afstemninger. Mange poster skulle besættes i klassen: præsident, vicepræsident, sekretær, kasserer, sparemærkesælger og lunch-clerk. Sidstnævntes opgave bestod i at klippe et hul i nogle frokost- og mælkekort, hvis eleverne skulle købe mad i kantinen. To gange om året var der afstemning, og anden gang blev jeg valgt til lunch-clerk, et hverv jeg udførte med megen omhu. Vi lærte i det hele taget alt om mødeteknik og ansvarlighed. Af andre hverv, der blev udført af elever, kan nævnes: bibliotekar, medlem af Røde Kors, skolepatruljer og sygemedhjælper. Lige før frokostpausen bad vi en bøn, hvorefter vi gik nedenunder i skolens festsal, hvor kantinen var. Et måltid varm mad kostede 25 cents (1,75 kr.) og bestod af en varm ret, et stykke kage, dessert, frugt og mælk. Når vi fik spinat, makaroni med ost eller sauerkraut, byttede jeg altid mad med en anden, så jeg fik desserten i stedet for den varme ret. Vi måtte godt levne, men det så ikke godt ud."}, {"type": "para", "text": "Gymnastiktimerne (PE) var meget anderledes, end jeg var vant til. De foregik enten i kælderen, hvis vejret var dårligt, eller i skolegården, hvis vejret var godt. Piger og drenge var sammen, og vi skiftede ikke tøj eller gik i bad. Vi spillede volleyball, basketball, softball og hickball. På et tidspunkt lærte jeg dem at spille rundbold og langbold, hvilket de var vældig begejstrede for. En gang om året var der noget, der hed Field Day, hvor alle skoler i området var samlet for at konkurrere mod hinanden i forskellige discipliner. Det var i starten af skoleåret, inden jeg blev helt perfekt til engelsk og kunne forstå alle detaljer. En dag gik der nogle lister rundt i klassen, hvor folk skrev sig på. Jeg ville ikke være dum og spørge, hvad det var til, så jeg skrev bare mit navn på tre af listerne. Det viste sig, at jeg havde meldt mig til tre discipliner til Field Day, og dette gik først rigtigt op for mig på selve dagen, hvor det var for sent at træne. Behøver jeg at sige, at det gik elendigt. Jeg blev nummer sjok i alle tre discipliner, som var hurtigløb, længdespring og basketball. Men vi havde en sjov dag alligevel, hvor forældrene var med. Til forskel fra Danmark gik vi ikke i skole om lørdagen."}, {"type": "para", "text": "På et tidspunkt blev der afholdt et elev talentshow på scenen i skolens kælder, og alle, der havde et talent, kunne optræde. Nogle af pigerne havde set mig spille med tre bolde op ad en mur, så de opfordrede mig til at optræde med det nummer. Det var åbenbart ikke noget, amerikanske børn kunne. Og sådan blev det. Jeg kom på programmet med mit ”juggling act” og øvede mig helt vildt, for jeg skulle jo helst undgå at tabe boldene. Jeg husker min nervøsitet, inden jeg skulle ”på”, men det lykkedes mig da, med et enkelt kiks, at komme helskindet igennem nummeret, som blev udført til tonerne af ”76 trombones”. Og begejstringen ville ingen ende ta’. Nogle af mine veninder mente, at det skyldtes, at drengene var mere fikserede på min bare mave end på de tre røde bolde, der fløj rundt i luften."}, {"type": "para", "text": "En gang om måneden var der forældremøde på skolen, hvor eleverne også gerne måtte være med. Der blev holdt foredrag, talt om eleverne og nydt forfriskninger. En dag spurgte skoleinspektøren mig, om jeg ville holde et foredrag om Danmark og vise lysbilleder. Det var en stor ære, som jeg takkede ja til, men jo tættere vi kom på aftenen, jo mere nervøs blev jeg. Margaret havde hjulpet mig med at forberede foredraget, men jeg var meget nervøs og havde sommerfugle i maven. Det var jo mange forældre og lærere, jeg skulle stå over for, men det blev en stor succes, og jeg høstede megen ros bagefter. Som tak fik jeg en sweatshirt med skolens navn."}, {"type": "para", "text": "Vi fik karakterbog 4 gange om året. Til dem, der havde rene A’er (11-taller) i slutningen af året, vankede der fribilletter til en baseballkamp. Jeg manglede kun 1 karakter i at kunne få dette, men det skal så dertil siges, at det var nemmere at få et A i USA end at få et 11-tal i Danmark. Desuden tror jeg også, at lærerne havde været ekstra flinke ved mig, fordi jeg kom fra Danmark."}, {"type": "para", "text": "På slutningen lavede klassen et album til mig, som jeg fik som afskedsgave med indgraveret navn i guld. Hver elev havde skrevet om et emne, der vedrørte Colorado samt sat billeder i og skrevet en personlig hilsen. Albummet indeholdt også en serie lysbilleder af Colorados natur. Albummet har jeg stadig som et kært minde."}, {"type": "para", "text": "Jeg havde kun én ubehagelig oplevelse, mens jeg gik i skole, og den havde i og for sig ikke noget med skolen at gøre. Denne var ikke længere væk, end at jeg nemt kunne gå frem og tilbage hver dag, og kvarteret var fredeligt. Indtil en dag hvor jeg var på vej hjem og mødte to piger på min egen alder. De havde åbenbart bestemt, at jeg skulle mobbes, så de begyndte at drille mig. Det var ubehageligt, men jeg lod som ingenting og gik bare videre. Flere eftermiddage stod dette på, så jeg til sidst frygtede at møde dem. Det hele kulminerede, da den ene sprang op på ryggen af mig og krad- sede mig på arme og hænder, så jeg blødte. Da løb jeg hjem og fortalte det til Margaret. Det viste sig, at pigerne var fra den katolske skole, hvor Sharon gik, og den ene gik i hendes klasse. Margaret fik et møde i stand med skoleinspektøren, som hun kendte, fordi skolen tilhørte hendes kirke og lå på vores gade. En dag blev jeg hentet i skolen af Margaret og Martinus, og vi tog hen på den katolske skole, hvor jeg så skulle udpege pigerne. Det var ubehageligt at gå ind i en klasse, kigge sig omkring og så pege på synderen. Det blev til en konfrontation på skoleinspektørens kontor, hvor pigerne græd og på inspektørens opfordring gav mig en undskyldning. På spørgsmålet om, hvorfor den ene havde kradset mig, svarede hun, at det havde veninden sagt, hun skulle gøre. Hertil replicerede inspektøren: ”Hvis nogen bad dig springe i Sloane Lake, ville du så gøre det?”"}, {"type": "para", "text": "Når det kom til højtiderne, fornemmede jeg også, at her var tale om en anderledes kultur. Min 13-års fødselsdag blev fejret efter alle kunstens regler med mange gæster om aftenen i den store gildesal i kælderen. Bedst husker jeg fødselsdagslagkagen med masser af glasur og 13 lys. Det var meget nemt at bage en sådan kage i USA, for man købte bare et pulver og blandede vand i, og VUPTI så stod kagen der høj og flot efter en tur i ovnen, og den smagte himmelsk. Sådan havde min mor nu alligevel aldrig bagt en kage. Denne metode skulle vise sig at komme til Danmark nogle år senere, men mor hoppede nu aldrig på den. Jeg fik mange gaver i dagens løb, men jeg måtte ikke pakke dem op før om aftenen, når alle gæsterne var kommet. Jeg fik et diadem på, så alle kunne se, at det var mig, der var ”the birthday girl”, og så blev der selvfølgelig sunget ”Happy Birthday”. Julen formede sig også anderledes end derhjemme, selvom vi fejrede den d. 24.12. om aftenen til ære for mig, og ikke juledag, som man normalt gør i USA. Det var første gang, jeg så elektriske lys på juletræer og bygninger, og så oven i købet kulørte – min mor ville have fundet det smagløst. Det var simpelthen ulovligt at have stearinlys på juletræerne. Også kunstige juletræer og blomster blev jeg chokeret over. Disse skikke har imidlertid også fundet vej til Danmark nu, især dekorering af huse til jul à la ”Fars fede juleferie”. Julius og Blanche var kommet helt fra Iowa for at holde jul sammen med os, hvilket var hyggeligt. Selvom vi fik risengrød og gåsesteg juleaften, var det en mærkelig aften, for midt i det hele skulle jeg i kirke og synge i kor, og efter vi havde danset om det mindste juletræ, jeg nogensinde havde set i en stue, og åbnet gaver, var jeg med Margaret til midnatsgudstjeneste i den katolske kirke, som lå på samme gade, som vi boede. Mor og far havde sendt en kæmpestor kasse fyldt med gaver til os fra hele familien, men vi havde også sendt en endnu større kasse til dem. Margaret havde ikke sparet på noget. Kirken var stuvende fuld, da vi kom lidt i kl. 23, men vi fik da en siddeplads. Jeg tænkte med medlidenhed på de arme mennesker, der måtte stå op i de 2½ time, seancen varede. Jeg var flere gange ved at falde i søvn, men det skyldtes vel også, at prædikenen var på latin. Uafbrudt skulle vi knæle og slå korsets tegn, så jeg til sidst var helt træt i alle lemmer. Jeg var tit med til katolske gudstjenester, da de fleste af vores venner var katolikker. Jeg var fx med til Crissy’s ”First Communion”, en slags katolsk konfirmation, hvor de går til alters første gang. Hun var klædt som hvid brud i en alder af 7 år, og det var en stor begivenhed for hende. Jeg var også med til barnedåb med hendes lillebror Jamie, hvor alt også foregik på latin. Efter dåben gik alle med dårlig hals op og knælede, og præsten sagde noget til hver især på latin, en slags helbredelsesbøn, velsagtens. Jeg havde desværre ikke ondt i halsen og kunne derfor ikke prøve det af. Da katolikker ikke må spise kød om fredagen, fik vi altid fisk den dag. Den 30. december ringede vi til Danmark. Det var naturligvis aftalt, så mor og far kunne være i Skæve, når opkaldet gik igennem, hvilket det først gjorde ved tredje forsøg. Den første, jeg fik i røret, var mormor, og så var det hele ødelagt. For da hun med gråd i stemmen spurgte: ”Hvordan har du det, Merete?”, var jeg færdig. Jeg tror ikke, jeg fik snakket med andre. I stedet for, som i dag, at holde forbindelsen ved lige pr. telefon, skrev vi breve til hinanden. Jeg skrev ugentligt hjem og fik også mange breve. Jeg korresponderede med mange venner og familiemedlemmer, deriblandt to drenge fra klassen, Hans Jørgen og Per Langhorn. Martinus elskede at drille mig med disse ”boyfriends”, som han kaldte dem. Nytårsaften var der ikke meget grin ved. Der var ingen, der fyrede kinesere af eller tog kaffekander. Da vores gæster gik kl. 22, gik vi i seng. Det fandt jeg meget mærkeligt og kedeligt. Dagen før påskelørdag klippede vi æggebakker i stykker og kom små påskeæg deri. Derpå gemte vi dem forskellige steder i græsplænen, og i hække og buske. Næste dag kom hele familien Shramek, som jo havde 6 børn, og så gjaldt det om, hvem af børnene, der kunne finde flest æg. De allermindste børn troede, at det var påskeharen, der havde gemt æggene. Også denne tradition har vundet indpas hos mange danske børnefamilier. Mine klassekammerater blev konfirmeret om foråret men mest med fokus på den kirkelige handling: ingen gaver, kun en bibel og en salmebog, og ingen fest. Hvor var jeg glad for, at jeg skulle konfirmeres i Danmark."}, {"type": "para", "text": "Margaret og Martinus følte et stort ansvar ved at have mig boende, så derfor var jeg meget sjældent med kammerater hjemme. Mine bedste veninder i klassen var Jacque, Barbara og Susan, som jeg stadig har kontakt med. Jeg overnattede hos Barbara en enkelt gang, nemlig den 4. juni. Klassen skulle på udflugt den 5. juni og skulle starte meget tidligt, og da jeg skulle køre med Barbara, hendes tvillingebror Tom og deres forældre, blev jeg nødt til at overnatte. Det var vældig hyggeligt, for de var meget søde. Udflugten gik til Colorado Springs, hvor vi overværede Airforce Academy kadetternes ”graduation”, altså ceremonien, hvor de får overrakt deres eksamensbeviser. Og til at gøre dette havde de inviteret selveste Præsident John F. Kennedy. Jeg husker, som var det i går, da Kennedy’s åbne vogn kørte ind på pladsen med Præsidenten vinkende og nikkende til tilskuerne. Jeg blev forbavset over at se, at hans hår var rødligt, for jeg havde kun set billeder af ham i sort/hvid. Men han var jo også af irsk afstamning. Efter at han havde kørt rundt langs tilskuerpladserne, holdt han en tale, og 25 æreskadetter fik lov at trykke ham i hånden. Det hele blev vist på TV. Da ceremonien var overstået, smed kadetterne traditionen tro deres hvide kasketter og handsker op i luften, og tilskuerne fløj ned for at få fat i dem. Arthur Brandes fra min klasse kom og gav mig to umage handsker, som jeg stadig har som et minde om denne dag. Det var betænksomt af ham. Er der noget at sige til, at jeg var lamslået den 22. november samme år, da jeg i radioen hørte, at Kennedy var blevet skudt. Takket være John F. Kennedy undgik man i 1962 en stormagtskrig mellem USA og Sovjetunionen. Som 12-årig er politik ikke det, der står øverst på dagsordenen, så jeg var lykkeligt uvidende om denne fare, men mine forældre var noget nervøse over, hvordan tingene ville udviklede sig, fortalte de mig senere. Konflikten mellem de to stormagter handlede om sovjetisk opstilling af mellemdistanceraketter på Cuba. Præsident Kennedy iværksatte en blokade for at forhindre transport af raketter til øen med trusler om opbringning. Efter 6 nervepirrende døgn trak ministerpræsident Nikita Khrustjov fragtbåde med raketter på vej mod Cuba tilbage. Det eneste, jeg kendte til Khrustjov, var, at jeg havde ham og hans kone Nina som påklædningsdukker, og de var begge små og buttede."}, {"type": "para", "text": "En af pigerne i klassen, Vickie, holdt et afskedsgilde for mig i form af et ”slumber party”. Vi var 8 piger, der var med, og vi medbragte selv sengetøj. Efter aftensmaden var vi i svømmehal, hvorefter vi fik hamburgers og hot dogs i haven, selvom det var mørkt. Efter midnat bredte vi sengetøjet ud på stuegulvet, og så begyndte pudekampen, som var et vigtigt element i denne form for fest. Efter dette faldt vi udmattede i søvn. Jeg holdt også selv afskedsfest for alle mine klassekammerater, hvilket var meget vemodigt. De kom alle med gaver, og jeg husker især en indianerdukke, som jeg fik af den tidligere omtalte Arthur Brandes, der var klassens klovn. Han var en lille fyr, som altid havde en frisk bemærkning parat. For flere år siden blev han meldt savnet og er aldrig blevet fundet. Festen forløb godt. Vi var i haven hele eftermiddagen, hvor vi fik forfriskninger, spillede kroket og legede danske lege. Det var hårdt at sige farvel til alle disse dejlige kammerater, hvis navne, udseende og adfærd har brændt sig godt og grundigt fast i min erindring."}, {"type": "para", "text": "Jeg har senere besøgt Denver 6 gange. I 1976 holdt vi en slags ”class reunion” hos Margaret og Martinus, hvor jeg så nogle af klassekammeraterne og lærerne, og i 1997 holdt Jacque en lignende komsammen for mig, hvor en del klassekammerater mødte op."}, {"type": "figure", "caption": "", "page": 63, "file": "assets/images/p063_066.jpg", "dim": [637, 860]}, {"type": "para", "text": "Mens jeg var i USA, blev der bragt en del artikler om mig i både danske og amerikanske aviser, hvilket er tegn på, at det på det tidspunkt var ret usædvanligt for en 12-årig pige at rejse alene til USA. Den 24. juni 1963 tog jeg afsked med Margaret og Martinus. På de lysbilleder, vi har fra lufthavnen, ser de meget triste ud. Jeg havde blandede følelser, for jeg glædede mig naturligvis til at se min familie igen, men på den anden side var jeg også ked af at skulle sige farvel. Men Martinus’ spådomme gik ikke i opfyldelse, for jeg faldt godt til, da jeg kom hjem, og kom ikke til at savne noget af al den luksus, jeg havde været vant til. Jeg holdt forbindelsen med Margaret og Martinus indtil deres død, og derefter har jeg besøgt dem på kirkegården. Margaret havde i sit testamente anført mig som arving til 1% af sin formue, hvilket beløb sig til $ 570,20, som jeg hentede hos Margarets søster Agnes i juli 1989. I 1965 var Margaret og Martinus på besøg i Danmark igen. Da de rejste hjem, tog de Malthas to børnebørn Majbrit og Lone på 13 og 11 år med til USA. De skulle også være der et år, men de kom hjem efter 8 måneder. Jeg ved ikke præcis, hvad der gik galt, men det var nok ingen fordel at være to sammen. Desuden så vi Margaret og Martinus i Danmark i 1975, og året efter besøgte vi dem."}, {"type": "figure", "caption": "", "page": 63, "file": "assets/images/p063_067.jpg", "dim": [860, 621]}, {"type": "para", "text": "Mens jeg havde været bortrejst, var Helge og Tove blevet gift den 1. september 1962 ved et mægtigt bryllup, som jo blev holdt på Konditoriet. Hvor var jeg ked af, at jeg ikke kunne være med. Desuden var min farfar død i november, hvilket jeg har nævnt andetsteds. Mit kære Konditori var blevet solgt. Grunden var, at mormor med sit ”dårlige hjerte” ikke kunne holde til arbejdet der mere, så morfar havde bygget hus til dem i Skæve."}, {"type": "para", "text": "Det var et stort øjeblik, da jeg landede i København, og mor, far, Per, Moster og Tove stod der med flag. Jeg tog af sted som et barn men kom hjem som en voksen pige. Det år modnede mig meget, og jeg lærte at stå på egne ben. Jeg fik lært at tale og skrive sproget som en indfødt, og jeg var ikke mere så genert, som jeg havde været. Når man som 12-årig kun taler engelsk et helt år, kan det være vanskeligt pludselig at skulle tale dansk. Sådan var det for mig, da jeg stod over for tolderne i Kastrup. De rystede opgivende på hovedet og syntes sikkert, at jeg var arrogant, men det var virkelig et problem for mig. Det gik dog hurtigt over, men i starten tænkte og drømte jeg på engelsk. Det var første gang, Per skulle flyve, og derfor var det hans debut med SAS. Han var næsten 3 år og brugte ikke mere ble, men flyveturen var alligevel så spændende, at han kom til at tisse i bukserne. Mor havde for en gangs skyld ikke været forudseende og havde ingen tørre bukser med, så han blev pakket ind i fars jakke, indtil de landede og kunne få fat i bagagen. Da Per jo var knap 2 år, da jeg tog af sted, kunne han ikke huske mig, så hver gang der kom en dame gående i lufthavnen, spurgte han: ”Er det Merete?”, også selvom hun var 80 år. Jeg var lykkelig for at se ham, og vi fik hurtigt genoprettet kontakten. Jeg havde en amerikanerbil og en SAS flyvemaskine med hjem til ham. At han så senere kom til at arbejde for SAS var pudsigt. Flyvemaskinen har stået på alle de kontorer, han har haft rundt om i verden. Jeg husker stadig det sug i maven, jeg fik, da jeg så min familie stå på den anden side af glasburet, inden jeg kunne komme ud til dem og få den helt store omfavnelse."}, {"type": "figure", "caption": "", "page": 64, "file": "assets/images/p064_068.jpg", "dim": [600, 601]}, {"type": "figure", "caption": "Et lille udsnit af stuen: På væggen onkel Ibs understellet af Pers vugge omdannet til", "page": 64, "file": "assets/images/p064_069.jpg", "dim": [600, 600]}, {"type": "para", "text": "Det næste spændende øjeblik for mig var mødet i Ålborg Lufthavn. Her stod der en velkomstkomité bestående af mormor, morfar, farmor, onkel Erik, Maltha og min veninde Lisbet. De havde blomster og flag med. I Skæve fik vi smørrebrød i mormor og morfars nye hus, hvor jeg fik besøg af Hanne Mette, min bedste veninde i Skæve. Vi var også på kirkegården og lægge blomster på farfars grav."}, {"type": "para", "text": "Det var ligeledes et stort øjeblik, da jeg gjorde mit indtog i Thorshøj og så, hvordan flagene vajede fra mange flagstænger. Kristine havde også hejst flaget, og mange havde taget opstilling for at byde mig velkommen hjem. Jeg fik mange gaver og 10 buketter blomster. Hvor var det rørende altsammen. Mor og far havde købt en ny grøn cykel til mig, og da jeg åbnede døren til mit værelse, stod der et splinternyt chatol i teaktræ, noget jeg længe havde ønsket mig. Mine forældre må have sparet længe for at kunne give mig disse gaver."}]}, {"title": "Min konfirmation", "blocks": [{"type": "para", "text": "Vi gik til præst i Præstegården hos Pastor Lentz, som vi var hunderædde for. Især drengene var han ude efter, når han bad dem rejse sig og lire det salmevers af, som de burde have lært udenad derhjemme. Kunne de ikke lige komme i gang, var der ingen nåde. ”Sæt dig ned, du kan jo ingen ting”, eller ”Du er jo så dum”, var dommen. Konfirmationsfesten skulle holdes i gildesalen i Frosts kælder med efterfølgende kaffe i vores lejlighed. Jeg sov næsten ikke natten op til konfirmationen, for mor havde sagt, at jeg skulle holde tale, og hun havde også bestemt, hvad jeg skulle sige. Det var nøje indstuderet. Det lå jeg så og gennemgik inde i mit hoved natten forinden, hvor mor sov på den ene sofa i stuen og jeg på den anden, en halvrund rød sofa, som kunne gøre én helt radbrækket. I talen skulle jeg bruge ordsproget: ”Hvor der er hjerterum, er der husrum”, og så sige, at dette ikke gjorde sig gældende i vores tilfælde, og så skulle jeg bl.a. takke familien Frost, fordi de ville lægge kælder til. Selve konfirmationsdagen den 15. marts 1964 forløb perfekt. Efter kirken lukkede jeg telegrammer og gaver op, hvilket var meget spændende. Nogle af telegrammerne indeholdt duftende papirroser, der automatisk foldede sig ud, når man åbnede dem. De blev åbnet mange gange i dagene derefter. Jeg havde Ulla og Britta med hele dagen. Jeg fik mange fine gaver og 430 kr. Mange telegrammer havde 5 kr. indlagt. Mor havde broderet en navneklud i ramme, som jeg stadig har hængende, og så fik jeg jo festen. Til frokosten, som vi spiste i soveværelset, der endnu engang var omdannet til spisestue, var vi kun de allernærmeste og min gudmor, Dorthe Hegaard fra Hjørring, en slægtning på fars side. Hun var ansat hos sin søster Kristine, som havde en købmandsforretning i Brogade, indtil denne lukkede i 1968. Mens jeg gik på gymnasiet, besøgte jeg somme tider Dorthe i forretningen."}, {"type": "para", "text": "Til aften kom hele min fars familie inkl. nogle fætre og kusiner, mors familie, uddelerens, Kristine, Maltha og Emma, morfars fine søster Mie, Ellen, familien Frost, Mie og Ingeman, som var fars faster og onkel fra Hørby og fru skomager Knudsen, ca 40 gæster. Vi fik 4 retter mad (suppe, tarteletter, steg og is) med diverse vine, bl.a. sauterne til suppen. En kogekone, som hed Edith Berthelsen, fra Skæve lavede maden sammen med Jensy Dreyer, og Inge-Lise Frost samt Anne og Henning fra Riis Toft serverede. Det eneste skår i glæden var, at min onkel Erik ikke var med. Han var indlagt på Hjørring Sygehus med åreknuder, den samme skavank, som hans far led af. Morfar holdt tale, hvilket han var god til, men han blev altid så rørt. Efter middagen gik vi tilbage til lejligheden og fik kaffe, eller rettere sagt mokka (kaffe uden Rich’s), som gæsterne drak af mors fine tynde mokkakopper, og til lejligheden var der blevet købt mini krystalsukker – det skulle jo passe til de små kopper. Når det skulle være rigtig fint, som ved denne lejlighed, lavede mor kaffe på kolbe. Kaffekolben blev så stillet på sofabordet, så gæsterne kunne følge med i den velduftende proces."}, {"type": "figure", "caption": "", "page": 65, "file": "assets/images/p065_070.jpg", "dim": [524, 721]}, {"type": "para", "text": "Nogen tid senere blev jeg fotograferet hos Stella Nova i Hjørring, hvor både Per og jeg havde abonnement. Vi blev fotograferet en gang om året, og der blev valgt et årets billede, som mor skrev bagpå. Alle billeder blev samlet af Stella Nova i et album, som vi fik udleveret til vores 18 års fødselsdage. Denne tradition førte jeg senere videre med Lars, blot foregik det ikke hos en fotograf, men billedet blev udvalgt blandt alle årets billeder."}, {"type": "para", "text": "Dagen efter konfirmationen holdt vi Blå Mandag. Det foregik på den måde, at vi tog rutebilen til Hjørring, hvor vi så var på Konditori Willy og få kakao og kage. Resten af dagen gik vi bare rundt i byen, og sidst på eftermiddagen tog jeg rutebilen hjem igen. De andre blev der, men jeg skulle hjem, fordi vi havde inviteret naboerne til efterkonfirmation om aftenen."}, {"type": "para", "text": "Nogle af mine kammerater holdt efterkonfirmation for konfirmanderne. Jeg husker, vi var inviteret op til Erik Maler. Han hed Erik Nielsen, men hans far var maler. Han blev også kaldt Tændstik Erik, fordi han var så tynd. Det var første gang, jeg var med til at lege mørkeleg. Alle drengene satte sig ind i en stue og slukkede lyset, hvorefter alle pigerne fik et nummer. Så skulle drengene kalde et nummer, og den pige, hvis nummer blev kaldt, skulle sætte sig hos den pågældende dreng. Der var ikke ret mange drenge, jeg havde lyst til at sidde hos, men drengene fandt også hurtigt ud af, hvem der havde de forskellige numre. Det var ikke sidste gang, jeg var med til denne leg, som var mere spændende, når Østervrå-drengene var med."}, {"type": "figure", "caption": "Et par år tidligere havde jeg været med til Brittas og Ullas konfirmationer, Brittas til frokost og", "page": 66, "file": "assets/images/p066_071.jpg", "dim": [557, 551]}]}, {"title": "Husbyggeri", "blocks": [{"type": "para", "text": "Selvom morfar var maler af profession, kunne han også lave alt mulig andet, såsom at mure. Og det gjorde han så, næsten 4 år i træk. Først byggede han hus til Moster og Ib i 1961 på Skagavej 19 i Skagen. Dernæst blev mit elskede Konditori solgt i 1962, og da jeg kom hjem fra USA i sommeren 1963, var mormor og morfar flyttet i selvbyggerhus, Villa Højbo i Skæve. Herefter havde han jo god tid og kunne bygge huse til resten af børnene, først til Helge i Hundige i 1964 og året efter til mor og far på Tryvej 10 i Thorshøj. Morfar nåede også at hjælpe Ib med en tilbygning, da huset blev for trangt. Erik nåede han ikke at bygge for, så han byggede selv sit hus tæt på Helge i 1976, men i skrivende stund mangler han stadig at færdiggøre overetagen."}, {"type": "para", "text": "For mig og min familie var det spændende at skulle flytte i nyt hus efter at have boet i lejlighed i 12 år. Morfar boede hos os i lejligheden i lange perioder, mens byggeriet stod på. Jeg gik tit op til ham på byggepladsen med kaffe eller mad. Ikke nok med at han murede huset, han tapetserede også hele hytten, for tapet skulle der på dengang. Elbo lavede tømrerarbejdet, og Ejlersen lavede el. Morfar har skrevet følgende i mor og fars gæstebog den 18. april 1965: ”Skærtorsdag kom de første Materialer på Byggepladsen, og samtidig indfandt Bygherren, Onkel Erik og undertegnede sig. Støbning af Sokkel gik i gang og fortsattes Langfredag. Paaskelørdag druknede i et heftigt Regnvejr. Paaskedag mødte Maltha og gav en Håndsrækning med. Der fortsættes muligvis i Morgen.” Mormor har tilføjet: ”Jeg tog mig af opvasken”. Senere skriver morfar igen: ”Mandag den 31. Maj gik vi i gang med at mure, og den 10. Juni var vi klar til Rejsning. Alle Skillevægge var med oppe; dertil maa siges, at vi var begunstiget af det herligste Vejr. Det maa bemærkes, at Per var en god Hjælper, og Merete og hendes Mor på skift var stadig Vært med en lille Forfriskning.” Senere igen : ”Søndag den 20. Juni gik vi i gang med Rejsning af Huset, bistaaet af Peter Mellergaard og dennes Svigersøn Erik Karstenskov samt Tage Molbjerg, Helge fra København og selveste Bygherren. Murer Frost var en lille Smut på Inspektion. Maltha, der skulle være med til Rejsningen, udeblev samtidig med Pølserne, men kom i sidste Time sammen med to Brødre og Margaret fra Amerika”."}, {"type": "para", "text": "Under opførelsen af gasbeton murene var de så ivrige, at de glemte at lave hul til badeværelsesvinduet. Dette undlod morfar at meddele i gæstebogen."}, {"type": "para", "text": "Rejsegildet foregik på den måde, at der blev lavet en krans, som blev hejst op i spærene sammen med en tom ølflaske. Det gjaldt så om, hvem der kunne smadre flasken med en sten, og den heldige (eller dygtige) fik så ½ flaske snaps. Der blev naturligvis serveret øl og pølser, som Maltha leverede."}, {"type": "para", "text": "Under mor og fars byggeri, den 16. oktober 1965, skete intet mindre end en sensation: efter 16 års ægteskab, utallige aborter og flere måneder på langs fødte min moster en velskabt dreng, og hele familien jublede. Da mor kom op til morfar i huset og meddelte ham, at han var blevet morfar for tredje gang, var han ikke til at skyde igennem, så der blev skålet både i kaffe, øl og snaps."}, {"type": "figure", "caption": "", "page": 67, "file": "assets/images/p067_072.jpg", "dim": [859, 593]}, {"type": "para", "text": "I efteråret 1965 flyttede vi ind, så jeg kunne holde min 16-års fødselsdag med ungdomsgilde i november. De fleste gulve var af kork, et meget blødt materiale, så folk blev faktisk bedt om at tage skoene af, når der skulle danses, og det skulle der til fester. Huset var 120m2 og meget traditionelt for den tid. Det måtte jo heller ikke blive for dyrt. Man kom først ind i et vindfang, inden man kom ind i en lang korridor med døre ind til de forskellige værelser: Pers værelse, soveværelset, hobbyrummet, mit værelse, badeværelset, køkkenet og en stor stue. Der var listelofter i stue og korridor og mørkeblå fliser på badeværelset. Desuden var der garage med vaskehus i enden samt en dejlig terrasse med pejs. Vaskehuset fungerede også som fyrrum, idet det var her, at oliefyret stod. I 60erne kostede 1000 liter olie 150 kr. Der var dog noget over det hus, som gjorde, at det virkede mere moderne og lidt forud for sin tid. Selvom det var traditionelt indrettet, var køkken og badeværelse noget større end normen, og træ på vægge og lofter samt mørkeblå fliser i badeværelset var heller ikke almindeligt. Som sagt havde mor og far en god smag, så det blev arkitekttegnede teaktræsmøbler og Le Klint- og PH-lamper, der kom til at præge hjemmet. Det, der gav os lidt ekstra smør på brødet, var fars mange ekstratimer med korntørring i høstsæsonen. På det tidspunkt havde han forladt Brugsen og arbejdede i Thorshøj Grovvareforening, hvor han blev uddeler i 1967."}, {"type": "para", "text": "Ikke før sommeren 1967 blev der holdt byggefest med 31 gæster, og på det tidspunkt stod tulipanerne i fuldt flor overalt i haven, et flot syn. Det var en kanonfest, hvor bl.a. far, morfar og Maltha holdt tale. Far kunne godt holde en tale, men det var mor, der støbte kuglerne og i store træk bestemte, hvad han skulle sige. Maltha begyndte altid sine taler med at sige: ”Ja, jeg er jo ikke den store taler”. Det var han nu. Alle tre taler blev optaget på spolebåndoptager."}, {"type": "para", "text": "Mor og far var i det hele taget gode til at holde fester. Mor var eminent til at planlægge, arrangere, dække bord og lave mad, og far var god til alle de praktiske ting, som mor satte ham til. Og når så festen løb af stabelen, var de begge perfekte værter, som forstod at hygge om gæsterne. Jeg husker fester, hvor jeg som teenager ikke deltog, men kom hjem og så, hvordan de fx cyklede rundt inde i stuen, spillede høj musik og havde det herligt, alt imens de opførte sig sobert. Efter en sådan fest, hvor folk blev til den lyse morgen, orkede mor ikke at rydde op, inden hun gik i seng. Det bedste, jeg vidste, var så at overraske dem ved at stå tidligt op og rydde alt op, vaske op og gøre rent, så hele huset skinnede, når jeg var klar med formiddagskaffen. Så kan det nok være, jeg var populær, men hvem ville ikke være glad for at vågne op til sådan et hus?"}]}, {"title": "Historiske begivenheder", "blocks": [{"type": "para", "text": "2.10.1951 Det danske fjernsyn begynder faste udsendelser. 400 danske husstande har eget apparat. 5.6.1953 Kong Frederik underskriver Grundloven, der giver Danmark kvindelig arvefølge til tronen. 29.1.1955 Statsminister Hans Hedtoft dør og H.C.Hansen bliver landets statsminister. 25.4.1955 Poliovaccinationen af danske børn begynder. 23.8.1955 Skuespilleren Ib Schønberg dør. 4.10.1957 Sovjetunionen opsender satellitten Sputnik. 20.10.1957 Serien ”Kvit eller dobbelt” starter i dansk radio og fjernsyn. 4.11.1957 Sovjet opsender Sputnik med levende hund om bord. 28.12.1957 Danmark vinder 3. plads ved Melodi Grand Prix i Frankfurt med ”Skibet skal sejle i nat”. 10.1.1958 Det danske par nr. 7 Kay Werner og Palle Lykke vinder det københavnske Seksdagesløb. 16.4.1958 Tronfølgeren, prinsesse Margrethe fylder 18 og får sæde i Statsrådet. 30.1.1959 Grønlands Handels nye skib ”Hans Hedtoft” går ned på vej fra København til Godthåb. 95 mennesker omkommer. 17.6.1959 Prinsesse Margrethe bliver student fra topersoners gymnasiet på Amalienborg. 30.7.1959 Helle Virkner og udenrigsminister Jens Otto Krag gifter sig i Sydfrankrig. 19.2.1960 Statsminister H.C.Hansen dør efter svær sygdom og afløses af Viggo Kampmann. 17.7.1960 Zonefly styrter ned over Øresund med 8 landsholdsspillere. Alle omkommer. 12.4.1961 Juri Gagarin, Sovjet, bringer sin rumkabine rundt om jorden og bliver det første menneske i rummet. 18.9.1961 Den italienske fodboldklub ”Bologna” køber Harald Nielsen, Frederikshavn, som professionel spiller for 200.000 kr. 28.8.1962 J.O.Krag bliver statsminister.", "page": 68}, {"type": "para", "text": "22.11.1963 Præsident John F. Kennedy myrdes i Dallas. 6.3.1964 Kong Paul af Grækenland dør. Konstantin følger sin far på tronen. 16.6.1964 Sovjetunionens ministerpræsident Nikita Khrusjtjóv på officielt besøg i Danmark med sin kone Nina. 18.9.1964 Prinsesse Anne Marie og kong Konstantin vies i Athen. 23.6.1965 Skuespilleren Peter Malberg dør. 18.9.1965 Politimordet på Amager. 38-årige Palle Sørensen dræber 4 politibetjente. 14.12.1965 Tina på 2 mdr. bortføres fra sin barnevogn uden for Daells Varehus i København. Hele landet følger dramaet. Den 11.1.1966 blev Tina fundet i god behold hos en ung kvinde, der havde aborteret og af angst for at miste sin samlever havde taget Tina og udgivet hende for sin nyfødte.", "page": 69}]}]}, {"title": "Ungdommen", "id": "ungdommen", "chapters": [{"title": "Fester og kærester", "blocks": [{"type": "para", "text": "Min første kæreste hed Kaj, og vi var kun 4 år. Han boede i Skæve, og vi legede ofte sammen, når jeg var på Konditoriet. Tit blev han drillet med, at han legede med piger, men han var ligeglad. Vi er her fotograferet i Konditoriets have, hvor vi står og holder om hinanden, alt imens vi kigger ned og spejler os i bassinet. Men pludselig forsvandt Kaj ud af mit liv, og jeg fik andre interesser."}, {"type": "figure", "caption": "", "page": 70, "file": "assets/images/p070_073.jpg", "dim": [860, 670]}, {"type": "para", "text": "Når man dengang blev konfirmeret, hed det sig, at man nu trådte ind i de voksnes rækker og bl.a. måtte drikke vin. Det gjorde vi nu ikke, men drengene begyndte at drikke øl. Første gang, jeg fik lov at tage til bal, var jeg lige fyldt 15 år. Det var 2. juledag 1964 på Kildekroen i Sæby, og grunden til jeg fik lov var, at jeg netop var begyndt at komme sammen med min første rigtige kæreste, Ole, som var 2 år ældre end mig. Vi kendte hinanden fra skolen og var begyndt at komme sammen til en privatfest i Østervrå kort tid forinden. Nu begyndte en rigtig sjov tid med masser af privatfester og baller, enten i Sæby eller på Flauenskjold Kro. Når vi tog til bal, hvilket skete ca. to gange om måneden, lejede vi et ”rugbrød” med chauffør til at køre os derud og hjem igen. Det kostede 1 kr. pr. person. Jeg fik ikke faste lommepenge, hvilket jeg var træt af. I stedet skulle jeg bede om penge, hver gang jeg skulle i byen. Jeg fik altid 50 kr., når jeg skulle til bal, og efter at have betalt taxa, indgangsbillet og 1 sodavand, som kunne vare hele aftenen, var der nok ca. 35 kr. tilbage, som jeg så afleverede, når jeg kom hjem. Når der blev spillet op til dans, strøg drengene hen og bød pigerne op, og det var ikke sjovt at sidde tilbage og være bænkevarmer. Det skete naturligvis ikke, hvis man kom fast sammen med en dreng, men i de ”ledige” perioder skulle man ikke regne med at være på dansegulvet hele tiden. Hvis vi ikke var til bal om lørdagen, samledes vi som regel på Østervrå Apotek. Apoteker Langhorn og hans kone havde tre sønner og en datter, Otto, Per, Erik og Marianne. Per gik i min klasse. Forældrene var ofte ude, og så boltrede vi os i det store hus. Drengene fik somme tider lidt for meget at drikke, men pigerne drak oftest kun sodavand. Vi ryddede altid op efter os, så vi kunne komme igen en anden gang. De havde en stor samling grammofonplader med bl.a. Beatles, Rolling Stones, Herman’s Hermits, Manfred Man, Mammas and Pappas, Cliff Richard og Mills Brothers. Hvis der indgik elektrisk guitar i musikken, blev den kaldt for pigtrådsmusik. Vi dansede i mørke i spisestuen til plader eller til Radio Luxembourg . Senere kom jeg der også hverdagsaftner sammen med Tove Skovlund, som var kæreste med Otto. Det var, da jeg selv var kæreste med den ældste af sønnerne, Erik. Hr. og fru Langhorn var flinke mennesker, der tilhørte det bedre borgerskab, og de elskede liv i huset. De virkede dog noget gamle i forhold til mine forældre, især hr. Langhorn, som var noget ældre end sin kone."}, {"type": "para", "text": "Jeg fik lov at holde fest, da jeg blev 16 år og vi netop var flyttet ind i det nye hus. Jeg glædede mig enormt meget til at vise mine venner huset, og mor havde lavet en fin middag. Jeg havde arvet en gammel grammofon, så vi kunne spille plader og danse i korridoren, hvis vi tog skoene af, for det var i stilethælenes tid, og vi havde som sagt bløde korkgulve over hele huset. Jeg var på det tidspunkt kommet sammen med Ole i næsten et år, uden at vi rigtig havde været med hinanden hjemme. Det var vi nok alligevel for unge til. Denne aften slog han op med mig og begyndte at komme sammen med min bedste veninde Lisbet. Jeg beherskede mig under festen, men næste dag lå jeg i sengen hele dagen og græd og græd, mens jeg lyttede til den gave jeg havde fået af mine venner, Beatles LP’en HELP. Ja, jeg havde virkelig brug for hjælp. Mor, far og Per tog i byen først på dagen, og da de kom hjem om aftenen, satte mor sig på min seng for at trøste mig. Hun vidste ikke, hvad hun skulle stille op med sådan en tøs, der led af ulykkelig kærlighed. Men jeg kom over det, ligesom alle andre i samme situation. Senere begyndte vi at komme sammen igen, men kun en kort periode. Og Lisbet forblev min bedste veninde, som jeg stadig har kontakt til. Snakken dengang i skolen gik meget på: ”Hvem kommer sammen med hvem?” og ”Hvem har slået op med hvem?”. Man skulle jo helst komme sammen med nogen, men ikke med hvem som helst."}, {"type": "para", "text": "En aften, da mor, far og Per skulle i byen, havde jeg fået lov at invitere gæster. Vi var 6, hvoraf de 4 dannede par, men Jan Thykær og jeg kom ikke sammen med nogen. Selvom vi ikke fik en dråbe spiritus, havde vi det hyleskægt – i starten. En af drengene tog nogle æg i køleskabet og gik ud på plænen for at spille med dem, og så behøver jeg vel ikke sige mere. Der blev også slæbt en del jord ind på gulvene, men vi havde heldigvis ikke gulvtæpper på. En af drengene ville rykke en skuffe ud i køkkenet og greb fat i en blind skuffe, som han så rykkede løs. Det udartede sig lidt vildt, og jeg var ikke så glad ved situationen. Pludselig gik døren op, og mor og far stod i stuen. Der lå et par på sofaen og et andet par på gulvet, og jeg sad i en stol og var meget rød i hovedet. Der var meget rodet og snavset i stuen og køkkenet. Efter at gæsterne var gået, skældte mor mig ud, og det var vanskeligt for mig at overbevise hende om, at mine gæster ikke havde drukket. Bedre blev det heller ikke næste dag, da hun fandt et tomt kondomhylster under min seng. Jeg bedyrede, at jeg ikke kendte noget til det, hvilket jeg virkelig ikke gjorde. Jeg var nok noget umoden på det område, for mor havde aldrig fortalt mig om blomsterne og bierne, og i skolen havde vi haft en biologilærerinde, der rødmede, bare hun skulle vise os en skematisk tegning af et underliv. Hun var selv gammeljomfru og nok ikke den rette til at varetage seksualundervisningen på grund af manglende erfaring inden for området. Mor var naturligvis dødsens angst for, at det skulle gå mig, som det var gået hende, og det var jeg også selv bevidst om, så jeg skulle ikke nyde noget. I vennekredse gik der også rygter om, hvem af pigerne, der var lette på tråden, og den gruppe skulle jeg i hvert fald ikke tilhøre. Det kunne jo nok få nogle af drengene til at synes, at man var kedelig, mens andre følte dyb respekt. Det var endnu den almindelige indstilling, at når en kvinde først havde givet efter eller ”givet sig hen”, som det hed i den gamle stil, faldt hendes værdi drastisk. Jomfrueligheden var en piges kostbareste smykke, som jeg heldigvis bevarede, til jeg mødte mit livs kærlighed i 1969, men det er en anden historie."}]}, {"title": "Kandestederne", "blocks": [{"type": "para", "text": "Min mor var bekendt med hotellivet, for hun havde arbejdet på forskellige hoteller i Skagen og omegn og også svinget kaffekanderne på Skæve Konditori. Fra forskellige album kan jeg se, at hun har arbejdet på Ruths Hotel i 1951 og på Hjorths Hotel i Kandestederne i 1953. Endvidere arbejdede hun på Brøndums Hotel i perioder fra vinteren 1954 til 1959. Så kom Per til verden, og hun kunne af naturlige årsager ikke være væk hjemmefra."}, {"type": "para", "text": "I 1964 blev hun kontaktet af Viggo Hjorth og spurgt, om hun ikke kunne tænke sig at komme op og lave mad til deres gæster om sommeren. Efter nogle overvejelser - for hun havde jo ingen uddannelse inden for det fag - takkede hun ja, for hun kunne godt bruge pengene. Det blev så stor en succes, at det blev starten på et længere samarbejde mellem Hjorths Hotel og min mor, og det kom også til at involvere mig og flere af mine veninder."}, {"type": "figure", "caption": "Brøndums Hotel 1955: Karen Dantoft, mor og moster", "page": 72, "file": "assets/images/p072_074.jpg", "dim": [449, 650]}, {"type": "para", "text": "For at kunne forstå vores tanker omkring Kandestederne, skal man vide noget om stedet, som ligger 12 km syd for Skagen mellem Råbjerg Mile og Vesterhavet. Der er en speciel stemning over dette afsidesliggende sted, hvor lyset er så specielt og naturen så barsk. Jeg kan godt forstå, at gæsterne kom igen år efter år, for havde man været der én gang, var man tryllebundet. Der lå 3 hoteller i området: Kandehus, Kokholms Hotel og Hjorths Hotel, som lå i midten. Først lidt historie: Hjorths Hotel var oprindeligt en landejendom med tilliggende jorder og klitarealer på i alt 300 tdr. land. Peter Hjorth (1880-1966) blev i 1907 gift med Engel Kirstine Høgenhaug og overtog samtidig gården. De fik sønnerne Viggo og Svend samt Holger og Knud, som var tvillinger. På det tidspunkt var hoteldriften ved at komme godt i gang. Peter var foruden at være skibstømrer også snedker og træskærer, og han lavede selv de fleste af møblerne til hotellet, hvoraf mange stadig anvendes rundt omkring i hotellets værelser i dag. Eftersom hoteldriften gik bedre og bedre, blev landejendommen efterhånden helt forvandlet til hotel. I 1922 ramtes familien af en tragedie, kun 2 år efter tvillingernes fødsel. Engel Kirstine fik den spanske syge, og inden hun var helt rask, gik hun en dag ud uden overtøj for at tage vasketøj ind, hvorved hun pådrog sig en lungebetændelse, der dengang var en alvorlig sygdom. Kort tid efter døde hun fra mand og 4 små børn. Efter at have klaret sig med hjælp fra familie og venner, annoncerede Peter Hjorth på et tidspunkt efter sommerhjælp. Det blev en frøken Astrid Mikkelsen (f. 1894), der reflekterede på annoncen, og hun fik nok at gøre med husførelsen og børnene foruden hele hoteldriften. I 1932 giftede hun sig med Peter Hjorth."}, {"type": "para", "text": "Vi er nu fremme ved 1965, hvor mor så om sommeren skulle arbejde på Hjorths Hotel igen. De skulle også bruge andet personale, så jeg fik lov at komme med som køkkenhjælp, og IngeLise, Britta og deres kusine Gunhild blev også ansat. Jeg blev dog, måske i kraft af min mors position, hurtigt forfremmet til stuepige, og da Inge-Lise stoppede, fik jeg hendes tjans som første-servitrice. Vi var 7 ansatte foruden fru Hjorth og Viggo. Mor var kogekone og havde en assistent, som hed Tut og kom fra Tuen. Hun var 16 år og noget naiv, men meget sød og dygtig, og hun og mor havde det bedste samarbejde. Der var to helt unge piger i opvasken, men det skiftede tit, for der var ingen, der gad være der ret længe. Det var et træls og hårdt arbejde for en lav løn. Endelig var der tre servitricer, hvoraf de to gjorde rent på værelserne om formiddagen og serverede om aftenen. Vi boede naturligvis alle på hotellet, og ingen tog hjem i de 6-7 uger, opholdet varede. Derfor havde vi heller ingen muligheder for at bruge penge, mens vi var der. Mor havde eneværelse, mens jeg boede sammen med de andre servitricer helt oppe under taget, hvor vi engang oplevede at have mus. Vi opdagede det, fordi de havde spist af vores chokolade. Da var jeg ikke meget for at lægge mig til at sove om aftenen."}, {"type": "figure", "caption": "Hjorths Hotel 1965: Inge-Lise, Britta og Merete", "page": 72, "file": "assets/images/p072_075.jpg", "dim": [625, 625]}, {"type": "para", "text": "Min arbejdsdag så nogenlunde således ud: Jeg stod op og var klar til at arbejde kl. 7 hver morgen alle ugens dage, iført blå nylonkittel og forklæde. Jeg stod for at servere morgenmad for hotellets gæster, ca. 50 personer i højsæsonen. Jeg skulle kende deres vaner, for det var ofte stamgæster, der boede på de samme værelser hvert år og sad ved de samme borde. Jeg vidste også, hvem der skulle have kaffe på sengen eller bare en bakke på værelset, hvornår de ville have deres morgenmad og hvordan æggene skulle koges. Efter morgenmaden ryddede jeg bordene og dækkede dem til frokosten kl. 13, som bestod af det store kolde bord. Der var min mor en mester, og hun høstede megen ros for sin kogekunst og evne til at planlægge og arrangere. Udover dette gik jeg til hånde, hvis der var andre opgaver, de andre ikke havde tid til. Kl. 13 ringede jeg med klokken, og folk strømmede ind i spisesalen og kastede sig over herlighederne. Efter frokosten fik vi lov at spise resterne; der skulle ikke laves personalemad til os, sagde fru Hjorth, og det var vi meget taknemmelige for. Nu var stuepigerne så som regel færdige med værelserne, og vi hjalp hinanden med at dække borde til middagen og sætte servietter op om søndagen. Hver søndag fik gæsterne rene duge og servietter. Sidstnævnte foldede de sammen og lagde i en servietmappe med deres navn, så de kunne bruge dem resten af ugen. Det skete også, at der kom gæster udefra og skulle have kaffe i restauranten eller på terrassen. Måske kom der en busfuld turister, der havde været på Milen og lige skulle have en forfriskning. Hvis det var inden frokost, var det mit job, men efter frokost deltes vi om det. Når vi så havde dækket middagsborde, holdt vi pause på skift, så der altid var én servitrice på vagt. Det kunne i bedste fald blive til en 2-timers pause om eftermiddagen, som blev brugt til at sove i. Vi mødte så igen i sort nederdel, hvid bluse og hvidt serveringsforklæde til middagen kl. 19. Denne bestod af tre retter mad, næsten altid med suppe først, og alt skulle serveres med stil. Vi havde hver vores borde, og det gik som smurt. De fleste gæster, vi nogensinde har haft, var 70 til andesteg en søndag i højsæsonen. Da måtte vi også indrette en havepavillion til værelse, og nogle af os flyttede sammen, så vi kunne huse alle gæsterne. Andesteg var fast på menuen om søndagen, og den dag glædede vi os til, for så måtte vi få en æblemost til maden. Efter middagen hjalp vi alle hinanden med at rydde op, og ved 21-tiden kunne vi så sætte os omkring det blå bord i køkkenet, slappe af og holde sjov. Vi tre servitricer skiftedes til at have aftenvagt, men selvom man ikke havde vagt, sad man der alligevel. Vi var meget sociale, og vi havde det vanvittig sjovt. Nogle af de unge gæster kom ud og sad sammen med os, bl.a. tykke Peter Friis Poulsen fra Helsingør, som var der 4 uger hver sommer sammen med sine lettere alkoholiserede men meget søde forældre, samt sin lillesøster. Den anden faste gæst var Sune Salling-Mortensen, hvis far var arkitekt i Århus. De to fyre færdedes der, som om de var hjemme. Kl. 23 lukkede køkkenet, og vi gik i seng, så vi kunne være friske til endnu en hård dag."}, {"type": "para", "text": "Mor var alle tiders at arbejde sammen med, og der var næsten aldrig et skævt ord mellem os. Dog blev hun lidt sur på mig engang, og med rette. Det skete, at der kom tyskere og englændere eller andre udlændinge, så der skulle tales udenlandsk. Tysk var jeg ikke ferm til, men jeg kunne klare mig og fortælle dem, hvad de skulle have at spise etc. Det engelske var naturligvis ingen problem, så det var altid mig, der blev hentet, hvis dette sprog skulle tales. En dag kom der nogle udlændinge og skulle leje et værelse, og jeg blev naturligvis hidkaldt, selvom jeg havde travlt med noget andet. Jeg brokkede mig til mor, men jeg fik ingen medhold. I stedet sagde hun til mig, at jeg skulle skamme mig. Jeg skulle være taknemmelig over, at jeg havde været så privilegeret at få lov til at lære sproget. Efter den dag brokkede jeg mig ikke mere. Mor var også meget festlig, og hun satte kulør på aftenvagterne omkring køkkenbordet. Ingen kunne som hun efterligne gæsterne og fortælle om deres særheder, og vi andre fulgte trop."}, {"type": "para", "text": "De første to sæsoner levede Peter Hjorth, men han var senil og lå permanent i sengen i soveværelset, hvor jeg kun kom, når jeg skulle hente nogle kagedåser, der befandt sig under sengen. Man skulle tage en dyb indånding, inden man åbnede døren, for luften var fæl. Der blev vist aldrig luftet ud, og der var lummert og beklumret. Vi så sjældent Peter Hjorth, kun når han uden fru Hjorths vidende forvildede sig ud i køkkenet iført natskjorte og bar røv. Det var et ynkeligt syn, når man tænker sig, hvor værdig, højt agtet og afholdt en mand han engang havde været. Fru Hjorth kom da også hurtigt ud og fik ham gelejdet i seng igen. I sommeren 1966 døde Peter Hjorth, mens vi var der. Hans kiste blev sat ud midt på græsplænen, hvorfra han blev bisat og senere begravet på Hulsig Kirkegård."}, {"type": "para", "text": "Fru Hjorth var en meget speciel person, både af udseende og væremåde. Hun var meget lille og tæt bygget, og ifølge mor lignede hun en sylfide for neden og en sværvægtsbokser for oven. Hendes hud var kridhvid og hendes lige så hvide hår var sat op på hovedet i en slags knold. Desuden var hendes daglige uniform en hvid kittel. Der er ingen tvivl om, at det var fru Hjorths fortjeneste, at hotellet havde haft succes, men på hendes gamle dage havde hun ikke mere overblikket, så det var mere eller mindre mor, der styrede slagets gang. Både Viggo og hans stedmor havde stor respekt for mor, så det var en dejlig tid for dem, når vi alle var der om sommeren og der var godt belagt med gæster. Også pinsen var en travl tid, hvor mor trådte til, somme tider med kort varsel. De gæster, der var der uden for sæsonen, glædede sig til at mor kom, så de kunne få noget lækkert at spise. Jeg har set den mad, fru Hjorth biksede sammen til hende og Viggo, for de spiste ikke gæsternes mad som vi andre, og jeg priste mig lykkelig over, at det var mors mad, vi fik lov at spise. Fru Hjorth var bestemt, resolut og meget humørsyg. Om morgenen tøffede hun rundt med udslagen hår og bare arme, og hvis hun fløjtede, skulle man gå i en stor bue omkring hende, for det var tegn på, at humøret var dårligt. Det blev så bedre op ad dagen, især hvis der kom fine gæster. Det skete, at Poul Reumert eller Henning Moritzen og Lise Ringheim kom på besøg til en kop kaffe. Så meddelte hun mig: ”Henning og Lise kommer i eftermiddag. Så skal vi have de fine kopper på inde i privaten.” Det var altid mig, der skulle servere for dem, hvilket jeg absolut ikke havde noget imod. Når køkkenpigerne så bagefter stod og vaskede de fine kopper af, kunne hun finde på at sige: ”I behøver ikke gøre det så godt, for jeg kan gøre det om til vinter!” Henning og Lise købte Poul Reumerts hus på Vagtbakken i 1967."}, {"type": "para", "text": "Viggo var ca. 55 år og ugift, hvilket vi piger godt kunne forstå, når han om morgenen gav os et knus eller en omfavnelse. Han var ikke altid lige soigneret, og han skråede, men jeg har aldrig set nogen med så klare ærlige blå øjne. Jeg er sikker på, at han kunne være blevet en flot fyr og have set yngre ud, hvis han ikke havde været karseklippet, og hvis han var blevet soigneret og havde fået noget pænt tøj på. Viggo var, ligesom sin far, opsynsmand ved Kandestedernes Redningsvæsen i 35 år, indtil dette blev nedlagt, og han var strandfoged så længe, han levede. Viggo var flittig og arbejdsom, men en stille, lidt indadvendt og særegen natur, og mange kom aldrig rigtigt på talefod med ham. Over for os piger var han dog utrolig rar og meget hjælpsom, men han kunne også have sine mørke dage. Når han var i humør til det, fortalte han historier, og så kunne vi selv dømme, om de var sande eller ej. Og han havde lune – han elskede at små-drille dem, han kunne lide. Viggo an- vendte ofte korte, udtryksfulde sætninger, såsom ”det var hulens” og ”hulemæ”, hvilket følgende anekdote også bevidner. Viggo havde engang været i USA, og mange troede, at han ville blive der, men pludselig var han vendt hjem. Da han så nogle år senere var gæst ved et middagsselskab hos nogle sommergæster, underholdt hans fine borddame ham om sin nylige rejse til USA. Viggo sad og passede sin mad uden kommentarer, men da hans borddame ved desserten udbrød: ”Ved De hvad Viggo Hjorth, De skulle også prøve at rejse en tur til Amerika”, så lød det så højt fra Viggo, at det kunne høres over hele bordet: ”A har wå’t der!” Da hans borddame nu ville høre, hvor i USA, kom det kort og godt fra Viggo: ”Over det hele!” – og så var det emne uddebatteret."}, {"type": "para", "text": "Som sagt var det ikke de store udskejelser, vi foretog os sådanne somre. Det vildeste, vi kunne præstere, var en tur på Milen eller i bølgerne tidligt om morgenen, hvis vi ellers orkede at stå op til det, men nogle gange gik der sport og væddemål i det. Når vi så endelig tog os sammen til en tur på Milen, var det en fantastisk oplevelse at komme derud så tidligt om morgenen og se solopgangen, det specielle lys og den stilhed, der herskede. Det skete også, at vi fik besøg hjemmefra. Far lånte i løbet af sommeren en bil en søndag, og så kom han og Per. Det så vi frem til, og så hjalp de andre til, så mor og jeg kunne få lidt frihed til at være sammen med dem. En gang fik jeg besøg af en ”kæreste”, der insisterede på at besøge mig, selvom jeg ikke var interesseret. Han kom en aften kørende på knallert fra Østervrå, og jeg var slet ikke glad for at se ham. Vi gik en tur på stranden, hvor jeg fik ham fortalt, at jeg ikke syntes, vi skulle fortsætte med at komme sammen. Han tog det meget pænt og tøffede de 50 km tilbage til Østervrå, men mor skældte mig ud, hvilket jeg syntes var uberettiget, for jeg havde jo sagt til ham, at han ikke skulle komme."}, {"type": "para", "text": "Mor fik fast løn og kunne have ca. 6.000 skattefrie kroner med sig hjem plus drikkepenge efter sommerferien. Vi servitricer fik procenter af salget samt drikkepenge, så jeg kunne typisk sætte 3.000 kr. i banken efter sommerferien. De faste gæster gav godt med drikkepenge. Når en familie rejste, lagde de ofte en god skilling (fx 200 kr.), som vi alle skulle dele, men det hændte også, at de kom og stak os hver en seddel, og nogle fik mere end andre, alt efter den service vi havde ydet. Jo, det var virkelig et servicejob, hvor det kunne betale sig at have det store smil fremme."}, {"type": "para", "text": "Min sidste sæson var sommeren 1968, for det efterfølgende år skulle jeg være student, og efter at mor begyndte på sin batik-fabrikation, kom hun der heller ikke mere. Vi besøgte adskillige gange Viggo og fru Hjorth, både på hotellet og senere i det hus, de byggede i midten af 70erne ved landevejen. Vi var klar over, at Viggo ikke var rask, men det kom alligevel bagpå os, da han i juni 1979 begik selvmord. Han havde kræft og ville hellere tage sit eget liv end dø af sygdommen. Viggo blev 70 år, og fru Hjorth døde i en alder af 92 år. I dag ligger de begge begravet sammen med Peter Hjorth på Hulsig Kirkegård."}, {"type": "para", "text": "I foråret 1999 tog vi et weekendophold på Hjorths Hotel, for mig et tilbageblik i nostalgiens verden og en dejlig oplevelse, som jeg håber at kunne gøre om. Jeg tror, at Vagn og Lars var lidt trætte af at høre om, hvordan vi gjorde tingene, da jeg arbejdede der, og på et tidspunkt foreslog de mig, at jeg kunne blive genansat. Selvom det kun var 4 somre, jeg arbejdede på Hjorths Hotel, har det betydet meget for mig og sat dybe spor på en positiv måde."}]}, {"title": "Fadæser", "blocks": [{"type": "para", "text": "Ingen kan gå igennem livet uden at dumme sig – heller ikke mig. Problemet var, at jeg som barn og ung tog det meget tungt, når det skete, og næsten ikke kunne komme over det igen. Årsagen var, at jeg var meget ærekær og gerne ville være perfekt. Det har jeg heldigvis med årene indset, at ingen er, men der gik lang tid."}, {"type": "para", "text": "Første gang, jeg erindrer at have lavet en fadæse, var som 4-årig, da jeg en dag under leg med Jens Erik Frost kom til at slå et lille stykke af låget til en porcelæns sukkerskål, der stod på skabet i deres stue. Jeg gik straks hjem, men kunne ikke få det sagt til mor. Først efter et par dage tog jeg mod til mig. Mor blev heldigvis ikke vred, og jeg tror, hun fik snakket med Rigmor om det. Men længe efter episoden var jeg ikke meget for at gå derover og lege."}, {"type": "para", "text": "Der har sikkert været andre episoder, som jeg ikke mere husker, men noget, jeg husker tydeligt var, da jeg kørte ind i garageporten derhjemme – uden kørekort. Jeg var som 19-årig i gang med at tage kørekort hos Eli Carlsen i Østervrå. Jeg havde kun haft nogle få timer men havde lært at bakke – troede jeg. Desuden var jeg meget motiveret og syntes, det var sjovt at køre bil. Mor og far kendte en ungkarl, der hed Knud og var på alder med mor. Han havde købt sig en rød Kadet uden at have kørekort, og en dag kom han ind og spurgte far, om han kunne have sin bil stående i vores garage mod at vi så lånte den, når det passede os. Det var en fin ordning, og Knud havde på den måde altid nogen til at køre for sig. Han var meget rundhåndet over for os, men mor var også god mod ham. Hun vaskede og strøg hans tøj, og han spiste ofte med. Jeg fik mange gaver af Knud og lov til at køre i hans bil, og nogle var så flinke at antyde, at han nok var lige lovlig interesseret i mig. Jeg følte dog aldrig, at dette var tilfældet. Knud blev senere gift og fik en datter, som kom til at hedde Merete – måske var hun opkaldt efter mig? Knud er i dag skilt og bor ikke mere i sit hus på Tryvej. Mor var skuffet over, at han ikke kom til fars begravelse, men Knud var en mærkelig stædig rad, der havde sine idéer. Han mente ikke, man skulle komme til en begravelse, hvis dødsannoncen først var i avisen efter begravelsen, hvilket var tilfældet, da far døde. Men tilbage til min fadæse."}, {"type": "para", "text": "En søndag skulle vi sammen med Knud ud at køre og have mad med. Det gjorde vi tit, og på den måde fik Knud jo også glæde af sin bil. Far ville gå ud og køre bilen ud af garagen, og så skulle vi samle Knud op længere henne ad vejen, hvor han boede. Da far havde kørt bilen ud af garagen og holdt i indkørslen, spurgte jeg ham, om jeg ikke måtte bakke den ud på vejen. Det havde jeg jo lige lært. Og far, der aldrig nægtede mig noget, sagde selvfølgelig ja. Hvad jeg ikke havde forudset var, at bremserne i Knuds bil var dårligere end i Elis. Da jeg skulle rette bilen op, fordi jeg var kommet lidt skævt afsted, nåede jeg ikke at bremse, før bilen kørte skråt ind i siden af porten. Noget af træet løsnede sig, men der var heldigvis ikke noget at se på bilen. Jeg skyndte mig brødebetynget at overlade rattet til far, og vi blev enige om ikke at sige noget til Knud. Senere kom Elbo og udbedrede skaderne på porten, og så blev der ikke snakket mere om den sag. Tilbage var så mine frustrationer og ærgrelsen over, at jeg havde dummet mig. Søndagesturen var for mig ødelagt, og jeg satte mig ikke mere bag rattet, før jeg havde kørekort."}, {"type": "para", "text": "Det fik jeg efter 19½ time, første gang jeg var oppe, og det på trods af, at jeg nær havde kørt en cyklist ned. Inden jeg nåede at bremse, mærkede jeg, at bremsepedalen forsvandt under min fod. Det var den motorsagkyndige, der var hurtigere end mig. Men åbenbart var det ikke noget, der bekymrede ham i hans bedømmelse, for jeg fik kortet, og stolt var jeg, da jeg kom hjem til mor og far. På vej hjem fra Sæby, hvor jeg havde kørt under hele perioden, gav Eli kaffe og kage på et cafeteria."}, {"type": "para", "text": "Det var først nu, jeg skulle til at lære at køre bil, men jeg kunne nemt låne Knuds Kadet, også uden at Knud fulgte med. I efteråret 1969 købte far sin første bil, en mørkeblå Ford Taunus, splinterny og flot. Da var der stolthed at spore hos Erik Møller Jensen. Om Knud fandt et andet hjem til sin røde Kadet, husker jeg ikke. Måske solgte han den, for jeg tror aldrig, han fik sig et kørekort."}, {"type": "para", "text": "Selvom mor og far var ømme over deres nye bil, var der aldrig problemer med at låne den. Det var jo også dejligt for far, at han ikke absolut skulle med hver gang, mor ville af sted. For øvrigt flyttede jeg hjemmefra til september, så det var kun i weekenderne, det var aktuelt at låne den."}, {"type": "para", "text": "En weekend, jeg var hjemme det efterår, lavede jeg de første skrammer i bilen. Vi var fredag aften i Skæve hos mormor og morfar, og Per var ude at spille fodbold. Senere på aftenen skulle han hentes, og det ville jeg gerne gøre. På vej ned ad den halvrunde nedkørsel skrabte jeg underkanten af bilen mod kantstenene omkring blomsterbedet, og så var aftenen ødelagt. Der var ingen, der skældte ud, men jeg var frygtelig ked af det. Jeg husker, at jeg i ugen efter skrev et langt brev til mor og far (dengang skrev man til hinanden), hvor jeg også nævnte episoden og fortalte dem, hvor ked af det, jeg var. Jeg var nu heller ikke verdens bedste bilist og bli’r det aldrig."}, {"type": "para", "text": "Som 17-årig mærkede jeg første gang, hvad spiritus kan gøre ved én. Som tidligere nævnt drak vi piger altid sodavand, når vi var til fest, men denne gang var jeg til fest med en ældre generation, og måske derfor gik det galt. Hele familien var til fest hos Moster og Ib i Skagen, og jeg var en af de yngste. Det var om sommeren, og efter middagen gik vi ud i haven, hvor der var indrettet bar på terrassen. Bartenderen var Ibs søsters mand Vagn, og han har senere fået skyld for, at han drak mig fuld. Jeg kunne ikke lide spiritus, men han lavede nogle vodka og juice drinks, som smagte ret godt. Stemningen blev også rigtig god, indtil jeg lå og talte fransk i et telt ude i haven. Senere blev jeg installeret i Mosters seng med en balje ved min side. Jeg var hundesyg, og næste dag var jeg meget flov. Forsamlingen tog det nu fra den humoristiske side og syntes, det var sjovt. Selv mor, som nok kunne være streng, tog det meget pænt og bebrejdede mig ikke noget. Men det, som man talte mest om næste dag, var fars badekar-seance. Det havde åbenbart været en våd fest, og flere havde fået for meget at drikke, deriblandt også far. På et tidspunkt var toilettet optaget i ret lang tid, og da man begyndte at undre sig og undersøge sagen, viste det sig, at far var gået i seng – i badekarret. Han forklarede det med, at der jo var så mange, der skulle overnatte, så hvis han nu tog badekarret, ville der være en ekstra plads. Tøjet havde han lagt ligeså sirligt på toiletbrættet. Det endte med, at far og jeg tilbragte natten side om side i dobbeltsengen, og Moster tog entré : ”50 øre for at se far og datter”. For eftertiden, når der skulle overnattes i familien, sagde de altid: ”Erik kan da sove i badekarret”."}]}, {"title": "Gymnasietiden", "blocks": [{"type": "para", "text": "Den 16. april 1966 sender Hr. skoleinspektør M. Bramsen følgende brev til Hr. lagerforvalter E. Møller Jensen, Thorshøj: ” Lærerrådet har indstillet Deres datter, Merete Møller Jensen, som egnet til optagelse i gymnasiet efter 2. real. Hun kan herefter vente at blive optaget uden optagelsesprøve.” Udover dette havde lærerne vurderet, at jeg var lige så dygtig til det matematiske som til det sproglige, men der havde de imidlertid taget fejl. Mor syntes bestemt, at jeg skulle være matematisk student, for de sproglige piger var så useriøse og kunne ikke bruge deres eksamen til så meget. En rigtig student var en matematisk student. Jeg indordnede mig som så ofte, selvom jeg jo inderst inde godt vidste, hvor min interesse lå. Men hvad jeg ikke var forberedt på var, at springet var så stort fra 2. real til 1.g. Det spring var vi to i klassen, der tog: Jette Kragelund og mig. I 2. real havde jeg været en af de dygtigste i klassen – nu befandt jeg mig i den dårligste halvdel. Jette klarede sig dog bedre end mig i gymnasiet og blev senere gift med en kedelig professortype, der scorede rene 13taller. De har sikkert fået nogle kloge børn."}, {"type": "para", "text": "Men der var nu også et stort spring i stoffet, især det matematiske. Sprogene, engelsk og fransk, kunne jeg sagtens klare, her lå jeg i toppen, men dansk var blevet sværere, og i min første stil fik jeg kun et 7-tal, hvilket var meget skuffende, når man var vant til at få 10 og 11. Bedre blev det heller ikke af, at vi havde fået en nordmand til matematik. Vi kunne simpelthen ikke forstå, hvad han sagde, og halvdelen af klassen fik 03 og 5. Heldigvis rejste han, og i 2.g. fik vi en kvindelig matematiklærer, Ruth Christensen, som kunne lære selv de dummeste matematik. Hun var meget lidt køn, havde overbid og var ugift, men med hendes hjælp nåede jeg helt op på 9- og 10-taller. 2.g. var mit absolut bedste år på gymnasiet, og jeg klarede mig pænt til eksamen. I 3.g. fik vi desværre en ny matematiklærer, og så faldt niveauet igen. Jeg var nu fast besluttet på, at jeg ville læse fransk og engelsk på universitetet, uanset hvad mor sagde, og jeg glædede mig til endelig udelukkende at skulle beskæftige mig med fag, der interesserede mig. På gymnasiet var der så mange fag, jeg ikke brød mig om, såsom historie, geografi og fysik. Jeg var ofte bange for at blive hørt, især i fysik, hvor vi havde en meget striks lærer. Han havde en vis evne til at gøre os nervøse ved at tage sin notesbog frem, fatte om blyanten, kigge ud i lokalet og tilfældigt slå ned på et navn i bogen. Han kiggede så først på navnet, dernæst rundt i lokalet, fæstnede sit blik på en person – og nævnte et helt andet navn. Det var psykisk terror, især når man ikke helt havde styr på stoffet. Historietimerne var derimod ikke forbundet med spænding, for læreren sad på bordet hele timen og diskuterede politik med drengene, mens vi piger sad og strikkede. Alle vi passive fik 8 i karakterbogen, så til eksamen i 3.g. i historie var der meget, der skulle læses op. Derimod syntes jeg, at oldtidskundskab, også kaldet oldævl, var interessant. Vi havde rektor Brodersen til dette fag. Han lignede selv en græsk gud og var meget skrap. Dele af biologiundervisningen var også interessant. En overgang havde vi Anker Buch, den berømte violinist, som vikar til sang. Han havde det svært, for der var ikke megen respekt at spore hos drengene, som hellere ville spille kort i de timer. Han prøvede alt muligt for at fange vores interesse, såsom naturligvis at spille på sin violin, spille plader og fyre dårlige vitser eller ordspil af. Fx: ”Ka’ I li’ cognac? Det ka’ whiskey (vi ski’)” eller ”Ka’ mus lide gulerødder? Ka’ rotter?” Lige meget hjalp det. Drengene blev ved med at spille kort og pigerne strikkede, men til forskel fra drengene hørte vi efter. De larmede bare. En dag tog hr. Buch dog fusen på os. Han stod med blikket rettet mod døren, som vi andre sad med ryggen til. Pludselig sagde han: ”Goddag Rektor”. Alle røg op fra deres pladser som skudt ud af en kanon, og der blev musestille i klassen. Indtil det gik op for os, at det var en joke, og at der ingen Rektor stod i klassen. Den lo han selv meget af."}, {"type": "para", "text": "Min gymnasietid var ikke speciel lykkelig. Det var hårdt arbejde. Hver dag stod jeg op kl. 5.30 for at tage bussen kl. 6.40 til Hjørring. Jeg sørgede selv for at komme op, og jeg smurte selv min madpakke, hvilket jeg havde gjort hele min skoletid. Jeg var først hjemme igen ved 16-tiden. Så lukkede jeg mig inde på mit værelse med lektierne, men da jeg allerede dengang elskede en god varme, skruede jeg helt op for radiatoren. Dette resulterede ofte i, at jeg måtte kæmpe for at holde mig vågen (ofte uden held) og ikke fik læst så meget før spisetid. Hvis jeg så også engang imellem skulle ud med vennerne, fik jeg ikke læst så meget, som jeg burde. I de matematiske fag skulle jeg virkelig slide for at hænge på, men heldigvis kom jeg nemmere igennem sprogfagene. Om lørdagen gik vi i skole til kl. 13. Heldigvis havde jeg ikke så mange pligter derhjemme, for mor kunne godt se, at jeg havde det hårdt. Fra 1966 til 1968 var jeg med i elevbladets redaktion på Østervrå Centralskole, og på den måde bevarede jeg forbindelsen med min elskede folkeskole."}, {"type": "para", "text": "Der var selvfølgelig også lyspunkter. Jeg fik mange gode veninder på gymnasiet, og vi havde det hyggeligt sammen, men de fester, som mange af mine klassekammerater gik til i Hjørring, var jazzballer, og da jazz aldrig har interesseret mig, var jeg kun med et par gange. Mit netværk havde jeg stadig i Østervrå, og det var der, jeg trivedes bedst. Højdepunkterne på gymnasiet var det årlige skolebal, hvor dress code var lang kjole. Det første år fik jeg syet en smuk lang pinkfarvet thaisilkekjole. Vi fik altid smørrebrød til skolefesterne. I 1969 kostede 6 stk. smørrebrød, 2 øl, 1 vand, 2 kaffe og 5 snaps 61,60 kr. I 3.g. dansede vi lanciers, også i lange kjoler og smoking. Min partner hed Poul Erik, og det gik rigtig godt med dansen. Han var ganske almindelig begavet men fik senere en høj stilling ved Ambassaden i Washington. Jeg så ham til vores 25 års jubilæum, som var et hyggeligt gensyn med klassekammerater og lærere."}, {"type": "para", "text": "I 1968 var jeg med klassen på udflugt til Norge."}, {"type": "para", "text": "En af mine gode veninder gik i en parallelklasse og hed Hannemarie. Hun var kusine til Jette Kragelund og boede på gården Broens Mølle lige før Hørby. Vi kørte i bus sammen hver dag og var tit med hinanden hjemme. Hun var en frisk pige med hvidt krøllet hår. Jeg fik det indtryk, at hendes mor havde dårlige nerver, men det var ikke så sært, eftersom hun blev holdt nede af Hannemarie. Jeg var ofte chokeret over den måde, hun både omtalte og tiltalte sin mor på. Det skulle jeg lige have prøvet over for min mor."}, {"type": "figure", "caption": "Her er trekløveret blevet til et firkløver. Jeg er 18 år.", "page": 79, "file": "assets/images/p079_076.jpg", "dim": [623, 860]}, {"type": "para", "text": "Endelig oprandt sidste skoledag i begyndelsen af maj 1969, og vi skulle møde op udklædte. Jeg var klædt ud som julemand og vandrede op til bussen iført dette kostume og med sækken på nakken. Heri var der ikke gaver til børnene, men bajere og en enkelt hvidtøl. Vi festede hele dagen, var lige hjemme og klæde om, hvorefter jeg kørte til privatfest hos en af drengene, som hed Henning og var fra Sønder Harritslev Mejeri. Jeg havde lånt Kadetten og rørte derfor ikke spiritus hele aftenen, men da jeg skulle køre den lange vej hjem kl. 4 om morgenen, var der så tåget, at jeg ikke kunne se en hånd for mig. Det var en drøj tur hjem i sneglefart, og jeg var glad, da jeg lå hjemme i min seng."}, {"type": "figure", "caption": "", "page": 79, "file": "assets/images/p079_077.jpg", "dim": [561, 800]}, {"type": "para", "text": "Det var en lykkens dag, da jeg den 18. juni 1969 fik sat huen (str. 54) på hovedet efter at have fået et 9-tal i kemi og kunne kalde mig matematisk-fysisk student. Jeg var glad, og mor og far var stolte. Vi var 167 studenter det år. Mit gennemsnit var kun på 7,6, men jeg var ligeglad, for jeg havde søgt ind på franskstudiet i Århus, og der var ingen adgangsbegrænsning. Min glæde var heller ikke mindre af, at jeg kort forinden havde mødt prinsen på den hvide hest, Vagn fra Hvidsted ved Tårs. På grund af denne forelskelse var min eksamenslæsning heller ikke blevet så koncentreret, som den burde, men det skal ikke være en undskyldning for mit lave gennemsnit. Desværre kunne Vagn ikke være med til at fejre dagen, fordi han var på soldaterøvelse, men han deltog senere i nogle af de fester, jeg var med til. Mor og far havde gjort denne dag meget festlig. Da vi kom hjem om formiddagen, kom mormor og morfar, farmor, gudmor Dorthe og faster Grethe og Peter Mellergård til frokost. Mor havde broderet en klokkestreng med det latinske ordsprog: ”Gaudeamus igitur”, som Per gav mig. Af mor og far fik jeg et ur, af min elskede Vagn en guldkæde med et kors i guld med turkiser (se billedet af mig som student), af mormor og morfar 200 kr. og af farmor 50 kr. Vejret var fint, og vi blev fotograferet i haven med alle mine blomster og gaver. Senere kom Elbo og Vibeke og gratulerede. Om aftenen var mor, far, Per og jeg på Søbad i Sæby og spise. Det var en travl uge i festens tegn, og jeg holdt selv fest som en af de sidste. Vi sad ved et langt bord ude på terrassen, og det var hyggeligt, men det var helt tydeligt, at folk var ved at være trætte af at feste. Den aften var der landskamp på TV, så alle drengene satte sig ind i stuen på et tidspunkt for at se fodbold, og der kom først gang i dansen senere. Der var åbenbart også nogle, der syntes, at vi havde for lidt øl hjemme, for de hentede senere forstærkning. Det gik jeg nu ikke så meget op i, for jeg havde det selv vældig dejligt – jeg havde bestået min studentereksamen og var smaskforelsket, så der skulle mere til at ødelægge mit humør."}, {"type": "figure", "caption": "Peter Mellergård holder mig morer sig.", "page": 80, "file": "assets/images/p080_078.jpg", "dim": [860, 581]}]}, {"title": "Forelskelsen", "blocks": [{"type": "figure", "caption": "Inga og Poul, julen 1969 i Hvidsted", "page": 80, "file": "assets/images/p080_079.jpg", "dim": [613, 860]}, {"type": "para", "text": "Jeg vil nu gå tilbage til den 10. maj 1969 – en aften, der fik stor betydning for resten af mit liv. Min veninde, Inga Boelskifte, havde lørdagen før været til bal på Tårs Hotel, hvor hun havde været sammen med en sød fyr, der hed Poul. Nu skulle hun så møde ham igen, og hun ville have mig med. Hvor heldigt for mig. Vi havde med mors hjælp syet batik buksedragter, så vi så rigtig smarte ud. Jeg fik ret hurtigt øje på en pæn fyr, men han var desværre sammen med en anden pige. Senere på aftenen kom han hen og gav øl til dem, der sad ved bordet. Jeg sad lidt udenfor på en bænk, men høflig som han var, spurgte han også mig, om jeg ville have en øl. Jeg kunne egentlig ikke lide øl, men for at komme i snak med fyren, som hed Vagn, sagde jeg ja tak. Senere bød han mig op, og jeg kunne mærke, hvordan mit hjerte bankede voldsomt. Han var pæn i tøjet: lyseblå skjorte, grå bukser og en grøn trøje med knapper. Hans øjne var blå og dejligt smilende, og håret var mørkt. Hans opførsel var høflig, og han var Inga og Poul, julen 1969 i Hvidsted meget charmerende. Jeg var blevet forelsket, og jeg blev ret hurtigt klar over, at det var alvor. Derfor gjorde jeg heller ikke modstand, da han lagde an til kinddans. Det blev en uforglemmelig aften, og Inga og jeg gik fra Tårs Hotel med hver sin fyr under armen, og så var de oven i købet kammerater. Vi skulle hjem til Poul på Østergård i Hvidsted, og jeg skulle køre i Ingas fars bil, en Simca, fordi Inga skulle køre Pouls fars bil. Jeg husker endnu det problem, vi havde med at finde lyset på bilen, og hvordan vi rodede i handskerummet for at finde instruktionsbogen. Da vi kom til Østergård skulle vi forcere en meget snæver indkørsel, og jeg var ikke den mest drevne chauffør med mit nyerhvervede kørekort. Men vi kom igennem muren uden skrammer. Hos Poul fik vi spejlæg, hvilket ofte var menuen efter et bal ude på landet, men denne nat kom spejlæggene fra mågeæg."}, {"type": "figure", "caption": "", "page": 81, "file": "assets/images/p081_080.jpg", "dim": [601, 860]}, {"type": "para", "text": "Vagn var soldat på Nr. Uttrup Kaserne ved Ålborg, så jeg så ham ofte i uniform, hvilket gjorde ham om end mere attraktiv. Han var min soldat, og jeg har lige siden den tid haft dette billede af ham som soldat stående ved min seng. Vi ringede sammen og var sammen hver weekend, hvis han da ikke havde vagt. Det skete, at han mod betaling fik en anden soldat til at sove i sin seng, så han kunne være sammen med mig. Jeg var også ret imponeret over, at hans far havde en Volvo, og stolt, når jeg blev hentet i den. Jeg kunne ikke få mig selv til at sige, at vi ingen bil havde, så Vagn troede, at Kadetten var vores. Han blev derfor meget forbavset, da han fandt ud af, hvordan tingene hang sammen."}, {"type": "para", "text": "Jeg var spændt, da jeg skulle møde Vagns forældre, Krista og Chr. Viggo. Jeg havde besøgt Vagn en aften, hvor de ikke var hjemme, så jeg havde set gården, Vestergård i Hvidsted, mellem Ilbro og Tårs. Gården var på 36 tdr. land, og selv jeg, der ikke vidste meget om landbrug, kunne straks se, at det var dygtige mennesker, der boede her. Der var orden overalt, og der lugtede ikke af ko i bryggerset, som der havde gjort på mange af de gårde, jeg havde besøgt , mens jeg gik i skole. Stuerne var smagfuldt indrettet i lidt ældre stil, end jeg var vant til, men det var dyre møbler, kongelige porcelænsfigurer og prismelysekroner. Alt passede sammen. Broderier og orkerede flakoner vidnede om, at her boede der en kone, der var dygtig med sine hænder. Det var mit indtryk, at Vagns forældre var noget mere velstående end mine. De var desuden noget ældre. Mens mine forældre i maj 1969 var hhv. 44 år og 35 år, var Vagns forældre hhv. 58 år og 54 år. Jeg skulle med Vagn hjem og spise middag en søndag, og jeg blev virkelig godt modtaget. De var meget gæstfrie og flinke. Ved samme lejlighed mødte jeg Vagns storesøster Doris på 26 og hans storebror Tage på 24. Doris, Vagn og Tage Vagn var 20 og ville fylde 21 den 12.8. Doris var gift med Poul Erik på 28, og de havde Jens Christian på 2 år. Tage var ungkarl, hvilket han forblev, indtil han i 1996 giftede sig med AnnaLise. Den 16. april 1970 fik Doris og Poul Erik barn munner to, nemlig Charlotte. Hverken jordemoderen eller lægen havde opdaget, at Charlotte var født med ganespaltning. Det fandt forældrene selv ud af, da det viste sig, at hun ikke tog mad til sig. Efterfølgende var Doris flere gange indlagt sammen med Charlotte for at få indsat og indopereret en kunstig gane."}, {"type": "figure", "caption": "Doris, Vagn og Tage", "page": 81, "file": "assets/images/p081_081.jpg", "dim": [860, 657]}, {"type": "figure", "caption": "Vestergård", "page": 82, "file": "assets/images/p082_082.jpg", "dim": [860, 679]}, {"type": "para", "text": "Vagn blev også taget godt imod i Thorshøj, selvom vi ingen mad havde i huset første gang, han var der. Det var en fredag aften op til pinse, hvor mor og far skulle i byen. Jeg skulle i biografen i Tårs sammen med Vagn, Inga og Poul. Bagefter skulle vi have kaffe i Thorshøj, men da mor ikke havde fået handlet ind til pinsen, havde vi ingen brød eller kage i huset. I stedet gav hun mig 5 kr., som jeg skulle købe kage for ved bageren. Det lykkedes os ikke at finde en bagerforretning, der var åben, så vi kom hjem til et tomt kaffebord. Det var Vagn bestemt ikke vant til hjemmefra. ”Har I ikke engang en tvebakke?” spurgte han. Det havde vi ikke. I stedet spiste vi den is, mor havde lavet til pinsen. Mor og far kom hjem, inden gæsterne gik, og bagefter udtrykte mor sin begejstring for sin nye svigersøn. Det ville hun ikke have gjort, hvis hun ikke havde kunnet lide ham. Far sagde naturligvis ikke noget, men senere kunne han ikke skjule, at han var meget glad for Vagn. Per var også temmelig vild med sin nye svoger, måske mest fordi han havde en scooter. Senere på sommeren købte han en Folkevogn."}, {"type": "para", "text": "Sommeren 1969 var en pragtfuld sommer, hvor jeg var meget sammen med Vagn, bortset fra de 14 dage jeg sejlede med Onkel Erik i hans motorbåd. Vi sejlede bl.a. i det Fynske Øhav og havde en fin tur, hvor vi oplevede både orkan og pragtfuldt solskinsvejr, og hvor jeg faldt i havnen i Stubbekøbing. Jeg troede, at min sidste time var kommet, for jeg kunne ikke svømme. Erik var ikke klar over dette, så han havde bedt mig holde linen, da vi skulle lægge til i havnen. Jeg havde sat det ene ben på land og havde haft det andet på båden, med det resultat, at båden var gledte ud, og jeg var faldet i vandet. Heldigvis fik jeg på mirakuløs måde fat i rebet og fik mig halet oven vande. Erik opdagede først, hvad der var sket, da jeg stak mit våde hoved op over vandkanten og folk begyndte at stimle sammen ved havnekanten. Så kan det nok være, at han fik mig halet i land. Min pung, som jeg havde i lommen, var helt gennemblødt, og pengesedlerne måtte hænges til tørre. Jeg var ret chokeret oven på den oplevelse, så om aftenen gik vi i biografen for at aflede tankerne. Endnu engang var der én, der holdt hånden over mig."}, {"type": "figure", "caption": "", "page": 82, "file": "assets/images/p082_083.jpg", "dim": [860, 568]}, {"type": "para", "text": "Da jeg så kom hjem, skulle jeg udelukkende være sammen med Vagn. Vi tog på telttur til Sæby og troede, vi kunne få lov at være i fred. Men Emma og Maltha havde sommerhus i Sæby og havde besøg af mormor, morfar og Per. Søndag morgen kom Per på besøg på campingpladsen, nok ikke ligefrem det bedste tidspunkt at besøge os på, men efter at han havde drukket den cola, Vagn langede ud til ham gemmen teltdøren, var vi klar til at tage imod."}]}, {"title": "Jeg flytter hjemmefra", "blocks": [{"type": "para", "text": "Jeg havde som sagt søgt ind på Århus Universitet og var blevet optaget på franskstudiet. Det betød, at jeg skulle flytte til Århus den 1. september 1969. En søndag tog mor, far og jeg til Århus for at finde en bolig til mig. Vi så på flere værelser og endte med at leje et 6 m2 stort værelse på Klintevej 8 i Risskov til 200 kr. om måneden. Det var en del af et parcelhus, hvor ejerens søn, der studerede jura, boede. Jeg skulle altså dele køkken og bad med denne overstuderede og usoignerede unge mand."}, {"type": "para", "text": "Det var en trist tid derhjemme, inden jeg skulle flytte. Mor var i dårligt humør, fordi jeg skulle forlade dem, og i dag kan jeg sagtens forstå hende. Dengang syntes jeg bare, at hun var urimelig. Det var en sørgelig dag, da mor og far afleverede mig den 31. august og jeg vinkede farvel til dem uden for min nye bolig. En epoke af mit liv var slut, og jeg skulle videre med mit liv og lære at stå på egne ben. Det var naturligvis sundt for mig, som havde været meget afhængig af min mor. Det store lyspunkt var, at Vagn, som jo var soldat, ville besøge mig hver onsdag aften, foruden at vi skulle være sammen alle de weekends, han ikke skulle have vagt. Det første, jeg gjorde, var at gøre rent på badeværelset. Køkkenet undgik jeg helst, for her huserede den jurastuderende og dennes kæreste, som ofte var på besøg. Jeg levede på en sten og lavede kun varm mad, når Vagn kom på besøg. Min debut hermed var ikke særlig vellykket, idet jeg ved hjælp af Frk. Jensens Kogebog fik fremtryllet en karrysovs, der var så grøn, at den røg direkte i kloakken. Og hvad er der så tilbage af boller i karry?"}, {"type": "para", "text": "Den 1.9. startede studierne på Universitetet, og jeg cyklede de 5 km. derind. Jeg mødte nogle af mine klassekammerater fra gymnasiet, men ingen skulle studere fransk ligesom mig. Jeg fandt dog snart sammen med nogle medstuderende, bl.a. en pige, der hed Anna Marie Munk og var fra Harken. Hun boede på Nordre Strandvej, ikke langt fra mig."}, {"type": "para", "text": "Hver onsdag kom Vagn på besøg ved 19-tiden. Han tog toget fra Ålborg og havde en gammel cykel stående på Banegården i Århus. Jeg glædede mig meget til de aftner, men det var lidt hårdt for ham at skulle stå op kl. 3 om natten og cykle ind til toget, så han kunne være på vagt næste morgen."}]}, {"title": "Forlovelsen", "blocks": [{"type": "para", "text": "Vi havde besluttet, at vi ville forloves på min 20-års fødselsdag, onsdag den 12.11.1969, og sådan blev det. Vi havde købt forlovelsesringe hos guldsmed Hassing i Hjørring, guld med indlagt hvidguld samt inskription. Aftenen fejrede vi i Århus Hallen, som dengang var et dansested. Vi dansede tæt hele aftenen og var så forelskede, at vi ikke sansede ret meget omkring os bortset fra musikken. Den efterfølgende lørdag fejrede vi begivenheden hos mor og far i Thorshøj. Mor havde inviteret Vagns forældre og søskende samt vores bedste venner, Inga og Poul, og det blev en rigtig hyggelig aften. Vagn har i mor og fars gæstebog skrevet: ”Kære Doris og Erik! Tak for alle tiders aften. Det var dejligt at nyde den gode mad. Og til sidst tak fordi jeg måtte få Merete. Venlig hilsen Vagn”."}]}, {"title": "Studierne", "blocks": [{"type": "para", "text": "Udover franskstudierne skulle jeg tage den store latinprøve samt læse filosofikum, førstnævnte fordi jeg var matematisk student og kun havde den lille latinprøve. Latintimerne foregik hver morgen, og jeg nød dem. Der var så megen logik i den latinske grammatik, og jeg elskede at oversætte og analysere teksterne, som vi jo skulle. Desuden udtaltes ordene som de stavedes, så det med udtalen var let. Jeg klarede mig også ganske godt til eksamen. Filosofikum var en anden sag, som ikke interesserede mig så meget, så for at få det hurtigt overstået gik jeg til manuduktion. Det foregik i en mindre kreds hos en ældre studerende, der havde indrettet sit værelse til klasselokale. Mod betaling gik vi der nogle gange om ugen og gik så op til eksamen tidligere, end hvis vi skulle have fulgt undervisningen på universitetet. Eksamen var offentlig, og jeg var rystende nervøs, men jeg kom op i Descartes og reddede mig et 8-tal."}, {"type": "para", "text": "Franskstudierne interesserede mig naturligvis, men det gik ikke så let, som jeg havde forestillet mig. For det første var mange af mine medstuderende rigtig dygtige til at tale sproget, fordi de havde været i Frankrig og studere eller arbejde, og for det andet var der discipliner, der ikke interesserede mig så meget, såsom oldfransk og litteraturhistorie. Til samtaletimerne var vi heldigvis delt op efter niveau, så jeg kom sammen med studerende, der ikke var bedre end mig. Vi var tre piger på det hold, som havde det godt sammen og som også skrev opgaver sammen, bl.a. Anna Marie. Jeg var meget flittig, og efter 2 år gik jeg op til eksamen i bifag men dumpede den sidste dag i grammatik. Jeg manglede 1 point i at bestå og skulle hele møllen igennem igen efter et halvt år. Den dag var jeg totalt knust, så Vagn inviterede mig ud at spise. Det var dog ikke verdens undergang, fandt jeg ud af, for mange af de andre var også dumpet. Sådan var universitetslivet. Et halvt år senere prøvede jeg igen og bestod med glans. Jeg ville læse engelsk som hovedfag og gik straks i gang i januar 1972. Jeg var således 1½ år inde i mit hovedfag, da vi blev gift. Min bedste veninde og studiekammerat hed Grete og var fra Randers. Hun var utrolig smuk og sød men ikke noget lys. Jeg var med hjemme hos hendes forældre og besøgte også hendes søster, som boede i et hus på vej til Mejlby. Grete blev ret tidligt gravid ved et uheld og fik en lille pige, Julie, og hun flyttede sammen med Julies far. Jeg tror ikke, hun nogensinde færdiggjorde sine studier."}]}, {"title": "Arbejde under studierne", "blocks": [{"type": "para", "text": "Vagn havde jo sit gode job som tømrersvend, og takket være hans økonomi kom jeg igennem studierne uden alt for megen gæld. Selv bidrog jeg økonomisk så godt, jeg kunne. Ved siden af studierne fik jeg et job på Plejehjemmet Kirkegårdsvej i Århus. I starten var det i ferierne og i januar, som var studiefri, og senere også i weekenderne. Jeg gjorde rent og serverede aftensmad for de gamle. Plejehjemmet var gammelt, ligesom beboerne, så rengøringen var ikke specielt morsom. Jeg kunne derimod godt lide de vagter, hvor jeg gav de gamle aftensmad. Mange af dem kom jeg ligefrem til at holde af. Det var hårdt, når jeg arbejdede på den lukkede afdeling, for der var der virkelig nogle beboere, der var langt ude. Det var tragi-komisk, når fru Jensen gentagne gange påstod, at hun var Dronning Ingrid, og når en af beboerne smed alt tøjet og gik råbende og skrigende rundt på gangen. Ikke så sært, at dørene var låst ind til denne afdeling. Oversygeplejersken, fru Deleuran, var imidlertid ikke min kop te, mest fordi hun behandlede de gamle meget dårligt, skældte ud på dem og talte ned til dem. Når hun gjorde det, havde jeg ondt af de gamle, for de forstod jo godt, at de fik skæld ud. Det var også på dette plejehjem, at jeg første gang så en orkidé. Når jeg var på aftenvagt, var det mit job at bære blomsterne ud i skyllerummet for natten. En aften var der en blomst, der så lidt brun ud, så jeg kylede den i skraldespanden. Næste aften blev jeg af blomstens ejermand spurgt, hvor hans orkidé var blevet af. Han havde næsten lige fået den, og sådan en fin og dyr blomst kunne nemt stå i 14 dage. Jeg måtte indrømme, at jeg havde smidt den ud, men heldigvis var skraldespanden ikke blevet tømt, så jeg skyndte mig ud og fiskede vidunderet op igen. Senere fik jeg feriejob på Plejehjemmet Hørgårdsvej i Risskov, ikke langt fra hvor vi boede. Det var som at komme fra asken og i ilden. Plejehjemmet var helt nyt og moderne med Arne Jacobsen møbler og PH lamper, og atmosfæren var en helt anden end på De Gamles Hjem. Alle var søde og rare, og de gamle havde det godt. Der var 24 beboere fordelt på to etager, og de havde hver en dejlig lejlighed med tekøkken, stue og stort badeværelse. I starten gjorde jeg rent, men det var den rene svir, fordi det hele var nyt. Senere arbejdede jeg i køkkenet, bl.a. hver 4. weekend, hvor jeg hjalp med at stille maden an og vaske op. Da jeg havde været der et stykke tid, blev jeg forfremmet til ufaglært sygehjælper, hvilket indebar, at jeg skulle hjælpe beboerne med at blive vasket og komme i tøjet, give dem mad og ellers snakke med dem og hjælpe dem. Det blev jeg meget glad for, idet mange af dem var rimelig friske. Jeg husker tydeligt den mest åndsfriske af dem alle, fru Larsen på 80, som dækkede bord til alle beboerne hver dag og holdt et vågent øje med, at alt gik som det skulle i spisestuen. Hun tørrede selv støv af i sin lejlighed, og hun lavede meget håndarbejde. Til mit bryllup fik jeg en lilla hæklet tehætte af hende. En anden dame på 90, fru Warming, var også vældig åndsfrisk og gav mig en dag 15 kr., som jeg købte en hvid skål for. Begge gaver har jeg den dag i dag. Det gjorde ondt at se, at nogle af beboerne aldrig fik besøg, selvom de havde børn. De blev derfor glade, når man gav sig tid til at snakke lidt med dem."}, {"type": "para", "text": "En dag havde jeg en ubehagelig oplevelse. En af beboerne, som hed frk. Mikkelsen og var dårligt gående, havde nogle ærinder i Århus, så jeg blev bedt om at tage med hende derind. Vi var med taxa og havde kørestol med. Det gik fint, og vi forrettede flere ærinder på Strøget. Frk. Mikkelsen var åndsfrisk og meget stædig, så hun insisterede på selv at gå fra kørestolen og ind i butikkerne. Men på vej ud af en blomsterbutik i Clemens Stræde gik det galt. Hun faldt bagover, landede på halen og slog sit haleben. Jeg følte mig meget skyldig, selvom både hun og forstanderinden sagde, at det ikke var min skyld. Frk. Mikkelsen lå i sengen i 3 dage, men så var hun heldigvis frisk igen."}]}, {"title": "Bolig", "blocks": [{"type": "para", "text": "Jeg blev snart træt af at bo på mit lille hummer på Klintevej. Grunden var ikke så meget værelsets størrelse, for jeg havde fået det indrettet ret hyggeligt. Det var mere ejerens søn og hans skiftende damebekendtskaber, der generede mig. Der var ret lydt fra stuen, hvor han huserede, og jeg blev nogle gange midt om natten vækket af skænderier på den anden side af væggen. Senere skulle huset sælges, og sønnen flyttede. Jeg fik imidlertid lov til at bo der til februar, hvor jeg havde fundet noget andet at bo i. Så snart sønnen var flyttet, gik jeg i gang med den store rengøring af køkken og bad, men det var ikke rart om aftenen at komme hjem til et tomt hus. Alligevel tænkte jeg ikke så meget over de farer, der lurede, når jeg kom hjem om aftenen. Jeg stillede min cykel i skuret og skulle så om på den anden side af huset og låse mig ind i buldrende mørke. I dag ville jeg ikke have turdet gøre det, men dengang skyndte jeg mig bare at få låst op og låst igen. Den eneste gang, jeg har været rigtig bange, var efter en aften at have været i biografen og set en Alfred Hitchcock gyser. I lang tid derefter var jeg bange, når jeg stillede cyklen fra mig i mørket."}, {"type": "figure", "caption": "Her er vi til bryllup med Alice og Svend", "page": 86, "file": "assets/images/p086_084.jpg", "dim": [860, 573]}, {"type": "para", "text": "Jeg havde fundet mig et andet værelse i kvarteret, på Vester Strandallé 147, i kælderen hos et ungt barnløst ægtepar, Connie og Henning. Jeg havde et 12 m2 stort værelse i den ene ende af kælderen, og i den anden ende boede der en anden pige. Vi delte toilet og køkken, begge rum meget små, og køkkenet koldt om vinteren. Kælderen var lavloftet og fugtig, men jeg nød at have fået dobbelt så megen plads til 250 kr. om måneden."}, {"type": "para", "text": "Den 31. marts 1970 var Vagn færdig som soldat. Han havde fået arbejde hos en tømrermester, Ebbe Wermuth Jensen, i Egå, hvor han havde lejet et værelse på et slags kollegium. Her kunne han også købe sin varme mad og få smurt madpakker. Værelset var pænt men spartansk møbleret og uden hygge, men han tilbragte jo også det meste af tiden hos mig. På et tidspunkt flyttede min nabo, og jeg kunne overtage hele kælderen. Vagn og jeg gik i gang med at male og tapetsere, og kælderen blev helt pæn med orange tapet i gangen og gråt malet gulv på toilettet. Vagn flyttede ind, og vi havde nu vores helt egen lille lejlighed. Vi indrettede stue i mit værelse og soveværelse i det andet værelse. Vi fik et gammelt fjernsyn, som vi stillede på et ligeså gammelt skab, og så gik vi ud og købte os en trekvart seng. Da var det, at Vagns mor udbrød: ”Var det in’ bier, at I bløw jywt”. De havde nok lidt svært ved at forene sig med tanken om, at vi boede sammen uden at være gift. Om vinteren Morgenmad på sengen, 1971 spiste vi morgenmad i sengen, fordi køkkenet var som is. Vagn, som altid var den første, der stod op, drønede, efter at være blevet vasket, ud i køkkenet og satte corn flakes, mælk og tykmælk på en orangefarvet bakke, som han sekunder efter stillede i sengen imellem os, og så råhyggede vi os med det."}, {"type": "figure", "caption": "Morgenmad på sengen, 1971", "page": 86, "file": "assets/images/p086_085.jpg", "dim": [860, 556]}, {"type": "para", "text": "Da vi havde boet der et stykke tid, kom Vagns forældre på besøg. De skulle spise middagsmad hos os, men da vi ingen spisebord havde, måtte maden indtages ved sofabordet. Det havde Chr. Viggo alligevel aldrig prøvet før, at sidde så ubekvemt og skulle spise sin varme mad. Og så den fugt. Skulle vi ikke hellere se at få bygget os et hus? Han skulle nok hjælpe os til at få købt en grund. Og sådan blev det."}, {"type": "para", "text": "En weekend, hvorvi havde besøg af Inga og Poul, som vi kom meget sammen med dengang, kørte Vagn og Poul en tur for at kigge på byggegrunde. Tilfældigvis kom de igennem Spørring og så på en mark et skilt med ”Byggegrund til salg”. Grunden kostede 21.000 kr., og sådan gik det til, at vi kom til at bo i Spørring. Det var jo egentlig lige meget, hvor vi byggede hus, for vi skulle bare bo i det, til jeg var færdig med at læse – så skulle vi tilbage til Vendsyssel!"}, {"type": "figure", "caption": "Tage laver varme", "page": 87, "file": "assets/images/p087_086.jpg", "dim": [860, 593]}, {"type": "para", "text": "Da frosten var af jorden i foråret 1972, begyndte byggeriet. Huset skulle være på 130 m2, og bortset fra murer- og elektrikerarbejdet, som vi havde fremmede håndværkere til, lavede Vagn og Tage det hele. De havde året forinden bygget hus til Tage i Svenstrup syd for Ålborg, så nu var turen altså kommet til os. Der var og er et godt forhold mellem de to brødre, og de arbejdede godt sammen. Tage var på det tidspunkt ungkarl og kom meget på besøg i Spørring. Han boede på gæsteværelset, som vi kaldte Tages værelse, og han færdedes, som om han var hjemme. Det var hyggelige weekends, når Tage kom på besøg, altid fra fredag aften. Så gik han og Vagn og lavede forskellige ting, og mange af vores venner blev også Tages venner. Ofte tog de to brødre også ud at fiske og kom somme tider hjem med over hundrede fladfisk."}, {"type": "figure", "caption": "Jeg var ikke så god til at male, så jeg fik lov at male", "page": 87, "file": "assets/images/p087_087.jpg", "dim": [629, 860]}, {"type": "para", "text": "Vi faldt hurtigt til i Spørring og kom til at kende mange mennesker fra starten, sikkert i kraft af, at Vagn selv gik og byggede huset. Mange kom forbi og skulle lige se, hvad der foregik. Men det var jo Vagn, der gik her, og det var ham, folk snakkede med, ikke mig. Derfor var det da heller ikke med stor begejstring, at jeg sagde ja til at deltage i gadefesten i 1972 – jeg kendte jo ikke nogen. Gadefesten blev dengang på Østervang holdt Skt. Hans Aften og gik på skift hos dem, der havde plads, enten i en garage eller en lade. Det år blev gadefesten holdt i nr. 15, i Hanne og Kelds garage, med dertil hørende bål på marken. Jeg ville gøre et godt indtryk og havde taget pænt tøj, tynde sko, nydelig frakke og handsker på: kæmpe fiasko! Det regnede, så jeg troede, at vi så skulle være inde i stuen, men sådan var gadefest-konceptet ikke. Efter spadsereturen ud i marken til bålet var jeg blevet både våd på fødderne og forfrosset, så jeg sad og krøb sammen i mit fine tøj med handsker på og kunne aldeles ikke se det sjove i noget som helst. Jeg følte mig totalt udenfor. Vagn, derimod, kendte mange, og fandt snart sammen med de andre mænd omkring en flok bajere. Bedre blev det heller ikke af, at jeg næste dag skulle på arbejde på det plejehjem, hvor jeg havde sommerjob, så jeg ville gerne tidligt hjem. Flere år efter, da jeg var faldet godt til og satte stor pris på de andre af gadens beboere, fortalt man mig, at jeg den aften havde givet indtryk af at være snobbet og ”fin” på den, ikke mindst på grund af mine handsker."}, {"type": "para", "text": "Til august det år flyttede vi ind, og mor, far og Per kom og hjalp. Den aften, vi var flyttet ind, havde vi det ret muntert sammen med Erik Elektriker. Vi sad i køkkenet og drak øl og snaps til maden, og jeg tror, at både mor og far var lidt halvberusede, da de skulle i seng. De skulle sove på gæsteværelset, men mor syntes nu, at der skulle gardiner op først, så hun baksede med gardinstangen, stående på en stol. På billedet driller far hende ved at hive ned i hendes bukser. Det var ikke så tit, at far fandt på den slags drillerier. Mor betalte og syede gardiner til hele huset, samme stof, bare med forskellige farve striber: rød til køkken, brun til stue og orange og turkisblå til værelserne. Dog var badeværelsesgardinerne af tyndere stof. Det hele kostede 1200 kr."}, {"type": "figure", "caption": "", "page": 88, "file": "assets/images/p088_088.jpg", "dim": [860, 585]}, {"type": "para", "text": "Det var utroligt spændende at bo i nyt hus. Det var noget andet end en fugtig kælder. Vi tog i Bilka og købte reolsystem til 700 kr. til stuen. Det var grønt og rummeligt, og da vi mange år senere blev trætte af det, malede vi det hvidt. Vi købte brune fløjlsmøbler (1 + 2 + 3) og spisebord med 6 stole i Domo. Sofa-arrangementet kostede 2500 kr., og dertil købte vi et røgfarvet glasbord uden tanke for det upraktiske med støv og fedtede fingre. Den 10. januar 1973 kørte jeg med Eva og Leo til Hammel, hvor jeg købte et hyrdetæppe til at ligge under glasbordet. Det var højeste mode og kostede 630 kr. Når det blev snavset, kunne man vaske det i badekarret ved at jokke rundt oveni det med sine bare tæer. I stedet for at slænge os i de nye møbler i vores dejlige stue, indrettede vi i starten et værelse som TV-stue med et nyt Philips sort-hvid TV og træmøbler, som Vagn havde fabrikeret, og som, til trods for skumgummihynder, var frygtelige at sidde i. Men vi hyggede os i denne lille stue og syntes, at den rigtige stue var altfor stor til os. Tage fik farve-TV i starten af 1973, mine svigerforældre kort tid derefter, mens vi ventede til den 1. oktober 1977, den dag Lars blev født."}, {"type": "para", "text": "Telefon fik vi først i sommeren 1973, idet vi overtog farmors telefon, da hun døde. På den måde fik vi den til halv pris, ca. 600 kr. Indtil da måtte vi benytte os af telefonbokse."}, {"type": "para", "text": "Jeg havde gjort lidt nar af mor året før, fordi de havde købt opvaskemaskine. De var jo kun tre mennesker. Men Brugsen havde haft et godt tilbud på en Major opvaskemaskine til kun 1100 kr. Nu måtte vi bide i det sure æble og indrømme, at en sådan maskine kunne vi også godt tænke os i vores nye hus. Og sådan blev det, for tilbuddet gjaldt stadig. Jeg undskyldte dog vores køb med, at vi så sparede et køkkenskab til 300 kr."}, {"type": "para", "text": "Vi fik hurtigt fordelt arbejdsopgaverne: Vagn ordnede alt det uden for huset, og det indvendige samt vinduerne var mit domæne. Det betød, at det var Vagn, der gik i haven og vaskede bil, mens jeg gjorde rent og lavede mad. Jeg holdt huset til perfektionisme, og mor sagde altid, når de kom herned i weekenden, at man kunne udføre en blindtarmsoperation på badeværelset, så rent var der. Alt gik efter en snor: køkkenet blev sæbet af og gulvene vasket hver fredag, alle fliser og fodlister fik jævnligt en tur, og strygetøjet fik ikke lov at ligge længe. Jeg har en gang sagt nej til et byfestarrangement en fredag eftermiddag, fordi jeg skulle gøre mit køkken rent! Det var dengang."}, {"type": "para", "text": "Selv inden vi blev gift og på trods af travlhed med studier, følte jeg mig virkelig som en husmoder med dertil hørende pligter. Når jeg skulle lave mad, slog jeg op i Frk. Jensens Kogebog, som enhver husmoder med respekt for sig selv havde stående, og jeg sad da også nogle gange og stoppede strømper til Vagn, hvis jeg da ikke lod dem ligge, til mormor kom på besøg."}]}, {"title": "Spørring", "blocks": [{"type": "para", "text": "Landsbyen Spørring mellem Århus og Randers havde i 1972 ca. 675 indbyggere. Byen stammer tilbage fra 1306. På det tidspunkt var der allerede en kirke, idet denne blev bygget sidst i 1100tallet. Da vi kom til Spørring var der både kro og hotel. Spørring Hotel startede som afholdshotel i 1913 men fik i 1966 spiritusbevilling. Den kro, der ligger der i dag, men som nu er indrettet med lejligheder, blev bygget i 1897 og var oprindeligt kongelig privilegeret kro og gæstgiveri. Før den nuværende kro blev bygget, lå der en anden kro på den modsatte side af vejen. Den ældste skole i Spørring blev bygget i 1796 og ligger der endnu (Gl. Landevej 42). Den var skole helt frem til 1890, hvor der blev bygget en ny skole på Gl. Landevej 31, det vi i dag kalder Den Gamle Skole. Den ophørte med at være skole i 1968, hvor Bakkegårdsskolen i Trige blev indviet."}, {"type": "para", "text": "Landsbysamfundet i Spørring var hyggeligt, og vi deltog flittigt i diverse arrangementer. Der var en dilettantforening, som hvert år i marts opførte en forestilling flere aftner. Vi var der altid om lørdagen, for da var der bal bagefter. I juni hvert år var der også byfest i en hel uge, og vi sad i skolegården næsten hver aften (inden vi blev forældre) og hyggede os. På den måde lærte vi mange mennesker at kende. Ved den lejlighed var der også revy, opført af dilettantforeningen. Vi blev hurtigt medlem af Borgerforenin- gen og jeg af Husmoderforeningen, og Hotellet dannede rammen om mange af disse arrangementer, bl.a. den årlige høstfest, som vi som festkomité et år var med til at arrangere."}, {"type": "figure", "caption": "Østervang 25 set fra baghaven", "page": 89, "file": "assets/images/p089_089.jpg", "dim": [828, 640]}, {"type": "para", "text": "Det var i forbindelse med en dilettant- aften på Spørring Hotel at vi første gang havde indbrud, nemlig den 10. marts 1973. Vi havde haft gæster til middag, inden vi skulle på Hotellet (Eva, Leo, Kirsten og Erik), og da vi kom hjem derfra om natten, kunne jeg ikke forstå, at der var jord på gulvet i bryggerset. Jeg havde gjort huset pinligt rent inden den aften, og jeg var lige ved at skælde Vagn ud for at være synderen, der havde slæbt jord ind. Da vi så kom længere ind i huset, så vi, at der var stearin på gulvene – indbrudstyvene havde ikke villet tænde lys, så de var gået rundt med stearinlys. Alt var gennemrodet og snavset til, og mange af mine smykker manglede foruden vores fotografiapparat og kikkert samt noget sølvtøj. Det smykkeskrin, jeg havde fået af min farmor og farfar i konfirmationsgave, var væk. Det havde stået i vindueskarmen i soveværelset, hvor tyvene var brudt ind. Deri var mange smykker, som jeg havde fået i USA, og som var uerstat- telige. De havde sågar taget et par handsker, som de havde brugt for ikke at efterlade fingeraftryk. Jeg husker, at jeg satte mig ned på køkkengulvet og græd. Da vi ikke selv havde telefon, gik vi hen til Hanne og Keld og ringede til politiet. De kom herud, idet der også havde været indbrud andre steder på Østervang, bl.a. hos slagterens, hvor et pengeskab var blevet brudt op. Senere fandt man tyvene, men da havde de skilt sig af med de fleste af tyvekosterne. Vi fik nogle få smykker tilbage, deriblandt Vagns vielsesring – dog uden inskription. Den havde de slebet væk for nemmere at kunne sælge den. Vagn var holdt op med at gå med den, fordi han en dag på arbejde havde hængt i med den og derfor skønnede, at det var for farligt, med det arbejde han havde, at gå med den."}, {"type": "para", "text": "Forretninger var der en del af i 1973: Brugs, bager, købmand, slagter, to frisører, barber, mekaniker, karosserifabrik, flere tømrerfirmaer, elektriker, murer, cykelværksted, vognmandsforretning, køreskole, apotekudsalg og bank."}]}, {"title": "Venner", "blocks": [{"type": "para", "text": "På trods af den uheldige figur, jeg havde gjort Skt. Hans Aften, fik vi hurtigt en vennekreds i Spørring. Den kom til at bestå af Eva og Leo i nr. 19, som flyttede ind samtidig med os, Kirsten og Erik (Maler) i nr. 21 og Alice og Reinholt i nr. 28. Senere kom der flere til. Den første aften, vi var sammen med sidstnævnte par, var hos malerens, og det blev en virkelig sjov aften, hvor vi dansede på bordet og stillede kaffekopperne op ovenpå kerastjerne at kende, naboer til Alice og Reinholt. Villy spillede i Centralværkstedets Orkester, og det hændte, at vi tog med til koncerter. Vi havde dog stadig vennerne i Nordjylland, deriblandt Inga og Poul, hvis bryllup vi var til den 18. september 1971 i Tårs Forsamlingshus. Det var en flot fest med brudepige og –svend, langt slæb, kjole og hvidt og høj hat. Poul havde fået en stilling som forvalter på Isgård på Djursland, men for at få stillingen krævede de, at han var gift. Vi havde mange gode og sjove stunder sammen med Inga og Poul i deres nye bolig, men desværre holdt ægteskabet ikke ret længe. De flyttede til Ravnshøje ved Frederikshavn, hvor vi under et besøg i efteråret 1972 fik at vide, at de skulle skilles. Det var sidste gang, vi så Inga. Selvom hun sagde, at vi skulle ses, henvendte hun sig aldrig mere. Jeg var i starten meget skuffet, fordi jeg betragtede hende som en af mine bedste veninder. Hun havde inden bruddet fundet sig en anden fyr, en gift mand med tre børn. Senere hørte vi, at det var danmarksmesteren i bueskydning, Arne Jacobsen, som var noget ældre end hende. Vi holdt forbindelsen til Poul, som heldigvis senere fandt Anne Marie, og vi kom til Pouls andet bryllup i 1979. I 70erne blev hvert 4. par skilt."}, {"type": "figure", "caption": "Til fest hos Malerens. Kirsten siger skål. Ved siden af hende sidder", "page": 90, "file": "assets/images/p090_090.jpg", "dim": [860, 581]}]}, {"title": "Fester m.m", "blocks": [{"type": "para", "text": "Vi var med til mange fester på Østervang de første mange år, vi boede i Spørring. Ofte var det sammenskudsgilder, hvor værtsparret lavede maden og gæsterne kom med de våde varer. Der blev altid danset lystigt sådanne aftner (se forrige afsnit)."}, {"type": "figure", "caption": "Her er Vagn omsværmet af Alice og Kirsten", "page": 91, "file": "assets/images/p091_091.jpg", "dim": [860, 689]}, {"type": "para", "text": "Et eksempel på en fest, vi holdt, var den 9. juni 1973, hvor vi havde inviteret Vagns søskende fra Svenstrup, foruden Alice og Reinholt, Kirsten og Erik og Eva og Leo. Menuen stod på tarteletter med hønsesalat, wienerschnitzel og sherryfromage. Til natmad fik vi suppe, og jeg havde selv lavet melboller. Det var alle tiders fest. Eva og Leo gik kl. 3.30. Derefter fik vi besøg af vores genbo Kalle. Lidt senere gik Alice og Reinholt. Kl. 4.30 gik Kirsten, Erik, Vagn, Tage, Kalle og jeg ned på Hotellet og fik kaffe. Kirsten, Erik og jeg gik hjem kl. 5.30, hvorefter jeg ryddede op og gjorde huset rent Her er Vagn omsværmet af Alice og Kirsten til næste dag, hvor mine svigerforældre skulle komme på besøg. Tage kom hjem kl. 6, men Vagn og Kalle blev siddende, indtil Else (Kalles kone) og jeg hentede dem kl. 8.30. Jeg var ikke i seng den nat, men huset skinnede, da Vagns forældre kom, og det var det vigtigste for mig. Men kors, hvor var jeg træt!"}, {"type": "para", "text": "Vi var ofte i byen eller havde gæster til kaffe en hverdagsaften, også helt spontant. Eva kunne ringe og sige, at hun havde bagt en kage og om vi da ikke lige kiggede over. Det var hyggeligt og meget uformelt. Det samme kunne de andre venner også finde på, også til en søndagsfrokost, men så røg der nogle snapse ned, nogle gange nok til, at vi begyndte at danse midt om eftermiddagen. 1973 var også året, hvor vi startede med at brygge vin sammen med Eva og Leo. Vi købte ingredienserne hos materialisten og havde en stor ballon stående i et skab i bryggerset. 3 uger tog det at brygge vinen, så var den klar til brug. Men forinden skulle den smages til, og det foregik i bryggerset. Problemet var, at den liflige drik smagte af saftevand, så det var nemt at få en lille skid på."}]}, {"title": "Familie", "blocks": [{"type": "para", "text": "Mine forældre var stolte af deres svigersøn, og de kom godt ud af det med hans forældre. Der var gensidig respekt, og far og Chr. Viggo havde fælles interesser inden for landbruget. På mange områder var mine forældre mere moderne end Vagns, men de var jo også yngre. Mor accepterede ikke, hvis vi var flere timer i Vestergård end hos dem. Så var der sure miner at spore. Vi forsøgte så godt vi kunne at fordele sol og vind lige, endda mest til mors fordel, for Vagns mor var ikke vanskelig."}, {"type": "para", "text": "Vi synes selv, at vi var flinke til at køre nordpå i weekenderne og besøge familien – næsten hveranden weekend. Det foregik ofte på den måde, at vi ankom til Thorshøj fredag aften og var der til søndag morgen, for mormor skulle også have et besøg, og så tilbragte vi søndagen i Vestergård og kørte hjem kl. 22 om aftenen."}, {"type": "para", "text": "Ofte skulle der hjælpes til med det ene og det andet, som fx i januar 1973, hvor Vagn moderniserede gangen i Vestergård, og i marts samme år, hvor Vagn og Tage byggede løsdriftsstald. Og i høsten var alle mand hjemme for at hjælpe til – dog mindes jeg ikke at have bidraget med noget i den forbindelse. Jeg følte mig ofte dum, fordi jeg ikke selv var født op ude på landet, og hvis jeg en enkelt gang forvildede mig ud i stalden, kunne Tage finde på at fortælle mig, hvad der var grise og hvad der var køer. På en spøgefuld måde, naturligvis, så jeg tog ikke anstød af det. En enkelt gang prøvede jeg at køre traktor for at vise lidt interesse, men det var vist ingen succes."}, {"type": "para", "text": "Vagn fik altid betaling for at hjælpe til i Vestergård, og vi fik alt det kød, vi ville have, både svinekød, kalvekød og fjerkræ, foruden æg, som Krista havde som sin egen forretning. Men os tjente hun ikke meget på."}]}, {"title": "Dødsfald i familien", "blocks": [{"type": "para", "text": "Morfar, som jo var en livlig mand, blev mere og mere stille med årene, og juleaften 1969 var han meget stille. Han huskede heller ikke så godt mere. Han havde glemt, at han havde givet mor penge til at købe en dug til mormor, så han havde lagt en pengegave under træet til hende. Om foråret blev han syg og indlagt på Dronninglund Sygehus, hvor Vagn og jeg besøgte ham nogle gange. Hans hjerte var simpelthen slidt op. Til sidst ville mor ikke have, at jeg så, hvor syg han var, så vi var der ikke, da han døde. Hun ville skåne mig, men jeg ville gerne have været der, for jeg var morfars pige. Jeg græd meget, den dag mor ringede og fortalte, at han var død. Det var den 31. marts 1970, og da mor og far forlod hospitalet om natten, kørte de hjem i snestorm. Nu var mormor alene, men det klarede hun ret godt, og til begravelsen stod hun op og holdt tale. Alle havde troet, at mormor ville dø først på grund af hendes dårlige hjerte, som jo senere viste sig at være en sammenklappet lunge!"}, {"type": "para", "text": "Tre år senere kom turen til farmor. Den 5. maj 1973 ringede mor og fortalte mig, at farmor havde kræft. Hun blev indlagt med en svulst i maven, men da de lukkede hende op den 17. maj og troede, at de skulle operere hende, var kræften så fremskreden, at de ligeså stille lukkede hende igen. Vagn og jeg besøgte hende den 12. maj og igen den 3. juni. Hun var meget bleg, som hun lå der i den hvide at snakke om. Vi vidste jo alle, inkl. hende selv, hvor det bar hen. Vi snakkede om det forestående bryllup, og jeg husker, at hun sagde: ”Merete, det kommer jeg ikke med til”. Jeg lovede hende, at vi ville besøge hende, når vi kom fra kirke, og det blev hun glad for. Da de ikke kunne gøre mere for hende på sygehuset, kom hun hjem til faster Grethe i Mellergård, hvor hun blev passet og plejet godt til sin død den 9. juli 1973. Vi havde været nervøse for, om det skulle ske lige op til vores bryllup den 28. juli. Mor og jeg havde aftalt, at hvis farmor stadig levede, ville Vagn og jeg besøge hende efter kirken, så hun kunne se os, for hun kunne under ingen omstændigheder klare at være med til festen. Men dette blev ikke aktuelt. Under vores ferie i Norge med mor, far og Per fik vi beskeden, at farmor var død, og vi tog straks hjem, lidt før planlagt. Farmor blev begravet to uger før vores bryllup fra den samme kirke, nemlig Skæve Kirke."}, {"type": "figure", "caption": "Mormor hjemvendt fra USA. På billedet ses desuden", "page": 92, "file": "assets/images/p092_092.jpg", "dim": [860, 576]}, {"type": "para", "text": "Det var hårdt at miste sine bedsteforældre, men heldigvis havde vi stadig mormor, og selvom hun altid havde virket svagest, vel nok på grund af åndedrætsbesvær og tendens til nemt at blive forpustet, var hun alene i 22 år. I 1971 tog mormor sammen med morfars søster Bertha en tur til USA. Der besøgte hun de tre svogre med familier, og det var en stor oplevelse for hende. Det værste ved turen var, at hun skulle dele seng med Bertha og ligge under samme lagen. Jeg husker hende fortælle, at Bertha sådan svedte om natten, ”og så trillede den lille fede klump hen under mig” (Bertha var lille og buttet). Det må have været et syn for Guder, hvis man blot havde været en flue på væggen. Mormor var god til at få tiden til at gå. En af hendes helt store beskæftigelser var håndarbejde. Hun broderede metervis af klokkestrenge, vægtæpper, bordløbere, dækkeservietter m.m. Ofte syede hun på bestilling, når familiens venner så, hvad der lå og hang af fine håndarbejder rundt omkring. Således syede hun fx 5 bjørnekløer (store vægtæpper), flere fødselsdagsløbere og stamtræer, foruden at hun hæklede massevis af mundservietter og hagesmækker. Hun sad altid ved spisebordet og broderede, for så kunne hun kigge ned i byen og ud på gaden og følge med i bybilledet."}]}, {"title": "Ferier", "blocks": [{"type": "para", "text": "Mor havde altid været bidt af Norge, sikkert fordi hun som 14-årig fik en penneveninde derfra. Agathe var fra Lillestrøm og var datter af en læge, og jeg hørte som barn og ung meget om hende og hendes forældre, hr. og fru Bjørnstad, og senere om hendes mand Harald."}, {"type": "para", "text": "Første gang, vi var på ferie sammen med mor, far og Per i Norge, var i efterårsferien 1971, hvor vi pakkede fars blå Ford Taunus og kørte til Blestølen i Telemarken. Der havde vi lejet en hytte i en uge. Der var læs på Forden, for mor havde al maden med – det var for dyrt at købe i Norge. Vi havde en pragtfuld uge, hvor vi råhyggede os og var ude i den flotte og kolde natur."}, {"type": "para", "text": "Den 30. juni 1973 tog vi sammen med mor, far og Per på ferie i Gudbrandsdalen i Norge. Vi stod op midt om natten for at sejle fra Frederikshavn til Göteborg kl. 6.30. Næste dag ankom vi til Dovre Motell, hvor vi havde lejet en hytte lige ned til en elv. Her kunne mændene gå ned med deres fiskestænger og sidde i timevis uden at få bid. Far var ikke særlig god til at fiske, men han nød at sidde med sin pibe lige så stille og vente på, at fiskene skulle bide på. Det gjorde de ikke så tit hos ham som hos Vagn, men det tog far ikke så tungt. Den dag, Per fangede sin første ørred, kunne det høres i miles omkreds, for han kom løbende, alt imens han råbte: ”Jeg har fanget en fisk, jeg har fanget en fisk!” Også far havde held et par gange, og Vagn fangede nogle stykker, så det blev til flere gode måltider. Vi besøgte bl.a. Dombås, Dovregubbens Hal, Oppdal, Fosdal, Grimsdalen, nogle af stederne sammen med Vibeke, Elbo og børnene, som lå på en campingplads i nærheden noget af tiden. Vi fik også tid til at lave bordplan til brylluppet. En dag kørte vi en lang tur på 400 km. til Romsdalen, Slettefossen, Åndalsnes og Trollstigan med hårnålesving. Vi så Trolltinderne, Gudbrandsjuvet og kørte gennem Valldal til Linge, hvor vi tog færgen over til Eidsdal. I Geiranger gik vejen atter opad, og vi så sne, sne og atter sne (Dalsnibba 1000 m.o.h.). Det var en fantastisk natur, Norge havde at byde på. Da vi kom hjem om aftenen, lå beskeden om farmors død. Vi rejste hjem den 12. juli."}, {"type": "para", "text": "Første gang, jeg mødte Agathe og hendes familie var i sommeren 1975. Da var vi også på ferie i Norge (Valdres) med mor, far og Per og gjorde på turen opad ophold i Lillestrøm hos Bjørnstads, hvor Agathe var hjemme med mand og tre børn. Vi spiste frokost der, og jeg husker, at vi bad bordbøn, for Bjørnstads var kristne mennesker. Af samme grund blev der serveret ingefærøl for mændene. Efter frokosten nød vi i det pragtfulde vejr kaffen i den dejlige have med de store birketræer. Agathes børn hed Cecilie, Anders og Cathrine, og de var vel mellem 1½ og 6 år og meget søde. Cecilie kastede straks sin kærlighed på far, ligesom mange andre små børn, på trods af, at han ikke gjorde noget for at tiltrække dem. Børn syntes altid, at far havde en mærkelig hånd, og så kunne han vrikke med ørerne."}, {"type": "para", "text": "Det blev til mange flere møder mellem mine forældre og Agathe, Harald og Bjørnstads, enten i Norge eller Danmark. Bjørnstads havde en hytte, som mor og far lånte flere gange sammen med Vibeke og Elbo. Venskabet med Agathe og Harald varede ved til mors død i 1993."}]}, {"title": "Fritidsaktiviteter", "blocks": [{"type": "para", "text": "Under studierne var det ikke blevet til mange fritidsaktiviteter, kun lidt volleyball, som jeg gik til en enkel vinter sammen med min studiekammerat Anna Marie. Håndbolden var lagt på hylden, så nu måtte jeg finde på noget andet. I Spørring var der en gammel gymnastiksal, hvor man kunne spille badminton, og det begyndte vi så på begge to kort tid efter, vi var flyttet dertil. Vi spillede sammen med Alice og Reinholt, enten single eller double, og det gav god motion. Alice og jeg fortsatte makkerskabet i mange år, også turneringskampe, og vi spiller stadig en gang om ugen."}, {"type": "para", "text": "Vagn var fodboldspiller på Jyllandsserieholdet, da jeg mødte ham, men da han flyttede fra Tårs, måtte han desværre vinke farvel til den karriere. Han har mange gange spøgefuldt sagt, at det var min skyld, han måtte droppe fodbolden. I Spørring havde de også fået øje på ham, når han spillede gadekampe til byfesterne. De kunne godt se, at han var en habil fodboldspiller, og i starten, vi boede i Spørring, fik de ham da også overtalt til at gå med. Det blev en kort fornøjelse, for han indså, at det ville gå ud over vores weekends, hvor vi ofte drog nordpå til forældre og venner."}]}, {"title": "Bryllup den 28. juli 1973", "blocks": [{"type": "para", "text": "I mor og fars korridor stod der en kiste, som morfar havde lavet. Mens jeg boede hjemme, blev den brugt til mit udstyr, og når der kom gæster, og snakken faldt på bryllup og udstyr, blev kisten åbnet og herlighederne vist frem: der var fine vævede ting fra Kolding Hør med indgraveret navn (Merete Møller) – sengelinned, viskestykker og håndklæder. Der var broderede dækkeservietter og mellemlægsservietter, pudevår med mellemværk og monogram, som jeg selv havde broderet på aftenskole, duge med hardangersyning, som jeg også havde syet på kursus. Hvad det angik, var jeg et godt parti. Og så var der jo mokkakopperne, sølvtøjet (Cheri), det brune riflede keramik te stel og meget mere."}, {"type": "para", "text": "Da datoen for brylluppet var bestemt og indbydelserne sendt ud et par måneder før, kunne forberedelserne begynde. Den 2. juni var mor og jeg i Ålborg for at se på brudekjole, men de havde ingen i str. 36. Brudekjolen blev købt i Dybvad samme dag og skulle kun forandres lidt. Den var meget sommerlig og i mol med kort slør Prisen var 250 kr. Skoene købte jeg for de 1-ører, jeg havde sparet sammen i årenes løb. Det var meget brugt dengang at samle på 1-ører til brudesko. Vagns tøj købte vi i Århus den 22. juni, og da det skulle være et sommerbryllup og vi var praktisk anlagt, syntes vi, at habitten skulle være lys og skjorten mørkebrun, så han kunne bruge det bagefter og ikke kun den ene gang. Men her begik vi en stor fadæse. Da vi kom hjem til Vagns mor og viste hende tøjet, trådte hun for en gangs skyld i karakter over for os. ”Hvad tror I, Bedstemor vil sige, hvis du kommer i en brun skjorte?” var hendes kommentar. Skjorten blev byttet til en hvid, og det var godt det samme. Habitten faldt i god jord. Heldigvis var vi i god tid med at få bukserne lagt op, for det viste sig, at det ene ben var kortere end det andet, da de kom fra skrædderen."}, {"type": "para", "text": "Festen, hvortil der var inviteret 72 gæster, blev betalt af mine forældre og skulle holdes i Lendum Forsamlingshus, som vi havde bestilt den 23. april. Det var kun de nærmeste i Vagns familie, der var inviteret med, samt den ældste onkel og nogle få venner, for aftalen var, at der 2 uger efter brylluppet skulle holdes et stort efterbryllup i Tårs Forsamlingshus med 110 indbudte, betalt af Vagns forældre. Vi regnede åbenbart med at få mange gaver."}, {"type": "para", "text": "Brudebuketten blev bestilt hos gartneren i Hørby, og selvom det var brudgommen, der skulle betale den, tror jeg ikke, han var med til at bestemme noget som helst. Det ordnede mor og jeg. Det blev røde roser, hvide margueritter og 2 orkidéer."}, {"type": "para", "text": "Vi fik lavet en takkesang hos en dame i Århus. Jeg hentede den d. 18. juli. Den var trykt på lyserødt papir og gik på melodien ”I skoven skulle være gilde”: En strøm af glade gæster fra både fjern og nær er kommet nu til bryllupsfest i dette skønne vejr. Vi sammen nu vil feste i gode venners lag, vi vil som brudepar med tak erindre denne dag, den er for vor familie en rigtig hjertesag."}, {"type": "para", "text": "Med sådanne forældre som brudeparret har, er vejen fremad banet, så den synes lys og klar, problemer fejes bort, så det hele bli’r en leg, vi ved, at I forkæler os, sig ind imellem nej! Nu må vi vise, hvad vi kan, for ellers går det ej!"}, {"type": "para", "text": "En dejlig tur i Norge blev nydt i fulde drag, imens Meretes mor gardiner syed’ fag for fag, med flid og lyst har far huset malet overalt, ja, hjælpen altid var parat før nogen havde kaldt, og interesse viste I, da møbler der blev valgt."}, {"type": "para", "text": "Og Doris og Poul Erik med huset tog et nap, ja, der var travlhed overalt, man næsten løb om kap, og selv om også Tage er smed af profession, så kan han tømmerere, han er fermere end no’n, med Vagn som makker blev det til en faglig præstation."}, {"type": "para", "text": "Hos Vagns forældre har man i reglen høns på is, Merete talte om, at hun på disse satte pris, at fryseren var tom, talte svir’mor ikke om, en høne af de levende fik ho’det drejet om, med denne høne grydeklar til eget hjem hun kom."}, {"type": "para", "text": "Af lyse barneminder så mange dukker frem, i Skæve by var mormors hus et dejligt feriehjem, de mange søde sager, som mormor havde der, de for Merete stadig står i eventyrets skær, for mormor og Merete er de minder meget værd."}, {"type": "para", "text": "En dejlig gård på landet, som mange drømmer om, en sådan gård er virk’lighed, fra denne Vagn jo kom, og når fra dagligt ræs han besøger denne gård, han nyder her at hjælpe til, enhver nok det forstår, ja, længslen efter gården bli’r forstærket år for år."}, {"type": "para", "text": "Vi håber, at I fremtidigt gæster os lidt mer’, besøg os bare oftere, det gælder også Per, utallige beviser på gavmildhed vi har, en tak til mor og svigermor, til far og svigerfar, et brudepar nu ønsker, I skal ha’ et højt hurra!"}, {"type": "para", "text": "Endelig oprandt den store dag, og vi havde naturligvis tilbragt natten hver for sig hos vores respektive forældre. Jeg vågnede allerede kl. 4.30, men først kl. 6.30 stod jeg op til en strålende solskinsdag, der skulle blive meget varm og meget minderig. Vi drak morgenkaffe i haven, og vi frydede os, for vi havde lavet noget af en satsning ved at invitere alle 72 gæster hjem i haven til kaffe efter kirken. Hvad skulle vi have gjort, hvis det havde regnet? Der var allerede kommet nogle gaver, og dem pakkede jeg op. Der blev sikkert rigeligt at pakke op senere. Kl. 9.45 skulle jeg til damefrisør Lissy i Thorshøj, som også skulle pynte mig senere sammen med Kirsten, som boede overfor. Efter at have været ved frisør kørte jeg til Hørby efter to buketter blomster, som jeg kørte på kirkegården med. Kl. 14 kom Lissy og Kirsten og pyntede mig i køkkenet, og kl. 15.30 kørte far og jeg til Skæve Kirke. Det var et stort øjeblik, da dørene gik op og jeg fulgtes med far op ad kirkegulvet, op til min elskede, der stod sammen med sin far og tog imod. Da han kyssede mig, bemærkede jeg, at han da vist ikke var helt nybarberet, men flot var han i sin lyse habit og hvide skjorte! Jeg tror også, at far var stolt, da han fulgte mig op ad kirkegulvet."}, {"type": "figure", "caption": "", "page": 96, "file": "assets/images/p096_093.jpg", "dim": [626, 625]}, {"type": "para", "text": "Vagns formiddag havde været noget anderledes end min. Dengang var der ikke decideret noget, der hed polterabend, men der var tradition for, at gommen skulle have nogle øl sammen med vennerne. I dette tilfælde blev det sammen med bror, svoger og naboen Anders, og det foregik om formiddagen i haven. Der blev slæbt en hel kasse øl ud på græsplænen, men det syntes Chr. Viggo var lige groft nok, så han bar den ned i kælderen, hvorefter Vagn hentede den op igen. Dumme hvalp! De nåede vist at kvæle nogle stykker. Måske derfor var der ikke blevet ordentlig tid til barbering."}, {"type": "para", "text": "Men der sad vi så i kirken og skulle være mand og kone. Det var en fantastisk fornemmelse, og alle vores venner og familie var samlede for at fejre begivenheden med os. Jeg husker ikke mere præstens ord, og jeg kendte ham heller ikke, for han var ferieafløser, men vi var bare så lykkelige. Det var også hyggeligt bagefter i mor og fars have. Jens Erik Skræm Pedersen var der for at fotografere os. Det foregik i stuen, for så var vi fri for at bruge tid på at skulle til fotografen. Han havde også været med ved kirken og fulgte med til Lendum senere. Vi fik hilst på og snakket med alle gæsterne i Thorshøj og kørte kl. 17.30 til Lendum, hvor festlighederne skulle fortsætte. Vi pakkede gaver ud til kl. 18.30, hvorefter vi gik til bords. Menuen bestod af suppe, ananas med høns i mayon- Far og datter i Skæve kirke Et lykkeligt brudepar d. 28.7.1973 naise, svinekam med grøntsager og islagkage. Der var 6 sange og 6 taler. Vi havde en velkomstsang på melodien: ”Den evigglade kobbersmed”. Sangen fra mor og far gik på melodien ”Lille sommerfugl”, og sangskjulerne var en fodbold og en skoletaske. Sangen fra Vagns familie gik på to melodier: ”Vi er børn af sol og sommer” og ”Vi skal gå hånd i hånd”. Sangskjulerne var en høvl og en kagerulle. Sangen fra mormor og mors familie (lavet af Moster) gik på melodien ”Vi skal gå hånd i hånd”, og sangskjuleren var en kurv. Sangen fra Per gik på melodien ”Skorstenfejeren gik en tur”, og sangskjuleren var en fiskestang. Elbo og Vibeke havde en sjov sang med på melodien ”Se Norges blomsterdal”, og til sidst kom vores takkesang. Jeg husker ikke alle talerne, men vores fædre holdt tale, og Maltha, som traditionen tro startede med de kendte ord: ”Ja, jeg er jo ikke den store taler”. Derudover tror jeg, at Edith Lie (Vagns forældres genboer) holdt tale foruden Martin Andersen (Pouls far) og Onkel Alfred. Kl. ca. 22 dansede vi brudevals, hvorefter mit slør blev revet i stykker. Det var der tradition for dengang, og det betød lykke. Udover papirsbilleder blev der taget smalfilm. Det stod Knud for. Normalt var det ellers onkel Ib, der tog smalfilm ved festlige lejligheder, men Knud havde anskaffet sig udstyret og ville gerne stå for den del af festen. Jeg er glad for, at han filmede mig, mens jeg dansede med far. På et tidspunkt, hvor jeg i et kort øjeblik stod og beundrede gavebordet sammen med nogle af gæsterne, kom far hen til mig og sagde: ”Du skal huske at danse med Vagn fra Ålbæk, for han har vel nok læst mange godnathistorier for dig.” Det var jeg glad for, at han sagde, og jeg gik straks hen og bød Vagn op. Han havde jo været kommis i Brugsen og ham og hans kone Grethe var en del af mor og fars vennekreds. Desværre døde han få år senere af kræft."}, {"type": "figure", "caption": "Et lykkeligt brudepar d. 28.7.1973", "page": 97, "file": "assets/images/p097_094.jpg", "dim": [591, 860]}, {"type": "figure", "caption": "Far og datter i Skæve kirke", "page": 97, "file": "assets/images/p097_095.jpg", "dim": [582, 860]}, {"type": "figure", "caption": "Mor og Far", "page": 98, "file": "assets/images/p098_096.jpg", "dim": [860, 607]}, {"type": "figure", "caption": "Krista og Chr. Viggo", "page": 98, "file": "assets/images/p098_097.jpg", "dim": [860, 604]}, {"type": "para", "text": "Mor og Far Krista og Chr. Viggo Mormor og Per Jens Christian og Doris Charlotte (som var sløj) og Poul Erik Erik og Tage (de to ungkarle) Dansen fortsatte til kl. 2, hvor vi forlod festen. Mor havde syet risposer med lyseblå bånd, så der blev kastet ris, da vi skulle af sted. Da var nogle af gæsterne begyndt at tage hjem. Det var en rigtig dejlig fest, som vi var kede af at forlade, men vi havde bestilt værelse på Hotel Phønix i Hjørring. I forvirringen over, hvilken bil vi skulle køre i, da vi skulle derfra, fik jeg ikke min taske med p-piller med, og da jeg var meget påpasselig med at tage dem, fordi jeg i hvert fald ikke skulle være gravid, før jeg var færdig med min uddannelse, måtte jeg ringe fra hotellet til Vestergård og bede Poul Erik køre til hotellet midt om natten med mine p-piller. Vagn var efterhånden blevet lidt halvsnalret, så da han skulle låse op ind til vores værelse, tog han fejl af værelset og linnedrummet. Ikke så sært, at han døjede med at låse op. Bryllupsnatten var ikke specielt romantisk, for inden jeg nåede at komme i seng, snorkede gommen det bedste, han havde lært. Men vi havde jo også boet sammen i ca. 3 år forinden. Det blev en dyr nat – 150 kr. for at sove i 4 timer. Men så der var også morgenmad med i prisen. I morgengave gav jeg Vagn en fiskestang, som lå og ventede på ham hjemme i Spørring, og jeg fik et guldsmykke i en kæde."}, {"type": "figure", "caption": "Mormor og Per", "page": 98, "file": "assets/images/p098_098.jpg", "dim": [860, 599]}, {"type": "figure", "caption": "Jens Christian og Doris", "page": 98, "file": "assets/images/p098_099.jpg", "dim": [860, 584]}, {"type": "figure", "caption": "Charlotte (som var sløj) og Poul Erik", "page": 99, "file": "assets/images/p099_100.jpg", "dim": [860, 605]}, {"type": "figure", "caption": "Erik og Tage (de to ungkarle)", "page": 99, "file": "assets/images/p099_101.jpg", "dim": [860, 605]}, {"type": "figure", "caption": "Vagns Bedstemor, hans Onkel Peter og Tante Emma", "page": 99, "file": "assets/images/p099_102.jpg", "dim": [860, 626]}, {"type": "figure", "caption": "Tante Karen og Onkel Alfred", "page": 99, "file": "assets/images/p099_103.jpg", "dim": [860, 579]}, {"type": "figure", "caption": "", "page": 100, "file": "assets/images/p100_104.jpg", "dim": [821, 860]}, {"type": "para", "text": "Næste dag var Vagns familie inviteret til frokost i Thorshøj, og mormor, Helge, Tove og Erik kom til eftermiddagskaffe. Det blev endnu en dejlig og varm dag, hvor vi drøftede festen og beundrede gaverne. Vi fik en kobbergryde af Per, et polsk vægtæppe af mormor, 2 tinlysestager af Vagns bedstemor, Kysepigen i porcelæn af Vagns søskende, gæstebog af Charlotte og Jens Christian (broderet af Doris), bestik, adskillige messinglysestager, fade, gulvvase, flere kobbergryder, kopper og tallerkner i Henning Koppel, som vi samlede på, keramikfade og –skåle, keramiklampe af mors søskende, stor morter, krystalskål, duge, Margrethe skål, dækkeservietter, skibsglas, kongelig figur, kagefad, kagerulle, rustfrit fad og skål, æggebægre, lagkagekniv, salatskål, gratinfad, ildfast fad, krukke, gryder, salt- og peberkværn, keramikaskebæger, vægstage, tehætte, tinkrus, glasskål og salatsæt, havegrill, glasvase, årskrus, 3 blomster, 3 buketter, 25 $ fra Margaret og Martinus i USA og andre pengegaver, i alt 2.895 kr., deraf 2000 kr. af Vagns forældre. Af mor og far fik vi festen, og den var vi glade for. Vi sendte takkekort med billede ud til alle, der havde tænkt på os."}, {"type": "figure", "caption": "Mor, Per, Merete og Mormor", "page": 100, "file": "assets/images/p100_105.jpg", "dim": [788, 624]}, {"type": "para", "text": "To uger senere iførte vi os bryllupstøjet igen (minus slør), og vi holdt en fantastisk god fest i Tårs Forsamlingshus for 110 gæster, hovedsagelig Vagns store familie (hans far havde 11 søskende og hans mor 2), naboer og venner, men også de af mor og fars venner, som havde givet gaver var inviteret med. Mormor blev placeret ved siden af Martin Andersen (Martin og Inger var også med på selve dagen), og hun havde en vældig aften, for Martin var ikke kedelig. Bordene stod som til brylluppet (med hovedbord), og der blev sunget og holdt taler. Kl. 24 blev der sunget fødselsdagssang for Mor, Per, Merete og Mormor Vagn, som fyldte 25 år."}, {"type": "para", "text": "Bryllupsrejsen blev udsat til januar 1974, hvor vi sammen med Tage tog to uger til Marokko."}]}, {"title": "Historiske begivenheder", "blocks": [{"type": "para", "text": "5.3.1966 500.000 danskere får folkepension. 18.3.1966 Osvald Helmuth dør, 71 år. 6.9.1966 Licensen for fjernsyn og radio stiger med 25 kr. årligt til 210 kr. 8.9.1966 144 passagerer og besætningsmedlemmer reddes fra færgen ”Skagerrak”, der springer læk 40 sømil nordvest for Hirtshals.", "page": 100}, {"type": "para", "text": "4.10.1966 Tronfølgeren forlover sig med Henri Laborde de Monpezat, 3. sekretær ved den franske ambassade i London. 15.3.1967 Prinsesse Benedikte forlover sig med prins Richard fra Berleburg i Tyskland. 21.4.1967 Militærjunta tager magten i Grækenland. 11.5.1967 Danmark og England anmoder om optagelse i EF. 10.6.1967 Tronfølgerens bryllup med grev Henri, der udnævnes til Prins Henrik af Danmark. 16.6.1967 Københavns 800-års jubilæum fejres bl.a. med verdens længste kaffebord på Strøget. 3.7.1967 Moms på 10 % indføres. 18.7.1967 DRs første tv-udsendelse i farver – kan kun ses på Sjælland. Kun få har købt farve-tv. 29.9.1967 Der indføres postnumre. 31.12.1967 Den græske kongefamilie flygter til Rom efter kong Konstantins mislykkede kup mod militærjuntaen. 3.2.1968 Prinsesse Benedikte og prins Richard vies i Fredensborg. 21.2.1968 Skuespilleren Gunnar Lauring dør, 63 år. 11.3.1968 Momsen forhøjes til 12½ %. 4.4.1968 Den amerikanske negerleder Martin Luther King myrdes. 19.4.1968 Poul Reumert dør, 85 år. Det danske studenteroprør bryder ud. Studenterne besætter Psykologisk Laboratorium ved Københavns Universitet. 27.5.1968 Gruppen ”Savage Rose” debuterer. 5.6.1968 Den amerikanske præsidentkandidat Robert Kennedy myrdes. 10.6.1968 CPR-numre indføres ved lov. 6.11.1968 Richard Nixon vælges til USAs præsident. 24.6.1969 Folkeafstemning om valgret til de 18-årige. Flertal af nej-stemmer. 20.7.1969 De amerikanske astronauter Armstrong og Aldrin på månen. 8.12.1969 Der er nu ca. 20.000 fremmedarbejdere i Danmark. 12.1.1970 Kildeskatten indføres i Danmark. 9.3.1970 Studenterne besætter universitetet i protest mod den nye styrelseslov. 1.4.1970 Fuld folkepension til alle over 67. 15.5.1970 Lov om 5-dages uge i folkeskolen efter sommerferien. 2.6.1970 Momsen forhøjes til 15 %. 30.1.1971 Mogens Glistrup ophidser nationen ved at sammenligne skattesnydere med krigens frihedskæmpere. Oplyser senere, at hans egen skatteprocent er 0. 12.2.1971 Narkopolitiet skønner, at der indsmugles og ryges to tons hash om måneden. 26.2.1971 Salget af flaskemælk ophører i København. 24.3.1971 Arkitekten Arne Jacobsen dør. Mit bestik var designet af ham. 6.7.1971 Louis Armstrong dør. Sommer 71 Christiania besættes og proklameres fristad. Bekender sig til fri hash, bilfri by og fælles ejendomsret. 13.9.1971 Trafikminister A.C.Normann påkører under overhaling en bil. To mister livet, tre bliver kvæstet. 21.9.1971 Ved folketingsvalget mister VKR-regeringen flertallet og afløses af en socialdemokratisk mindretalsregering under J.O.Krag. 7.1.1972 Bodil Koch dør. 10.1.1972 Aksel Larsen dør. 14.1.1972 Frederik IX dør 15.1.1972 Statsminister J.O.Krag udråber Dronning Margrethe på Christiansborg Slot, i bidende frost og for øjnene af 50.000 mennesker. Den første socialdemokrat, der udråber den første arveberettigede og folkevalgte dronning i landet. 22.1.1972 J.O.Krag underskriver EF-traktaten i Bruxelles. 22.3.1972 Skolepligten udvides fra 7 til 9 år. 4.7.1972 Den første Nordsøolie bringes i land. 22.8.1972 Mogens Glistrup stifter Fremskridtspartiet. 1.9.1972 Det nye universitetscenter RUC ved Roskilde starter med 700 studenter. 5.9.1972 Palæstinensisk terroraktion mod israelske sportsfolk ved olympiaden i München. 7.9.1972 Folketinget vedtager Danmarks indtræden i EF med 141 stemmer for og 34 imod. 2.10.1972 Flertal for dansk medlemskab af EF ved folkeafstemningen i Danmark. 1.958.043 sagde ja, 1.135.775 sagde nej. 3.10.1972 Jens Otto Krag indgiver sin afskedsbegæring. Som hans efterfølger udpeges Anker Jørgensen til statsminister og partiformand. 18.1.1973 Tom Bogs vinder EM-titlen i mellemvægt ved at besejre franskmanden Bettini. 18.2.1973 Demonstration i København for og imod fri abort. 22.2.1973 Letmælken har premiere. 21.3.1973 Største konflikt på arbejdsmarkedet siden 1936. 153.000 i strejke og 105.000 lockoutet. 1.4.1973 1- og 2-ørerne bliver ugyldige. Alle de 1-ører, jeg havde sparet sammen til brudesko, fik jeg derfor vekslet, inden de blev brugt. 21.5.1973 Voldsomme protester mod Jens Jørgen Thorsens planlagte Jesus-film. 24.5.1973 Folketinget vedtager loven om fri abort. 95 stemmer ja, 56 stemmer nej. 6.7.1973 40.000 kvindelige lønarbejdere under det offentlige opnår ligeløn. Jeg har valgt at slutte første del af mine erindringer her, men jeg håber, at jeg får tid og lyst til at skrive anden del i den nærmeste fremtid * Onkel Alfred døde den 16. juni 2006 og blev begravet den 24. juni. Vi var kun 20 til begravelsen i Skæve Kirke med efterfølgende kaffe på Dybvad Kro.", "page": 101}]}]}], "cover": ["assets/cover/c1.jpg", "assets/cover/c2.jpg", "assets/cover/c3.jpg", "assets/cover/c4.jpg", "assets/cover/c5.jpg", "assets/cover/c6.jpg", "assets/cover/c7.jpg", "assets/cover/c8.jpg", "assets/cover/c9.jpg"]};
